option.value:
//! Expression evaluation.

use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

use saule_ast::{BinOp, CallArg, Expr, LambdaBody, Spanned, Type};

use crate::env::Environment;
use crate::error::RuntimeError;
use crate::value::{ClassObject, FunctionBody, FunctionObject, InstanceObject, Value};

use super::{Flow, ops};

const SUPER_OWNER_BINDING: &str = "__saule_super_owner";

#[derive(Clone)]
pub(crate) enum EvaluatedArg {
    Positional(Value),
    Named { name: String, value: Value },
}

pub fn eval(expr: &Spanned<Expr>, env: &Rc<RefCell<Environment>>) -> Result<Value, RuntimeError> {
    let span = expr.span.clone();
    match &expr.value {
        Expr::Int(n) => Ok(Value::Int(*n)),
        Expr::Float(f) => Ok(Value::Float(*f)),
        Expr::Bool(b) => Ok(Value::Bool(*b)),
        Expr::Str(s) => Ok(Value::Str(Rc::new(s.clone()))),
        Expr::Nil => Ok(Value::Nil),

        Expr::Ident(name) => env
            .borrow()
            .get(name)
            .ok_or_else(|| RuntimeError::Undefined {
                name: name.clone(),
                span,
            }),

        Expr::Unary { op, rhs } => {
            let v = eval(rhs, env)?;
            ops::unary(*op, v, span)
        }

        Expr::Binary { op, lhs, rhs } => match op {
            // `and` / `or` short-circuit, so evaluate lazily.
            BinOp::And => {
                let l = eval(lhs, env)?;
                if l.is_truthy() { eval(rhs, env) } else { Ok(l) }
            }
            BinOp::Or => {
                let l = eval(lhs, env)?;
                if l.is_truthy() { Ok(l) } else { eval(rhs, env) }
            }
            // `??` short-circuits: only evaluate RHS when LHS is nil.
            BinOp::Coalesce => {
                let l = eval(lhs, env)?;
                if matches!(l, Value::Nil) { eval(rhs, env) } else { Ok(l) }
            }
            _ => {
                let l = eval(lhs, env)?;
                let r = eval(rhs, env)?;
                ops::binary(*op, l, r, span)
            }
        },

        Expr::Call { callee, args } => {
            // Dotted calls (`obj.method(args)`) and `self.super(args)` need
            // special handling so we can auto-bind `self` and route to the
            // parent constructor respectively. Saule lets instance methods
            // omit the explicit `self` parameter — see `call_instance_method`.
            if let Expr::Member { obj, name } = &callee.value {
                if name == "super" {
                    return super_call(obj, args, env, span);
                }
                let receiver = eval(obj, env)?;
                let vs = eval_call_args(args, env)?;
                return dispatch_member_call(&receiver, name, vs, span);
            }

            let cv = eval(callee, env)?;
            let vs = eval_call_args(args, env)?;
            call_value(cv, &vs, span)
        }

        // Postfix / composite forms — wait until later phases.
        Expr::Member { obj, name } => {
            let receiver = eval(obj, env)?;
            read_member(&receiver, name, span)
        }
        Expr::SafeMember { obj, name } => {
            let receiver = eval(obj, env)?;
            if matches!(receiver, Value::Nil) {
                Ok(Value::Nil)
            } else {
                read_member(&receiver, name, span)
            }
        }
        Expr::Index { obj, index } => {
            let receiver = eval(obj, env)?;
            let index_value = eval(index, env)?;
            read_index(&receiver, index_value, span)
        }
        Expr::MethodCall { obj, method, args } => {
            let receiver = eval(obj, env)?;
            let evaled = eval_call_args(args, env)?;
            invoke_method(&receiver, method, evaled, span)
        }
        Expr::ForceUnwrap(inner) => {
            let v = eval(inner, env)?;
            if matches!(v, Value::Nil) {
                Err(RuntimeError::ForceUnwrapNil { span })
            } else {
                Ok(v)
            }
        }
        Expr::Table(items) => {
            let mut values = Vec::with_capacity(items.len());
            for item in items {
                values.push(eval(item, env)?);
            }
            Ok(Value::Table(Rc::new(RefCell::new(
                crate::value::TableObject::from_array(values),
            ))))
        }

        Expr::Lambda { params, body, .. } => {
            let body = match body {
                LambdaBody::Expr(e) => FunctionBody::Expr(e.clone()),
                LambdaBody::Block(stmts) => FunctionBody::Block(stmts.clone()),
            };
            Ok(Value::Function(Rc::new(FunctionObject {
                name: None,
                params: params.clone(),
                body,
                closure: env.clone(),
            })))
        }

        Expr::Self_ => env
            .borrow()
            .get("self")
            .ok_or_else(|| RuntimeError::Undefined {
                name: "self".to_string(),
                span,
            }),
    }
}

fn first_or_nil(values: Vec<Value>) -> Value {
    values.into_iter().next().unwrap_or(Value::Nil)
}

pub(crate) fn eval_values(
    expr: &Spanned<Expr>,
    env: &Rc<RefCell<Environment>>,
) -> Result<Vec<Value>, RuntimeError> {
    let span = expr.span.clone();
    match &expr.value {
        Expr::Call { callee, args } => {
            if let Expr::Member { obj, name } = &callee.value {
                if name == "super" {
                    return Ok(vec![super_call(obj, args, env, span)?]);
                }
                let receiver = eval(obj, env)?;
                let vs = eval_call_args(args, env)?;
                return dispatch_member_call_multi(&receiver, name, vs, span);
            }

            let cv = eval(callee, env)?;
            let vs = eval_call_args(args, env)?;
            call_value_multi(cv, &vs, span)
        }
        Expr::MethodCall { obj, method, args } => {
            let receiver = eval(obj, env)?;
            let evaled = eval_call_args(args, env)?;
            invoke_method_multi(&receiver, method, evaled, span)
        }
        _ => Ok(vec![eval(expr, env)?]),
    }
}

/// Invoke a callable [`Value`]. Handles both native and user-defined
/// functions.
fn call_value(
    callee: Value,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(call_value_multi(callee, args, span)?))
}

pub(crate) fn call_value_multi(
    callee: Value,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    match callee {
        Value::Native(nf) => {
            let mut positional = Vec::with_capacity(args.len());
            for arg in args {
                match arg {
                    EvaluatedArg::Positional(v) => positional.push(v.clone()),
                    EvaluatedArg::Named { name: _, .. } => {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "named arguments are not supported for built-in function `{}` — use positional arguments instead",
                                nf.name
                            ),
                            span,
                        });
                    }
                }
            }
            (nf.func)(&positional)
                .map(|v| vec![v])
                .map_err(|message| RuntimeError::TypeError { message, span })
        }
        Value::Function(f) => call_function_multi(&f, args, span),
        Value::NativeClosure(nc) => {
            let mut positional = Vec::with_capacity(args.len());
            for arg in args {
                match arg {
                    EvaluatedArg::Positional(v) => positional.push(v.clone()),
                    EvaluatedArg::Named { name: _, .. } => {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "named arguments are not supported for built-in function `{}` — use positional arguments instead",
                                nc.name
                            ),
                            span,
                        });
                    }
                }
            }
            (nc.func)(&positional)
                .map_err(|message| RuntimeError::TypeError { message, span })
        }
        // `ClassName(args)` constructs an instance.
        Value::Class(c) => construct(c, args, span).map(|v| vec![v]),
        other => Err(RuntimeError::TypeError {
            message: format!(
                "value of type `{}` is not callable — only functions, classes, and methods can be called",
                other.type_name()
            ),
            span,
        }),
    }
}

/// Bind `params` into `scope` from `args`, evaluating defaults lazily. Used
/// by every kind of call (free function, instance method, static method,
/// constructor) so the rules stay in one place.
fn bind_params(
    scope: &Rc<RefCell<Environment>>,
    params: &[saule_ast::Param],
    args: &[EvaluatedArg],
    span: &std::ops::Range<usize>,
) -> Result<(), RuntimeError> {
    let variadic_indices: Vec<usize> = params
        .iter()
        .enumerate()
        .filter_map(|(i, p)| p.variadic.then_some(i))
        .collect();
    if variadic_indices.len() > 1 {
        return Err(RuntimeError::TypeError {
            message: "a function can declare at most one variadic parameter".to_string(),
            span: params[variadic_indices[1]].span.clone(),
        });
    }
    let variadic_idx = variadic_indices.first().copied();
    if let Some(idx) = variadic_idx
        && idx + 1 != params.len()
    {
        return Err(RuntimeError::TypeError {
            message: format!(
                "variadic parameter `{}` must be the last parameter in the list",
                params[idx].name
            ),
            span: params[idx].span.clone(),
        });
    }

    let mut assigned: Vec<Option<Value>> = vec![None; params.len()];
    let mut variadic_values: Vec<Value> = Vec::new();
    let mut next_positional = 0usize;
    let mut seen_named = false;
    let mut named_arg_count = 0usize;

    for arg in args {
        match arg {
            EvaluatedArg::Positional(value) => {
                if seen_named {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "positional argument #{} cannot follow named arguments; all positional arguments must come first",
                            next_positional + 1
                        ),
                        span: span.clone(),
                    });
                }
                if let Some(var_idx) = variadic_idx
                    && next_positional >= var_idx
                {
                    variadic_values.push(value.clone());
                    next_positional += 1;
                    continue;
                }
                if next_positional >= params.len() {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "too many arguments: expected {} but got at least {}",
                            params.len(),
                            next_positional + 1
                        ),
                        span: span.clone(),
                    });
                }
                assigned[next_positional] = Some(value.clone());
                next_positional += 1;
            }
            EvaluatedArg::Named { name, value } => {
                seen_named = true;
                named_arg_count += 1;
                let Some(idx) = params.iter().position(|p| p.name == *name) else {
                    let valid_params: Vec<String> = params.iter().map(|p| p.name.clone()).collect();
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "unknown named argument `{name}` (argument #{} of {}) — valid parameters: {}",
                            named_arg_count,
                            args.len(),
                            valid_params.join(", ")
                        ),
                        span: span.clone(),
                    });
                };
                if params[idx].variadic {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "variadic parameter `{name}` cannot be passed by name — provide any extra arguments positionally"
                        ),
                        span: span.clone(),
                    });
                }
                if assigned[idx].is_some() {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "duplicate argument for parameter `{name}` — this parameter was already provided"
                        ),
                        span: span.clone(),
                    });
                }
                assigned[idx] = Some(value.clone());
            }
        }
    }

    let missing_required: Vec<String> = params
        .iter()
        .enumerate()
        .filter_map(|(i, p)| {
            if assigned[i].is_none()
                && !p.variadic
                && p.default.is_none()
                && !is_nullable_type(&p.ty)
            {
                Some(p.name.clone())
            } else {
                None
            }
        })
        .collect();

    for (i, param) in params.iter().enumerate() {
        if param.variadic {
            scope.borrow_mut().define(
                param.name.clone(),
                Value::Table(Rc::new(RefCell::new(crate::value::TableObject::from_array(
                    variadic_values.clone(),
                )))),
            );
            continue;
        }
        let value = if let Some(v) = assigned[i].clone() {
            v
        } else if let Some(default) = &param.default {
            eval(default, scope)?
        } else if is_nullable_type(&param.ty) {
            Value::Nil
        } else {
            let help = if missing_required.len() == 1 {
                Some(format!(
                    "add argument `{}` to this call (positionally or by name)",
                    missing_required[0]
                ))
            } else {
                Some(format!(
                    "add required arguments to this call: {}",
                    missing_required
                        .iter()
                        .map(|n| format!("`{n}`"))
                        .collect::<Vec<_>>()
                        .join(", ")
                ))
            };
            return Err(RuntimeError::ArgumentError {
                message: if missing_required.len() == 1 {
                    format!("missing required argument for parameter `{}`", param.name)
                } else {
                    format!(
                        "missing {} required argument(s): {}",
                        missing_required.len(),
                        missing_required.join(", ")
                    )
                },
                help,
                span: span.clone(),
            });
        };
        scope.borrow_mut().define(param.name.clone(), value);
    }
    Ok(())
}

fn is_nullable_type(ty: &Type) -> bool {
    matches!(ty, Type::Nullable(_)) || matches!(ty, Type::Named(n) if n == "nil")
}

#[allow(dead_code)]
pub(crate) fn table_index_to_slot(index: &Value) -> Result<Option<usize>, String> {
    match index {
        Value::Int(i) if *i <= 0 => Ok(None),
        Value::Int(i) => Ok(Some((*i as usize) - 1)),
        other => Err(format!(
            "table indices must be integers, got `{}`",
            other.type_name()
        )),
    }
}

fn read_index(
    receiver: &Value,
    index: Value,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    match receiver {
        Value::Table(items) => Ok(items.borrow().get(&index)),
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot index a `{}` — only tables support `[index]` access",
                other.type_name()
            ),
            span,
        }),
    }
}

fn eval_call_args(
    args: &[CallArg],
    env: &Rc<RefCell<Environment>>,
) -> Result<Vec<EvaluatedArg>, RuntimeError> {
    let mut out = Vec::with_capacity(args.len());
    for arg in args {
        match arg {
            CallArg::Positional(expr) => out.push(EvaluatedArg::Positional(eval(expr, env)?)),
            CallArg::Named { name, value } => out.push(EvaluatedArg::Named {
                name: name.clone(),
                value: eval(value, env)?,
            }),
        }
    }
    Ok(out)
}

fn run_function_body(
    f: &FunctionObject,
    scope: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(run_function_body_multi(f, scope, span)?))
}

fn run_function_body_multi(
    f: &FunctionObject,
    scope: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    let outcome = match &f.body {
        FunctionBody::Block(stmts) => super::stmt::exec_block(stmts, scope)?,
        FunctionBody::Expr(e) => Flow::Return(vec![eval(e, scope)?]),
    };
    match outcome {
        Flow::Return(values) => Ok(values),
        Flow::Normal(_) => Ok(vec![Value::Nil]),
        Flow::Break => Err(RuntimeError::LoopControlOutsideLoop {
            which: "break",
            span,
        }),
        Flow::Continue => Err(RuntimeError::LoopControlOutsideLoop {
            which: "continue",
            span,
        }),
    }
}

/// Skip a leading `self` parameter (so explicit-self style still works
/// alongside the implicit-self style this language prefers).
fn user_params(f: &FunctionObject) -> &[saule_ast::Param] {
    if f.params.first().map(|p| p.name == "self").unwrap_or(false) {
        &f.params[1..]
    } else {
        &f.params
    }
}

/// Call a user-defined function: binds args (with defaults), executes the
/// body in a fresh scope parented to the function's closure, and converts
/// the resulting [`Flow`] into a return value.
pub(crate) fn call_function(
    f: &FunctionObject,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(call_function_multi(f, args, span)?))
}

fn call_function_multi(
    f: &FunctionObject,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    let scope = Environment::with_parent(f.closure.clone());
    bind_params(&scope, &f.params, args, &span)?;
    run_function_body_multi(f, &scope, span)
}

fn call_instance_method_multi(
    f: &FunctionObject,
    receiver: Value,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    let scope = Environment::with_parent(f.closure.clone());
    // Inject the class's static fields/methods so the method body can refer
    // to them by their bare names — see `inject_class_statics` for why.
    if let Value::Instance(inst) = &receiver {
        inject_class_statics(&scope, &inst.borrow().class);
    }
    scope.borrow_mut().define("self".to_string(), receiver);
    bind_params(&scope, user_params(f), args, &span)?;
    run_function_body_multi(f, &scope, span)
}

/// Invoke a static method with `self` bound to the class itself, which is
/// what makes `self.staticField` inside a `static fn` resolve to the right
/// thing (and is the only way `Main.main()` can reach `Main.lauris`).
fn call_static_method(
    f: &FunctionObject,
    class: &Rc<ClassObject>,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(call_static_method_multi(f, class, args, span)?))
}

fn call_static_method_multi(
    f: &FunctionObject,
    class: &Rc<ClassObject>,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    let scope = Environment::with_parent(f.closure.clone());
    inject_class_statics(&scope, class);
    scope
        .borrow_mut()
        .define("self".to_string(), Value::Class(class.clone()));
    bind_params(&scope, user_params(f), args, &span)?;
    run_function_body_multi(f, &scope, span)
}

/// Make the class's static fields and methods directly visible inside a
/// method body, so users can write `lauris.introduce()` instead of
/// `self.lauris.introduce()` or `Main.lauris.introduce()`. Parent statics
/// are seeded first and overridden by child statics, matching the lookup
/// order used for member access. Locals and parameters bound later still
/// shadow these, so the user can introduce a same-named local without
/// surprise.
fn inject_class_statics(scope: &Rc<RefCell<Environment>>, class: &Rc<ClassObject>) {
    // Collect the chain root-first so the most-derived class wins.
    let mut chain: Vec<Rc<ClassObject>> = Vec::new();
    let mut cur = Some(class.clone());
    while let Some(c) = cur {
        chain.push(c.clone());
        cur = c.parent.clone();
    }
    for c in chain.iter().rev() {
        for (n, v) in c.static_fields.borrow().iter() {
            scope.borrow_mut().define(n.clone(), v.clone());
        }
        for (n, f) in &c.static_methods {
            scope
                .borrow_mut()
                .define(n.clone(), Value::Function(f.clone()));
        }
    }
}

/// Public re-export of [`call_static_method`] for embedders. Kept as a thin
/// wrapper so the implementation details (param binding, `self` injection)
/// stay private to this module.
pub(crate) fn call_static_method_public(
    f: &FunctionObject,
    class: &Rc<ClassObject>,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    call_static_method(f, class, args, span)
}

/// Resolve `obj.name(args)` where the lookup intent is to *invoke* the
/// result. Instance methods get implicit `self`; static methods get the
/// class as `self`; non-function fields are simply invoked through
/// [`call_value`].
fn dispatch_member_call(
    receiver: &Value,
    name: &str,
    args: Vec<EvaluatedArg>,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(dispatch_member_call_multi(receiver, name, args, span)?))
}

fn dispatch_member_call_multi(
    receiver: &Value,
    name: &str,
    args: Vec<EvaluatedArg>,
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    match receiver {
        Value::Instance(inst) => {
            let class = inst.borrow().class.clone();
            if let Some(m) = class.lookup_method(name) {
                return call_instance_method_multi(&m, receiver.clone(), &args, span);
            }
            if let Some(m) = class.lookup_static_method(name) {
                return call_static_method_multi(&m, &class, &args, span);
            }
            // Fall back: maybe the instance has a callable field.
            if let Some(v) = inst.borrow().fields.get(name).cloned() {
                return call_value_multi(v, &args, span);
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no method or field `{name}` on instance of class `{}` — instance members are case-sensitive",
                    class.name
                ),
                span,
            })
        }
        Value::Class(class) => {
            if let Some(m) = class.lookup_static_method(name) {
                return call_static_method_multi(&m, class, &args, span);
            }
            if let Some(v) = class.lookup_static_field(name) {
                return call_value_multi(v, &args, span);
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no static member `{name}` on class `{}` — check the class definition for the correct name",
                    class.name
                ),
                span,
            })
        }
        Value::EnumVariant(_variant) => {
            // Look up the method in the enum's method list, then call with
            // self bound to the variant.
            let v = read_member(receiver, name, span.clone())?;
            match v {
                Value::Function(m) => {
                    call_instance_method_multi(&m, receiver.clone(), &args, span)
                }
                _ => call_value_multi(v, &args, span),
            }
        }
        Value::File(handle) => {
            // File methods are implemented in `stdlib::io` via a static
            // method table — keep `Value::File` opaque to the rest of the
            // evaluator.
            let mut positional = Vec::with_capacity(args.len());
            for a in args {
                match a {
                    EvaluatedArg::Positional(v) => positional.push(v),
                    EvaluatedArg::Named { .. } => {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "named arguments are not supported on file methods (`{name}`) — use positional arguments instead"
                            ),
                            span,
                        });
                    }
                }
            }
            crate::stdlib::io::dispatch_file_method(handle, name, &positional)
                .map_err(|message| RuntimeError::TypeError { message, span })
        }
        _ => {
            // Generic: read the field, then call it.
            let v = read_member(receiver, name, span.clone())?;
            call_value_multi(v, &args, span)
        }
    }
}

/// `self.super(args)` — call the parent class's constructor on the current
/// instance. The receiver expression must evaluate to an instance whose
/// class has a parent.
fn super_call(
    obj: &Spanned<Expr>,
    args: &[CallArg],
    env: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    let receiver = eval(obj, env)?;
    let inst = match receiver {
        Value::Instance(i) => i,
        other => {
            return Err(RuntimeError::TypeError {
                message: format!(
                    "`super(...)` requires `self` (an instance receiver), but got a `{}` — use `self.super(...)` inside a constructor",
                    other.type_name()
                ),
                span,
            });
        }
    };
    let owner_class = super_owner_class(env).unwrap_or_else(|| inst.borrow().class.clone());
    let parent = owner_class
        .parent
        .clone()
        .ok_or_else(|| RuntimeError::TypeError {
            message: format!(
                "class `{}` has no parent to call `super` on",
                owner_class.name
            ),
            span: span.clone(),
        })?;
    let ctor = constructor_chain(&parent).ok_or_else(|| RuntimeError::TypeError {
        message: format!("parent class `{}` has no constructor", parent.name),
        span: span.clone(),
    })?;

    let vs = eval_super_args(args, env, &span)?;

    let scope = Environment::with_parent(ctor.closure.clone());
    scope
        .borrow_mut()
        .define("self".to_string(), Value::Instance(inst));
    scope.borrow_mut().define(
        SUPER_OWNER_BINDING.to_string(),
        Value::Class(parent.clone()),
    );
    bind_params(&scope, user_params(&ctor), &vs, &span)?;
    run_function_body(&ctor, &scope, span).map(|_| Value::Nil)
}

fn eval_super_args(
    args: &[CallArg],
    env: &Rc<RefCell<Environment>>,
    span: &std::ops::Range<usize>,
) -> Result<Vec<EvaluatedArg>, RuntimeError> {
    let mut out = Vec::with_capacity(args.len());
    for arg in args {
        match arg {
            CallArg::Positional(expr) => out.push(EvaluatedArg::Positional(eval(expr, env)?)),
            CallArg::Named { .. } => {
                return Err(RuntimeError::TypeError {
                    message: "named arguments are not supported in `super(...)`".to_string(),
                    span: span.clone(),
                });
            }
        }
    }
    Ok(out)
}

fn super_owner_class(env: &Rc<RefCell<Environment>>) -> Option<Rc<ClassObject>> {
    match env.borrow().get(SUPER_OWNER_BINDING) {
        Some(Value::Class(c)) => Some(c),
        _ => None,
    }
}

// ─── Class / instance helpers ───────────────────────────────────────────────

/// Read `receiver.name`.
///
/// On an instance:
///   1. instance fields,
///   2. class methods (returned as a `Function` — useful for `obj.method`
///      access, though most call sites use the `obj:method()` form),
///   3. class static fields (so `instance.maxHealth` still works the same
///      as `Class.maxHealth`).
///
/// On a class:
///   1. static fields,
///   2. static methods.
fn read_member(
    receiver: &Value,
    name: &str,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    match receiver {
        Value::Instance(inst) => {
            let inst_ref = inst.borrow();
            if let Some(v) = inst_ref.fields.get(name) {
                return Ok(v.clone());
            }
            if let Some(m) = inst_ref.class.lookup_method(name) {
                return Ok(Value::Function(m));
            }
            if let Some(v) = inst_ref.class.lookup_static_field(name) {
                return Ok(v);
            }
            if let Some(m) = inst_ref.class.lookup_static_method(name) {
                return Ok(Value::Function(m));
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no field or method `{name}` on instance of class `{}` — available fields: (check class definition)",
                    inst_ref.class.name
                ),
                span,
            })
        }
        Value::Class(class) => {
            if let Some(v) = class.lookup_static_field(name) {
                return Ok(v);
            }
            if let Some(m) = class.lookup_static_method(name) {
                return Ok(Value::Function(m));
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no static member `{name}` on class `{}` — try `{}:` method notation or check if this is an instance method",
                    class.name,
                    class.name
                ),
                span,
            })
        }
        Value::Enum(enum_obj) => {
            if let Some(variant) = enum_obj.variants.get(name) {
                return Ok(Value::EnumVariant(variant.clone()));
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no variant `{name}` on enum `{}` — check enum definition",
                    enum_obj.name
                ),
                span,
            })
        }
        Value::EnumVariant(variant) => {
            match name {
                "value" => {
                    Ok(variant
                        .value
                        .clone()
                        .unwrap_or(Value::Str(Rc::new(variant.variant_name.clone()))))
                }
                "name" => {
                    Ok(Value::Str(Rc::new(variant.variant_name.clone())))
                }
                _ => {
                    if let Some(enum_obj) = variant.enum_obj.borrow().as_ref() {
                        if let Some(m) = enum_obj.methods.get(name) {
                            return Ok(Value::Function(m.clone()));
                        }
                    }
                    Err(RuntimeError::TypeError {
                        message: format!(
                            "no property or method `{name}` on enum variant `{}.{}`",
                            variant.enum_name, variant.variant_name
                        ),
                        span,
                    })
                }
            }
        }
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot read field `{name}` on value of type `{}` — only instances, classes, and enums have members",
                other.type_name()
            ),
            span,
        }),
    }
}

/// Dispatch `receiver:name(args)`. For instances we prepend `self`; for
/// classes we call the static method as-is.
/// Dispatch `receiver:name(args)` (the colon-call form). Delegates to the
/// shared [`dispatch_member_call`] so the dot and colon forms behave the
/// same way at runtime.
fn invoke_method(
    receiver: &Value,
    name: &str,
    args: Vec<EvaluatedArg>,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    dispatch_member_call(receiver, name, args, span)
}

pub(crate) fn invoke_method_multi(
    receiver: &Value,
    name: &str,
    args: Vec<EvaluatedArg>,
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    dispatch_member_call_multi(receiver, name, args, span)
}

/// `new Class(args)` — create an instance, populate field defaults, then
/// run the constructor (if any) with `self` bound to the new object.
pub(crate) fn construct(
    class: Rc<ClassObject>,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    // Allocate the instance up-front so the constructor can stash it as
    // `self` and observe its own writes.
    let inst = Rc::new(RefCell::new(InstanceObject {
        class: class.clone(),
        fields: HashMap::new(),
    }));

    // Initialize instance fields from defaults (walking the inheritance
    // chain parent-first so the most-derived defaults win).
    init_fields(&class, &inst, &span)?;

    // Run the constructor — first declared on this class, otherwise the
    // nearest parent's. If none exists, fields stay at their defaults.
    if let Some(ctor) = constructor_chain(&class) {
        let scope = Environment::with_parent(ctor.closure.clone());
        inject_class_statics(&scope, &class);
        scope
            .borrow_mut()
            .define("self".to_string(), Value::Instance(inst.clone()));
        scope
            .borrow_mut()
            .define(SUPER_OWNER_BINDING.to_string(), Value::Class(class.clone()));
        // Skip a leading explicit `self` parameter if present (the
        // constructor / `init` body uses the auto-bound one).
        bind_params(&scope, user_params(&ctor), args, &span)?;
        run_function_body(&ctor, &scope, span)?;
    }

    Ok(Value::Instance(inst))
}

fn init_fields(
    class: &Rc<ClassObject>,
    inst: &Rc<RefCell<InstanceObject>>,
    span: &std::ops::Range<usize>,
) -> Result<(), RuntimeError> {
    if let Some(parent) = &class.parent {
        init_fields(parent, inst, span)?;
    }
    // Field-default expressions evaluate in the class's declaration scope.
    // We approximate by using the constructor's closure (every method on a
    // class shares that closure), falling back to a fresh prelude-less env
    // when none exists.
    let scope = if let Some(ctor) = &class.constructor {
        Environment::with_parent(ctor.closure.clone())
    } else if let Some(m) = class.methods.values().next() {
        Environment::with_parent(m.closure.clone())
    } else if let Some(m) = class.static_methods.values().next() {
        Environment::with_parent(m.closure.clone())
    } else {
        Environment::new()
    };
    // `self` is visible to default expressions too.
    scope
        .borrow_mut()
        .define("self".to_string(), Value::Instance(inst.clone()));

    for field in &class.field_defs {
        let value = match &field.default {
            Some(e) => eval(e, &scope)?,
            None => Value::Nil,
        };
        inst.borrow_mut().fields.insert(field.name.clone(), value);
    }
    Ok(())
}

fn constructor_chain(class: &Rc<ClassObject>) -> Option<Rc<FunctionObject>> {
    if let Some(c) = &class.constructor {
        return Some(c.clone());
    }
    class.parent.as_ref().and_then(constructor_chain)
}

//! Expression evaluation.

use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

use saule_ast::{BinOp, CallArg, Expr, LambdaBody, Spanned, Type};

use crate::env::Environment;
use crate::error::RuntimeError;
use crate::value::{ClassObject, FunctionBody, FunctionObject, InstanceObject, Value};

use super::{Flow, ops};

const SUPER_OWNER_BINDING: &str = "__saule_super_owner";

#[derive(Clone)]
pub(crate) enum EvaluatedArg {
    Positional(Value),
    Named { name: String, value: Value },
}

pub fn eval(expr: &Spanned<Expr>, env: &Rc<RefCell<Environment>>) -> Result<Value, RuntimeError> {
    let span = expr.span.clone();
    match &expr.value {
        Expr::Int(n) => Ok(Value::Int(*n)),
        Expr::Float(f) => Ok(Value::Float(*f)),
        Expr::Bool(b) => Ok(Value::Bool(*b)),
        Expr::Str(s) => Ok(Value::Str(Rc::new(s.clone()))),
        Expr::Nil => Ok(Value::Nil),

        Expr::Ident(name) => env
            .borrow()
            .get(name)
            .ok_or_else(|| RuntimeError::Undefined {
                name: name.clone(),
                span,
            }),

        Expr::Unary { op, rhs } => {
            let v = eval(rhs, env)?;
            ops::unary(*op, v, span)
        }

        Expr::Binary { op, lhs, rhs } => match op {
            // `and` / `or` short-circuit, so evaluate lazily.
            BinOp::And => {
                let l = eval(lhs, env)?;
                if l.is_truthy() { eval(rhs, env) } else { Ok(l) }
            }
            BinOp::Or => {
                let l = eval(lhs, env)?;
                if l.is_truthy() { Ok(l) } else { eval(rhs, env) }
            }
            // `??` short-circuits: only evaluate RHS when LHS is nil.
            BinOp::Coalesce => {
                let l = eval(lhs, env)?;
                if matches!(l, Value::Nil) { eval(rhs, env) } else { Ok(l) }
            }
            _ => {
                let l = eval(lhs, env)?;
                let r = eval(rhs, env)?;
                ops::binary(*op, l, r, span)
            }
        },

        Expr::Call { callee, args } => {
            // Dotted calls (`obj.method(args)`) and `self.super(args)` need
            // special handling so we can auto-bind `self` and route to the
            // parent constructor respectively. Saule lets instance methods
            // omit the explicit `self` parameter — see `call_instance_method`.
            if let Expr::Member { obj, name } = &callee.value {
                if name == "super" {
                    return super_call(obj, args, env, span);
                }
                let receiver = eval(obj, env)?;
                let vs = eval_call_args(args, env)?;
                return dispatch_member_call(&receiver, name, vs, span);
            }

            let cv = eval(callee, env)?;
            let vs = eval_call_args(args, env)?;
            call_value(cv, &vs, span)
        }

        // Postfix / composite forms — wait until later phases.
        Expr::Member { obj, name } => {
            let receiver = eval(obj, env)?;
            read_member(&receiver, name, span)
        }
        Expr::SafeMember { obj, name } => {
            let receiver = eval(obj, env)?;
            if matches!(receiver, Value::Nil) {
                Ok(Value::Nil)
            } else {
                read_member(&receiver, name, span)
            }
        }
        Expr::Index { obj, index } => {
            let receiver = eval(obj, env)?;
            let index_value = eval(index, env)?;
            read_index(&receiver, index_value, span)
        }
        Expr::MethodCall { obj, method, args } => {
            let receiver = eval(obj, env)?;
            let evaled = eval_call_args(args, env)?;
            invoke_method(&receiver, method, evaled, span)
        }
        Expr::ForceUnwrap(inner) => {
            let v = eval(inner, env)?;
            if matches!(v, Value::Nil) {
                Err(RuntimeError::ForceUnwrapNil { span })
            } else {
                Ok(v)
            }
        }
        Expr::Table(items) => {
            let mut values = Vec::with_capacity(items.len());
            for item in items {
                values.push(eval(item, env)?);
            }
            Ok(Value::Table(Rc::new(RefCell::new(
                crate::value::TableObject::from_array(values),
            ))))
        }

        Expr::Lambda { params, body, .. } => {
            let body = match body {
                LambdaBody::Expr(e) => FunctionBody::Expr(e.clone()),
                LambdaBody::Block(stmts) => FunctionBody::Block(stmts.clone()),
            };
            Ok(Value::Function(Rc::new(FunctionObject {
                name: None,
                params: params.clone(),
                body,
                closure: env.clone(),
                owner_class: std::cell::RefCell::new(None),
            })))
        }

        Expr::Self_ => env
            .borrow()
            .get("self")
            .ok_or_else(|| RuntimeError::Undefined {
                name: "self".to_string(),
                span,
            }),
    }
}

fn first_or_nil(values: Vec<Value>) -> Value {
    values.into_iter().next().unwrap_or(Value::Nil)
}

pub(crate) fn eval_values(
    expr: &Spanned<Expr>,
    env: &Rc<RefCell<Environment>>,
) -> Result<Vec<Value>, RuntimeError> {
    let span = expr.span.clone();
    match &expr.value {
        Expr::Call { callee, args } => {
            if let Expr::Member { obj, name } = &callee.value {
                if name == "super" {
                    return Ok(vec![super_call(obj, args, env, span)?]);
                }
                let receiver = eval(obj, env)?;
                let vs = eval_call_args(args, env)?;
                return dispatch_member_call_multi(&receiver, name, vs, span);
            }

            let cv = eval(callee, env)?;
            let vs = eval_call_args(args, env)?;
            call_value_multi(cv, &vs, span)
        }
        Expr::MethodCall { obj, method, args } => {
            let receiver = eval(obj, env)?;
            let evaled = eval_call_args(args, env)?;
            invoke_method_multi(&receiver, method, evaled, span)
        }
        _ => Ok(vec![eval(expr, env)?]),
    }
}

/// Invoke a callable [`Value`]. Handles both native and user-defined
/// functions.
fn call_value(
    callee: Value,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(call_value_multi(callee, args, span)?))
}

pub(crate) fn call_value_multi(
    callee: Value,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    match callee {
        Value::Native(nf) => {
            let mut positional = Vec::with_capacity(args.len());
            for arg in args {
                match arg {
                    EvaluatedArg::Positional(v) => positional.push(v.clone()),
                    EvaluatedArg::Named { name: _, .. } => {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "named arguments are not supported for built-in function `{}` — use positional arguments instead",
                                nf.name
                            ),
                            span,
                        });
                    }
                }
            }
            (nf.func)(&positional)
                .map(|v| vec![v])
                .map_err(|message| RuntimeError::TypeError { message, span })
        }
        Value::Function(f) => call_function_multi(&f, args, span),
        Value::NativeClosure(nc) => {
            let mut positional = Vec::with_capacity(args.len());
            for arg in args {
                match arg {
                    EvaluatedArg::Positional(v) => positional.push(v.clone()),
                    EvaluatedArg::Named { name: _, .. } => {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "named arguments are not supported for built-in function `{}` — use positional arguments instead",
                                nc.name
                            ),
                            span,
                        });
                    }
                }
            }
            (nc.func)(&positional)
                .map_err(|message| RuntimeError::TypeError { message, span })
        }
        // `ClassName(args)` constructs an instance.
        Value::Class(c) => construct(c, args, span).map(|v| vec![v]),
        other => Err(RuntimeError::TypeError {
            message: format!(
                "value of type `{}` is not callable — only functions, classes, and methods can be called",
                other.type_name()
            ),
            span,
        }),
    }
}

/// Bind `params` into `scope` from `args`, evaluating defaults lazily. Used
/// by every kind of call (free function, instance method, static method,
/// constructor) so the rules stay in one place.
fn bind_params(
    scope: &Rc<RefCell<Environment>>,
    params: &[saule_ast::Param],
    args: &[EvaluatedArg],
    span: &std::ops::Range<usize>,
) -> Result<(), RuntimeError> {
    let variadic_indices: Vec<usize> = params
        .iter()
        .enumerate()
        .filter_map(|(i, p)| p.variadic.then_some(i))
        .collect();
    if variadic_indices.len() > 1 {
        return Err(RuntimeError::TypeError {
            message: "a function can declare at most one variadic parameter".to_string(),
            span: params[variadic_indices[1]].span.clone(),
        });
    }
    let variadic_idx = variadic_indices.first().copied();
    if let Some(idx) = variadic_idx
        && idx + 1 != params.len()
    {
        return Err(RuntimeError::TypeError {
            message: format!(
                "variadic parameter `{}` must be the last parameter in the list",
                params[idx].name
            ),
            span: params[idx].span.clone(),
        });
    }

    let mut assigned: Vec<Option<Value>> = vec![None; params.len()];
    let mut variadic_values: Vec<Value> = Vec::new();
    let mut next_positional = 0usize;
    let mut seen_named = false;
    let mut named_arg_count = 0usize;

    for arg in args {
        match arg {
            EvaluatedArg::Positional(value) => {
                if seen_named {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "positional argument #{} cannot follow named arguments; all positional arguments must come first",
                            next_positional + 1
                        ),
                        span: span.clone(),
                    });
                }
                if let Some(var_idx) = variadic_idx
                    && next_positional >= var_idx
                {
                    variadic_values.push(value.clone());
                    next_positional += 1;
                    continue;
                }
                if next_positional >= params.len() {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "too many arguments: expected {} but got at least {}",
                            params.len(),
                            next_positional + 1
                        ),
                        span: span.clone(),
                    });
                }
                assigned[next_positional] = Some(value.clone());
                next_positional += 1;
            }
            EvaluatedArg::Named { name, value } => {
                seen_named = true;
                named_arg_count += 1;
                let Some(idx) = params.iter().position(|p| p.name == *name) else {
                    let valid_params: Vec<String> = params.iter().map(|p| p.name.clone()).collect();
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "unknown named argument `{name}` (argument #{} of {}) — valid parameters: {}",
                            named_arg_count,
                            args.len(),
                            valid_params.join(", ")
                        ),
                        span: span.clone(),
                    });
                };
                if params[idx].variadic {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "variadic parameter `{name}` cannot be passed by name — provide any extra arguments positionally"
                        ),
                        span: span.clone(),
                    });
                }
                if assigned[idx].is_some() {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "duplicate argument for parameter `{name}` — this parameter was already provided"
                        ),
                        span: span.clone(),
                    });
                }
                assigned[idx] = Some(value.clone());
            }
        }
    }

    let missing_required: Vec<String> = params
        .iter()
        .enumerate()
        .filter_map(|(i, p)| {
            if assigned[i].is_none()
                && !p.variadic
                && p.default.is_none()
                && !is_nullable_type(&p.ty)
            {
                Some(p.name.clone())
            } else {
                None
            }
        })
        .collect();

    for (i, param) in params.iter().enumerate() {
        if param.variadic {
            scope.borrow_mut().define(
                param.name.clone(),
                Value::Table(Rc::new(RefCell::new(crate::value::TableObject::from_array(
                    variadic_values.clone(),
                )))),
            );
            continue;
        }
        let value = if let Some(v) = assigned[i].clone() {
            v
        } else if let Some(default) = &param.default {
            eval(default, scope)?
        } else if is_nullable_type(&param.ty) {
            Value::Nil
        } else {
            let help = if missing_required.len() == 1 {
                Some(format!(
                    "add argument `{}` to this call (positionally or by name)",
                    missing_required[0]
                ))
            } else {
                Some(format!(
                    "add required arguments to this call: {}",
                    missing_required
                        .iter()
                        .map(|n| format!("`{n}`"))
                        .collect::<Vec<_>>()
                        .join(", ")
                ))
            };
            return Err(RuntimeError::ArgumentError {
                message: if missing_required.len() == 1 {
                    format!("missing required argument for parameter `{}`", param.name)
                } else {
                    format!(
                        "missing {} required argument(s): {}",
                        missing_required.len(),
                        missing_required.join(", ")
                    )
                },
                help,
                span: span.clone(),
            });
        };
        scope.borrow_mut().define(param.name.clone(), value);
    }
    Ok(())
}

fn is_nullable_type(ty: &Type) -> bool {
    matches!(ty, Type::Nullable(_)) || matches!(ty, Type::Named(n) if n == "nil")
}

#[allow(dead_code)]
pub(crate) fn table_index_to_slot(index: &Value) -> Result<Option<usize>, String> {
    match index {
        Value::Int(i) if *i <= 0 => Ok(None),
        Value::Int(i) => Ok(Some((*i as usize) - 1)),
        other => Err(format!(
            "table indices must be integers, got `{}`",
            other.type_name()
        )),
    }
}

fn read_index(
    receiver: &Value,
    index: Value,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    match receiver {
        Value::Table(items) => Ok(items.borrow().get(&index)),
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot index a `{}` — only tables support `[index]` access",
                other.type_name()
            ),
            span,
        }),
    }
}

fn eval_call_args(
    args: &[CallArg],
    env: &Rc<RefCell<Environment>>,
) -> Result<Vec<EvaluatedArg>, RuntimeError> {
    let mut out = Vec::with_capacity(args.len());
    for arg in args {
        match arg {
            CallArg::Positional(expr) => out.push(EvaluatedArg::Positional(eval(expr, env)?)),
            CallArg::Named { name, value } => out.push(EvaluatedArg::Named {
                name: name.clone(),
                value: eval(value, env)?,
            }),
        }
    }
    Ok(out)
}

fn run_function_body(
    f: &FunctionObject,
    scope: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(run_function_body_multi(f, scope, span)?))
}

fn run_function_body_multi(
    f: &FunctionObject,
    scope: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    let outcome = match &f.body {
        FunctionBody::Block(stmts) => super::stmt::exec_block(stmts, scope)?,
        FunctionBody::Expr(e) => Flow::Return(vec![eval(e, scope)?]),
    };
    match outcome {
        Flow::Return(values) => Ok(values),
        Flow::Normal(_) => Ok(vec![Value::Nil]),
        Flow::Break => Err(RuntimeError::LoopControlOutsideLoop {
            which: "break",
            span,
        }),
        Flow::Continue => Err(RuntimeError::LoopControlOutsideLoop {
            which: "continue",
            span,
        }),
    }
}

/// Skip a leading `self` parameter (so explicit-self style still works
/// alongside the implicit-self style this language prefers).
fn user_params(f: &FunctionObject) -> &[saule_ast::Param] {
    if f.params.first().map(|p| p.name == "self").unwrap_or(false) {
        &f.params[1..]
    } else {
        &f.params
    }
}

/// Call a user-defined function: binds args (with defaults), executes the
/// body in a fresh scope parented to the function's closure, and converts
/// the resulting [`Flow`] into a return value.
pub(crate) fn call_function(
    f: &FunctionObject,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(call_function_multi(f, args, span)?))
}

fn call_function_multi(
    f: &FunctionObject,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    let scope = Environment::with_parent(f.closure.clone());
    // If this function is a class method invoked directly (rather than via
    // the dedicated method-dispatch path), seed the scope with the class's
    // statics so the body can reach sibling statics by bare name.
    if let Some(class) = f.resolved_owner() {
        inject_class_statics(&scope, &class);
    }
    bind_params(&scope, &f.params, args, &span)?;
    run_function_body_multi(f, &scope, span)
}

fn call_instance_method_multi(
    f: &FunctionObject,
    receiver: Value,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    let scope = Environment::with_parent(f.closure.clone());
    // Inject the class's static fields/methods so the method body can refer
    // to them by their bare names — see `inject_class_statics` for why.
    if let Value::Instance(inst) = &receiver {
        inject_class_statics(&scope, &inst.borrow().class);
    }
    scope.borrow_mut().define("self".to_string(), receiver);
    bind_params(&scope, user_params(f), args, &span)?;
    run_function_body_multi(f, &scope, span)
}

/// Invoke a static method with `self` bound to the class itself, which is
/// what makes `self.staticField` inside a `static fn` resolve to the right
/// thing (and is the only way `Main.main()` can reach `Main.lauris`).
fn call_static_method(
    f: &FunctionObject,
    class: &Rc<ClassObject>,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(call_static_method_multi(f, class, args, span)?))
}

fn call_static_method_multi(
    f: &FunctionObject,
    class: &Rc<ClassObject>,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    let scope = Environment::with_parent(f.closure.clone());
    inject_class_statics(&scope, class);
    scope
        .borrow_mut()
        .define("self".to_string(), Value::Class(class.clone()));
    bind_params(&scope, user_params(f), args, &span)?;
    run_function_body_multi(f, &scope, span)
}

/// Make the class's static fields and methods directly visible inside a
/// method body, so users can write `lauris.introduce()` instead of
/// `self.lauris.introduce()` or `Main.lauris.introduce()`. Parent statics
/// are seeded first and overridden by child statics, matching the lookup
/// order used for member access. Locals and parameters bound later still
/// shadow these, so the user can introduce a same-named local without
/// surprise.
fn inject_class_statics(scope: &Rc<RefCell<Environment>>, class: &Rc<ClassObject>) {
    // Collect the chain root-first so the most-derived class wins.
    let mut chain: Vec<Rc<ClassObject>> = Vec::new();
    let mut cur = Some(class.clone());
    while let Some(c) = cur {
        chain.push(c.clone());
        cur = c.parent.clone();
    }
    for c in chain.iter().rev() {
        for (n, v) in c.static_fields.borrow().iter() {
            scope.borrow_mut().define(n.clone(), v.clone());
        }
        for (n, f) in &c.static_methods {
            scope
                .borrow_mut()
                .define(n.clone(), Value::Function(f.clone()));
        }
    }
}

/// Public re-export of [`call_static_method`] for embedders. Kept as a thin
/// wrapper so the implementation details (param binding, `self` injection)
/// stay private to this module.
pub(crate) fn call_static_method_public(
    f: &FunctionObject,
    class: &Rc<ClassObject>,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    call_static_method(f, class, args, span)
}

/// Resolve `obj.name(args)` where the lookup intent is to *invoke* the
/// result. Instance methods get implicit `self`; static methods get the
/// class as `self`; non-function fields are simply invoked through
/// [`call_value`].
fn dispatch_member_call(
    receiver: &Value,
    name: &str,
    args: Vec<EvaluatedArg>,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(dispatch_member_call_multi(receiver, name, args, span)?))
}

fn dispatch_member_call_multi(
    receiver: &Value,
    name: &str,
    args: Vec<EvaluatedArg>,
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    match receiver {
        Value::Instance(inst) => {
            let class = inst.borrow().class.clone();
            if let Some(m) = class.lookup_method(name) {
                return call_instance_method_multi(&m, receiver.clone(), &args, span);
            }
            if let Some(m) = class.lookup_static_method(name) {
                return call_static_method_multi(&m, &class, &args, span);
            }
            // Fall back: maybe the instance has a callable field.
            if let Some(v) = inst.borrow().fields.get(name).cloned() {
                return call_value_multi(v, &args, span);
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no method or field `{name}` on instance of class `{}` — instance members are case-sensitive",
                    class.name
                ),
                span,
            })
        }
        Value::Class(class) => {
            if let Some(m) = class.lookup_static_method(name) {
                return call_static_method_multi(&m, class, &args, span);
            }
            if let Some(v) = class.lookup_static_field(name) {
                return call_value_multi(v, &args, span);
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no static member `{name}` on class `{}` — check the class definition for the correct name",
                    class.name
                ),
                span,
            })
        }
        Value::EnumVariant(_variant) => {
            // Look up the method in the enum's method list, then call with
            // self bound to the variant.
            let v = read_member(receiver, name, span.clone())?;
            match v {
                Value::Function(m) => {
                    call_instance_method_multi(&m, receiver.clone(), &args, span)
                }
                _ => call_value_multi(v, &args, span),
            }
        }
        Value::File(handle) => {
            // File methods are implemented in `stdlib::io` via a static
            // method table — keep `Value::File` opaque to the rest of the
            // evaluator.
            let mut positional = Vec::with_capacity(args.len());
            for a in args {
                match a {
                    EvaluatedArg::Positional(v) => positional.push(v),
                    EvaluatedArg::Named { .. } => {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "named arguments are not supported on file methods (`{name}`) — use positional arguments instead"
                            ),
                            span,
                        });
                    }
                }
            }
            crate::stdlib::io::dispatch_file_method(handle, name, &positional)
                .map_err(|message| RuntimeError::TypeError { message, span })
        }
        _ => {
            // Generic: read the field, then call it.
            let v = read_member(receiver, name, span.clone())?;
            call_value_multi(v, &args, span)
        }
    }
}

/// `self.super(args)` — call the parent class's constructor on the current
/// instance. The receiver expression must evaluate to an instance whose
/// class has a parent.
fn super_call(
    obj: &Spanned<Expr>,
    args: &[CallArg],
    env: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    let receiver = eval(obj, env)?;
    let inst = match receiver {
        Value::Instance(i) => i,
        other => {
            return Err(RuntimeError::TypeError {
                message: format!(
                    "`super(...)` requires `self` (an instance receiver), but got a `{}` — use `self.super(...)` inside a constructor",
                    other.type_name()
                ),
                span,
            });
        }
    };
    let owner_class = super_owner_class(env).unwrap_or_else(|| inst.borrow().class.clone());
    let parent = owner_class
        .parent
        .clone()
        .ok_or_else(|| RuntimeError::TypeError {
            message: format!(
                "class `{}` has no parent to call `super` on",
                owner_class.name
            ),
            span: span.clone(),
        })?;
    let ctor = constructor_chain(&parent).ok_or_else(|| RuntimeError::TypeError {
        message: format!("parent class `{}` has no constructor", parent.name),
        span: span.clone(),
    })?;

    let vs = eval_super_args(args, env, &span)?;

    let scope = Environment::with_parent(ctor.closure.clone());
    scope
        .borrow_mut()
        .define("self".to_string(), Value::Instance(inst));
    scope.borrow_mut().define(
        SUPER_OWNER_BINDING.to_string(),
        Value::Class(parent.clone()),
    );
    bind_params(&scope, user_params(&ctor), &vs, &span)?;
    run_function_body(&ctor, &scope, span).map(|_| Value::Nil)
}

fn eval_super_args(
    args: &[CallArg],
    env: &Rc<RefCell<Environment>>,
    span: &std::ops::Range<usize>,
) -> Result<Vec<EvaluatedArg>, RuntimeError> {
    let mut out = Vec::with_capacity(args.len());
    for arg in args {
        match arg {
            CallArg::Positional(expr) => out.push(EvaluatedArg::Positional(eval(expr, env)?)),
            CallArg::Named { .. } => {
                return Err(RuntimeError::TypeError {
                    message: "named arguments are not supported in `super(...)`".to_string(),
                    span: span.clone(),
                });
            }
        }
    }
    Ok(out)
}

fn super_owner_class(env: &Rc<RefCell<Environment>>) -> Option<Rc<ClassObject>> {
    match env.borrow().get(SUPER_OWNER_BINDING) {
        Some(Value::Class(c)) => Some(c),
        _ => None,
    }
}

// ─── Class / instance helpers ───────────────────────────────────────────────

/// Read `receiver.name`.
///
/// On an instance:
///   1. instance fields,
///   2. class methods (returned as a `Function` — useful for `obj.method`
///      access, though most call sites use the `obj:method()` form),
///   3. class static fields (so `instance.maxHealth` still works the same
///      as `Class.maxHealth`).
///
/// On a class:
///   1. static fields,
///   2. static methods.
fn read_member(
    receiver: &Value,
    name: &str,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    match receiver {
        Value::Instance(inst) => {
            let inst_ref = inst.borrow();
            if let Some(v) = inst_ref.fields.get(name) {
                return Ok(v.clone());
            }
            if let Some(m) = inst_ref.class.lookup_method(name) {
                return Ok(Value::Function(m));
            }
            if let Some(v) = inst_ref.class.lookup_static_field(name) {
                return Ok(v);
            }
            if let Some(m) = inst_ref.class.lookup_static_method(name) {
                return Ok(Value::Function(m));
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no field or method `{name}` on instance of class `{}` — available fields: (check class definition)",
                    inst_ref.class.name
                ),
                span,
            })
        }
        Value::Class(class) => {
            if let Some(v) = class.lookup_static_field(name) {
                return Ok(v);
            }
            if let Some(m) = class.lookup_static_method(name) {
                return Ok(Value::Function(m));
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no static member `{name}` on class `{}` — try `{}:` method notation or check if this is an instance method",
                    class.name,
                    class.name
                ),
                span,
            })
        }
        Value::Enum(enum_obj) => {
            if let Some(variant) = enum_obj.variants.get(name) {
                return Ok(Value::EnumVariant(variant.clone()));
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no variant `{name}` on enum `{}` — check enum definition",
                    enum_obj.name
                ),
                span,
            })
        }
        Value::EnumVariant(variant) => {
            match name {
                "value" => {
                    Ok(variant
                        .value
                        .clone()
                        .unwrap_or(Value::Str(Rc::new(variant.variant_name.clone()))))
                }
                "name" => {
                    Ok(Value::Str(Rc::new(variant.variant_name.clone())))
                }
                _ => {
                    if let Some(enum_obj) = variant.enum_obj.borrow().as_ref() {
                        if let Some(m) = enum_obj.methods.get(name) {
                            return Ok(Value::Function(m.clone()));
                        }
                    }
                    Err(RuntimeError::TypeError {
                        message: format!(
                            "no property or method `{name}` on enum variant `{}.{}`",
                            variant.enum_name, variant.variant_name
                        ),
                        span,
                    })
                }
            }
        }
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot read field `{name}` on value of type `{}` — only instances, classes, and enums have members",
                other.type_name()
            ),
            span,
        }),
    }
}

/// Dispatch `receiver:name(args)`. For instances we prepend `self`; for
/// classes we call the static method as-is.
/// Dispatch `receiver:name(args)` (the colon-call form). Delegates to the
/// shared [`dispatch_member_call`] so the dot and colon forms behave the
/// same way at runtime.
fn invoke_method(
    receiver: &Value,
    name: &str,
    args: Vec<EvaluatedArg>,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    dispatch_member_call(receiver, name, args, span)
}

pub(crate) fn invoke_method_multi(
    receiver: &Value,
    name: &str,
    args: Vec<EvaluatedArg>,
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    dispatch_member_call_multi(receiver, name, args, span)
}

/// `new Class(args)` — create an instance, populate field defaults, then
/// run the constructor (if any) with `self` bound to the new object.
pub(crate) fn construct(
    class: Rc<ClassObject>,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    // Allocate the instance up-front so the constructor can stash it as
    // `self` and observe its own writes.
    let inst = Rc::new(RefCell::new(InstanceObject {
        class: class.clone(),
        fields: HashMap::new(),
    }));

    // Initialize instance fields from defaults (walking the inheritance
    // chain parent-first so the most-derived defaults win).
    init_fields(&class, &inst, &span)?;

    // Run the constructor — first declared on this class, otherwise the
    // nearest parent's. If none exists, fields stay at their defaults.
    if let Some(ctor) = constructor_chain(&class) {
        let scope = Environment::with_parent(ctor.closure.clone());
        inject_class_statics(&scope, &class);
        scope
            .borrow_mut()
            .define("self".to_string(), Value::Instance(inst.clone()));
        scope
            .borrow_mut()
            .define(SUPER_OWNER_BINDING.to_string(), Value::Class(class.clone()));
        // Skip a leading explicit `self` parameter if present (the
        // constructor / `init` body uses the auto-bound one).
        bind_params(&scope, user_params(&ctor), args, &span)?;
        run_function_body(&ctor, &scope, span)?;
    }

    Ok(Value::Instance(inst))
}

fn init_fields(
    class: &Rc<ClassObject>,
    inst: &Rc<RefCell<InstanceObject>>,
    span: &std::ops::Range<usize>,
) -> Result<(), RuntimeError> {
    if let Some(parent) = &class.parent {
        init_fields(parent, inst, span)?;
    }
    // Field-default expressions evaluate in the class's declaration scope.
    // We approximate by using the constructor's closure (every method on a
    // class shares that closure), falling back to a fresh prelude-less env
    // when none exists.
    let scope = if let Some(ctor) = &class.constructor {
        Environment::with_parent(ctor.closure.clone())
    } else if let Some(m) = class.methods.values().next() {
        Environment::with_parent(m.closure.clone())
    } else if let Some(m) = class.static_methods.values().next() {
        Environment::with_parent(m.closure.clone())
    } else {
        Environment::new()
    };
    // `self` is visible to default expressions too.
    scope
        .borrow_mut()
        .define("self".to_string(), Value::Instance(inst.clone()));

    for field in &class.field_defs {
        let value = match &field.default {
            Some(e) => eval(e, &scope)?,
            None => Value::Nil,
        };
        inst.borrow_mut().fields.insert(field.name.clone(), value);
    }
    Ok(())
}

fn constructor_chain(class: &Rc<ClassObject>) -> Option<Rc<FunctionObject>> {
    if let Some(c) = &class.constructor {
        return Some(c.clone());
    }
    class.parent.as_ref().and_then(constructor_chain)
}

//! Statement execution with control-flow propagation.

use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

use saule_ast::{ClassMember, Decl, EnumVariant, Expr, ImportNames, Method, Param, Spanned, Stmt};

use crate::env::Environment;
use crate::error::{RuntimeError, unsupported};
use crate::module;
use crate::value::{self, ClassObject, FieldDef, FunctionBody, FunctionObject, InterfaceObject, Value};

use super::{Flow, expr};

/// Execute a sequence of statements in `env`. Stops at the first non-`Normal`
/// outcome and propagates it.
pub fn exec_block(
    stmts: &[Spanned<Stmt>],
    env: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let mut last = Flow::nil();
    for stmt in stmts {
        match exec(stmt, env)? {
            Flow::Normal(v) => last = Flow::Normal(v),
            other => return Ok(other),
        }
    }
    Ok(last)
}

/// Run a block in a fresh child scope. The scope is dropped on return.
fn exec_scoped_block(
    stmts: &[Spanned<Stmt>],
    parent: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let scope = Environment::with_parent(parent.clone());
    exec_block(stmts, &scope)
}

/// Execute a single statement.
pub fn exec(stmt: &Spanned<Stmt>, env: &Rc<RefCell<Environment>>) -> Result<Flow, RuntimeError> {
    let span = stmt.span.clone();
    match &stmt.value {
        Stmt::Local { name, value, .. } => {
            let v = match value {
                Some(e) => expr::eval(e, env)?,
                None => Value::Nil,
            };
            env.borrow_mut().define(name.clone(), v);
            Ok(Flow::nil())
        }

        Stmt::LocalMulti { names, values } => {
            // Evaluate every RHS first so `local a, b = b, a` works at the
            // outer scope. The final expression may expand into multiple
            // return values (Lua-style destructuring semantics).
            let evaluated = eval_expr_list(values, env)?;
            for (i, (name, _)) in names.iter().enumerate() {
                let v = evaluated.get(i).cloned().unwrap_or(Value::Nil);
                env.borrow_mut().define(name.clone(), v);
            }
            Ok(Flow::nil())
        }

        Stmt::Assign { target, value } => exec_assign(target, value, env),

        Stmt::AssignMulti { targets, values } => {
            // Evaluate all RHS expressions first to support parallel
            // semantics (e.g. `a, b = b, a + b`). The final expression may
            // expand into multiple return values.
            let evaluated = eval_expr_list(values, env)?;
            for (i, target) in targets.iter().enumerate() {
                let v = evaluated.get(i).cloned().unwrap_or(Value::Nil);
                assign_target(target, v, env)?;
            }
            Ok(Flow::nil())
        }

        Stmt::Expr(e) => Ok(Flow::Normal(expr::eval(e, env)?)),

        Stmt::If {
            cond,
            then_block,
            elseifs,
            else_block,
        } => {
            if expr::eval(cond, env)?.is_truthy() {
                return exec_scoped_block(then_block, env);
            }
            for (econd, ebody) in elseifs {
                if expr::eval(econd, env)?.is_truthy() {
                    return exec_scoped_block(ebody, env);
                }
            }
            if let Some(eb) = else_block {
                return exec_scoped_block(eb, env);
            }
            Ok(Flow::nil())
        }

        Stmt::While { cond, body } => {
            while expr::eval(cond, env)?.is_truthy() {
                match exec_scoped_block(body, env)? {
                    Flow::Normal(_) | Flow::Continue => continue,
                    Flow::Break => break,
                    ret @ Flow::Return(_) => return Ok(ret),
                }
            }
            Ok(Flow::nil())
        }

        Stmt::Repeat { body, cond } => {
            // Lua semantics: the `until` condition sees locals declared in
            // the body, so condition and body must share the same scope.
            loop {
                let scope = Environment::with_parent(env.clone());
                match exec_block(body, &scope)? {
                    Flow::Normal(_) | Flow::Continue => {}
                    Flow::Break => break,
                    ret @ Flow::Return(_) => return Ok(ret),
                }
                if expr::eval(cond, &scope)?.is_truthy() {
                    break;
                }
            }
            Ok(Flow::nil())
        }

        Stmt::ForNumeric {
            var,
            var_ty: _,
            from,
            to,
            step,
            body,
        } => exec_for_numeric(var, from, to, step.as_ref(), body, env, span),

        Stmt::ForIn { vars, iter, body } => exec_for_in(vars, iter, body, env, span),

        Stmt::Return(exprs) => {
            let values = if exprs.is_empty() {
                vec![Value::Nil]
            } else {
                eval_expr_list(exprs, env)?
            };
            Ok(Flow::Return(values))
        }

        Stmt::Break => Ok(Flow::Break),
        Stmt::Continue => Ok(Flow::Continue),

        Stmt::Throw(_) => Err(unsupported("throw", span)),
        Stmt::Try { .. } => Err(unsupported("try/catch", span)),
        Stmt::Decl(decl) => exec_decl(decl, env),
    }
}

fn eval_expr_list(
    exprs: &[Spanned<Expr>],
    env: &Rc<RefCell<Environment>>,
) -> Result<Vec<Value>, RuntimeError> {
    let mut out = Vec::new();
    for (i, expr_node) in exprs.iter().enumerate() {
        if i + 1 == exprs.len() {
            out.extend(expr::eval_values(expr_node, env)?);
        } else {
            out.push(expr::eval(expr_node, env)?);
        }
    }
    Ok(out)
}

// ─── Declarations ────────────────────────────────────────────────────────────

fn exec_decl(
    decl: &Spanned<Decl>,
    env: &std::rc::Rc<std::cell::RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let span = decl.span.clone();
    match &decl.value {
        Decl::Function {
            name, params, body, ..
        } => {
            let func = FunctionObject {
                name: Some(name.clone()),
                params: params.clone(),
                body: FunctionBody::Block(body.clone()),
                closure: env.clone(),
            };
            env.borrow_mut()
                .define(name.clone(), Value::Function(std::rc::Rc::new(func)));
            Ok(Flow::nil())
        }
        Decl::Class { .. } => exec_class_decl(decl, env),
         Decl::Interface { .. } => exec_interface_decl(decl, env),
         Decl::Enum { name, variants, methods, .. } => exec_enum_decl(name, variants, methods, env, span),
        Decl::Import { names, path } => exec_import(names, path, env, span),
    }
}

/// Materialize a `Decl::Class` into a [`ClassObject`] and install it under
/// the class's name in `env`. Method closures all capture `env` so they can
/// see the class itself (used by static calls) and other top-level names.
fn exec_class_decl(
    decl: &Spanned<Decl>,
    env: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let span = decl.span.clone();
    let Decl::Class {
        name,
        extends,
        implements,
        members,
        ..
    } = &decl.value
    else {
        unreachable!("exec_class_decl called with non-class decl");
    };

    // Resolve parent class, if any. Must already exist in scope.
    let parent = if let Some(pname) = extends {
        match env.borrow().get(pname) {
            Some(Value::Class(c)) => Some(c),
            Some(other) => {
                return Err(RuntimeError::TypeError {
                    message: format!(
                        "cannot extend `{}`: expected a class but got `{}` — check class definition",
                        pname, other.type_name()
                    ),
                    span,
                });
            }
            None => {
                return Err(RuntimeError::Undefined {
                    name: pname.clone(),
                    span,
                });
            }
        }
    } else {
        None
    };

    let mut field_defs: Vec<FieldDef> = Vec::new();
    let mut methods: HashMap<String, Rc<FunctionObject>> = HashMap::new();
    let mut static_fields: HashMap<String, Value> = HashMap::new();
    let mut static_methods: HashMap<String, Rc<FunctionObject>> = HashMap::new();
    let mut constructor: Option<Rc<FunctionObject>> = None;

    // Scan once so we know whether the class has a constructor (`fn init`).
    // When it doesn't, `local field = expr` declarations are promoted to
    // statics so callers can read them via `ClassName.field` (and through
    // the class-as-`self` convention used inside `static fn`s).
    let has_init_method = members.iter().any(|m| match &m.value {
        ClassMember::Method(meth) => meth.name == "init" && !meth.is_static,
        _ => false,
    });

    for member in members {
        match &member.value {
            ClassMember::Field {
                is_static,
                name: fname,
                default,
                ..
            } => {
                // Promote `local field = expr` to a static when there's no
                // constructor — otherwise we'd never be able to read it.
                let treat_as_static = *is_static || (!has_init_method && default.is_some());
                if treat_as_static {
                    // Static defaults are evaluated once, at class
                    // declaration time, in the enclosing scope.
                    let value = match default {
                        Some(e) => expr::eval(e, env)?,
                        None => Value::Nil,
                    };
                    static_fields.insert(fname.clone(), value);
                } else {
                    field_defs.push(FieldDef {
                        name: fname.clone(),
                        default: default.clone(),
                    });
                }
            }
            ClassMember::Method(m) => {
                let func = Rc::new(make_function(
                    Some(format!("{name}.{}", m.name)),
                    m.params.clone(),
                    m.body.clone(),
                    env,
                ));
                if m.is_static {
                    static_methods.insert(m.name.clone(), func);
                } else if m.name == "init" {
                    // `init` is the only constructor spelling — always promote.
                    constructor = Some(func);
                } else {
                    methods.insert(m.name.clone(), func);
                }
            }
        }
    }

    // Validate that all implemented interfaces' required methods are present.
    // Collect ALL missing methods across ALL interfaces so we report them together.
    let mut missing_methods: Vec<(String, String)> = Vec::new(); // (interface_name, method_name)

    for interface_name in implements {
        match env.borrow().get(interface_name) {
            Some(Value::Interface(iface)) => {
                for required_method in &iface.methods {
                    if !methods.contains_key(required_method.0) {
                        missing_methods.push((interface_name.clone(), required_method.0.clone()));
                    }
                }
            }
            Some(_) => {
                return Err(RuntimeError::TypeError {
                    message: format!(
                        "cannot implement `{}`: expected an interface but got something else",
                        interface_name
                    ),
                    span,
                });
            }
            None => {
                return Err(RuntimeError::Undefined {
                    name: interface_name.clone(),
                    span,
                });
            }
        }
    }

    // Report all missing methods at once
    if !missing_methods.is_empty() {
        let missing_list = missing_methods
            .iter()
            .map(|(iface, method)| format!("`{}` from interface `{}`", method, iface))
            .collect::<Vec<_>>()
            .join(", ");
        return Err(RuntimeError::TypeError {
            message: format!(
                "class `{}` is missing method{}: {}",
                name,
                if missing_methods.len() == 1 { "" } else { "s" },
                missing_list
            ),
            span,
        });
    }

    let class = Rc::new(ClassObject {
        name: name.clone(),
        parent,
        field_defs,
        methods,
        static_fields: RefCell::new(static_fields),
        static_methods,
        constructor,
    });

    env.borrow_mut().define(name.clone(), Value::Class(class));
    Ok(Flow::nil())
 }

 /// Execute an interface declaration and install it in the environment.
 fn exec_interface_decl(
     decl: &Spanned<Decl>,
     env: &Rc<RefCell<Environment>>,
 ) -> Result<Flow, RuntimeError> {
     let Decl::Interface {
         name,
         extends,
         methods,
         ..
     } = &decl.value
     else {
         unreachable!("exec_interface_decl called with non-interface decl");
     };

     // Build a map of method signatures from the interface.
     // For now, we just store the method name and parameter count for basic validation.
     let mut method_sigs = HashMap::new();
     for method in methods {
         let param_count = method.params.len();
         let has_return_type = method.return_ty.is_some();
         method_sigs.insert(method.name.clone(), (param_count, has_return_type));
     }

     let interface_obj = Rc::new(InterfaceObject {
         name: name.clone(),
         extends: extends.clone(),
         methods: method_sigs,
     });

     env.borrow_mut()
         .define(name.clone(), Value::Interface(interface_obj));
     Ok(Flow::nil())
 }

 fn make_function(
    name: Option<String>,
    params: Vec<Param>,
    body: Vec<Spanned<Stmt>>,
    closure: &Rc<RefCell<Environment>>,
) -> FunctionObject {
    let _ = closure; // silence unused if we change capture
    FunctionObject {
        name,
        params,
        body: FunctionBody::Block(body),
        closure: closure.clone(),
    }
}

fn exec_enum_decl(
    enum_name: &str,
    variants: &[Spanned<EnumVariant>],
    methods: &[Method],
    env: &Rc<RefCell<Environment>>,
    _span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    let mut variant_dict = HashMap::new();
    let mut enum_methods = HashMap::new();

    for method in methods {
        let func = Rc::new(make_function(
            Some(format!("{enum_name}.{}", method.name)),
            method.params.clone(),
            method.body.clone(),
            env,
        ));
        enum_methods.insert(method.name.clone(), func);
    }

    // Create all variants (without enum references initially)
    for variant in variants {
        match &variant.value {
            EnumVariant::Bare(name) => {
                let variant_obj = Rc::new(value::EnumVariantObject {
                    enum_name: enum_name.to_string(),
                    variant_name: name.clone(),
                    value: None,
                    enum_obj: RefCell::new(None),
                });
                variant_dict.insert(name.clone(), variant_obj);
            }
            EnumVariant::Valued(name, expr) => {
                let val = expr::eval(expr, env)?;
                let variant_obj = Rc::new(value::EnumVariantObject {
                    enum_name: enum_name.to_string(),
                    variant_name: name.clone(),
                    value: Some(val),
                    enum_obj: RefCell::new(None),
                });
                variant_dict.insert(name.clone(), variant_obj);
            }
        }
    }

    // Create the final enum object with all variants
    let final_enum = Rc::new(value::EnumObject {
        name: enum_name.to_string(),
        variants: variant_dict.clone(),
        methods: enum_methods,
    });

    // Now update each variant to reference the enum
    for variant in variant_dict.values() {
        *variant.enum_obj.borrow_mut() = Some(final_enum.clone());
    }

    env.borrow_mut()
        .define(enum_name.to_string(), Value::Enum(final_enum));
    Ok(Flow::nil())
}

// ─── Imports ─────────────────────────────────────────────────────────────────

/// Execute `import ... from "path"`:
///   1. Resolve `path` relative to the importing file's directory.
///   2. Load (or fetch cached) exports for that module via the shared
///      [`module::ModuleLoader`].
///   3. Bind the requested names — optionally aliased — into `env`.
fn exec_import(
    names: &ImportNames,
    path: &str,
    env: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    let loader = env.borrow().loader().ok_or_else(|| RuntimeError::ImportError {
        message: "no module loader available — running this file with `saule run` should attach one".to_string(),
        span: span.clone(),
    })?;
    let dir = env.borrow().module_dir().ok_or_else(|| RuntimeError::ImportError {
        message: "cannot resolve relative import: current file has no known directory".to_string(),
        span: span.clone(),
    })?;

    let abs = module::resolve_import_path(&dir, path).ok_or_else(|| RuntimeError::ImportError {
        message: format!(
            "could not find module `{path}` (looked for `.sau` / `.saule` / `init.sau`)"
        ),
        span: span.clone(),
    })?;

    let exports = module::load_module(&abs, &loader, span.clone())?;

    match names {
        ImportNames::All => {
            for (n, v) in &exports.values {
                env.borrow_mut().define(n.clone(), v.clone());
            }
        }
        ImportNames::List(list) => {
            for (n, alias) in list {
                let v = exports.values.get(n).cloned().ok_or_else(|| {
                    RuntimeError::ImportError {
                        message: format!(
                            "`{n}` is not exported from `{}`",
                            abs.display()
                        ),
                        span: span.clone(),
                    }
                })?;
                let bind = alias.clone().unwrap_or_else(|| n.clone());
                env.borrow_mut().define(bind, v);
            }
        }
    }

    Ok(Flow::nil())
}

// ─── Assignment ──────────────────────────────────────────────────────────────

fn exec_assign(
    target: &Spanned<Expr>,
    value: &Spanned<Expr>,
    env: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let v = expr::eval(value, env)?;
    assign_target(target, v, env)
}

fn assign_target(
    target: &Spanned<Expr>,
    v: Value,
    env: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    match &target.value {
        Expr::Ident(name) => {
            if env.borrow_mut().assign(name, v) {
                Ok(Flow::nil())
            } else {
                Err(RuntimeError::AssignUndeclared {
                    name: name.clone(),
                    span: target.span.clone(),
                })
            }
        }
        // `obj.field = v` / `Class.static = v`
        Expr::Member { obj, name } => {
            let receiver = expr::eval(obj, env)?;
            assign_member(&receiver, name, v, target.span.clone())
        }
        Expr::Index { obj, index } => {
            let receiver = expr::eval(obj, env)?;
            let index_value = expr::eval(index, env)?;
            assign_index(&receiver, index_value, v, target.span.clone())
        }
        _ => Err(RuntimeError::InvalidAssignTarget {
            span: target.span.clone(),
        }),
    }
}

fn assign_member(
    receiver: &Value,
    name: &str,
    value: Value,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    match receiver {
        Value::Instance(inst) => {
            inst.borrow_mut().fields.insert(name.to_string(), value);
            Ok(Flow::nil())
        }
        Value::Class(class) => {
            // Walk the chain — `Child.staticField = …` should update the
            // declaring class so the change is visible to every sibling.
            if set_static_in_chain(class, name, value.clone()) {
                Ok(Flow::nil())
            } else {
                // Define a fresh static on the most-derived class.
                class
                    .static_fields
                    .borrow_mut()
                    .insert(name.to_string(), value);
                Ok(Flow::nil())
            }
        }
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot assign field `{name}` on value of type `{}` — only instances and classes can have fields assigned",
                other.type_name()
            ),
            span,
        }),
    }
}

fn set_static_in_chain(class: &Rc<crate::value::ClassObject>, name: &str, value: Value) -> bool {
    if class.static_fields.borrow().contains_key(name) {
        class
            .static_fields
            .borrow_mut()
            .insert(name.to_string(), value);
        return true;
    }
    if let Some(parent) = &class.parent {
        return set_static_in_chain(parent, name, value);
    }
    false
}

fn assign_index(
    receiver: &Value,
    index: Value,
    value: Value,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    match receiver {
        Value::Table(items) => {
            items
                .borrow_mut()
                .set(&index, value)
                .map_err(|message| RuntimeError::TypeError {
                    message,
                    span: span.clone(),
                })?;
            Ok(Flow::nil())
        }
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot assign through `[index]` on a `{}` — only tables support indexed assignment",
                other.type_name()
            ),
            span,
        }),
    }
}

// ─── Numeric for ─────────────────────────────────────────────────────────────

fn exec_for_numeric(
    var: &str,
    from: &Spanned<Expr>,
    to: &Spanned<Expr>,
    step: Option<&Spanned<Expr>>,
    body: &[Spanned<Stmt>],
    env: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    let from_v = expr::eval(from, env)?;
    let to_v = expr::eval(to, env)?;
    let step_v = match step {
        Some(e) => expr::eval(e, env)?,
        // Default step matches the loop's numeric type.
        None => match &from_v {
            Value::Float(_) => Value::Float(1.0),
            _ => Value::Int(1),
        },
    };

    match (from_v, to_v, step_v) {
        (Value::Int(f), Value::Int(t), Value::Int(s)) => {
            if s == 0 {
                return Err(RuntimeError::ZeroStep { span });
            }
            run_numeric_loop_int(var, f, t, s, body, env)
        }
        (Value::Float(f), Value::Float(t), Value::Float(s)) => {
            if s == 0.0 {
                return Err(RuntimeError::ZeroStep { span });
            }
            run_numeric_loop_float(var, f, t, s, body, env)
        }
        (f, t, s) => Err(RuntimeError::TypeError {
            message: format!(
                "numeric `for` loop requires all bounds (from, to, step) to be the same numeric type — got `{}`, `{}`, `{}` (use matching integer or float bounds)",
                f.type_name(),
                t.type_name(),
                s.type_name()
            ),
            span,
        }),
    }
}

fn run_numeric_loop_int(
    var: &str,
    from: i64,
    to: i64,
    step: i64,
    body: &[Spanned<Stmt>],
    parent: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let mut i = from;
    while (step > 0 && i <= to) || (step < 0 && i >= to) {
        let scope = Environment::with_parent(parent.clone());
        scope.borrow_mut().define(var.to_string(), Value::Int(i));
        match exec_block(body, &scope)? {
            Flow::Normal(_) | Flow::Continue => {}
            Flow::Break => return Ok(Flow::nil()),
            ret @ Flow::Return(_) => return Ok(ret),
        }
        // Detect overflow so a too-large step doesn't loop forever.
        let (next, overflow) = i.overflowing_add(step);
        if overflow {
            break;
        }
        i = next;
    }
    Ok(Flow::nil())
}

fn run_numeric_loop_float(
    var: &str,
    from: f64,
    to: f64,
    step: f64,
    body: &[Spanned<Stmt>],
    parent: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let mut i = from;
    while (step > 0.0 && i <= to) || (step < 0.0 && i >= to) {
        let scope = Environment::with_parent(parent.clone());
        scope.borrow_mut().define(var.to_string(), Value::Float(i));
        match exec_block(body, &scope)? {
            Flow::Normal(_) | Flow::Continue => {}
            Flow::Break => return Ok(Flow::nil()),
            ret @ Flow::Return(_) => return Ok(ret),
        }
        i += step;
    }
    Ok(Flow::nil())
}

fn exec_for_in(
    vars: &[(String, Option<saule_ast::Type>)],
    iter: &Spanned<Expr>,
    body: &[Spanned<Stmt>],
    env: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    let iter_value = expr::eval(iter, env)?;
    match iter_value {
        Value::Table(items) => {
            // Snapshot to allow the table to mutate during iteration without
            // breaking the loop. Yield array entries first, then map entries.
            let (array, map_entries) = {
                let t = items.borrow();
                let array = t.array.clone();
                let mut map_entries: Vec<(crate::value::TableKey, Value)> =
                    t.map.iter().map(|(k, v)| (k.clone(), v.clone())).collect();
                // Deterministic order: int keys ascending, then strings, then bools.
                map_entries.sort_by(|a, b| match (&a.0, &b.0) {
                    (crate::value::TableKey::Int(x), crate::value::TableKey::Int(y)) => x.cmp(y),
                    (crate::value::TableKey::Int(_), _) => std::cmp::Ordering::Less,
                    (_, crate::value::TableKey::Int(_)) => std::cmp::Ordering::Greater,
                    (crate::value::TableKey::Str(x), crate::value::TableKey::Str(y)) => x.cmp(y),
                    (crate::value::TableKey::Str(_), _) => std::cmp::Ordering::Less,
                    (_, crate::value::TableKey::Str(_)) => std::cmp::Ordering::Greater,
                    (crate::value::TableKey::Bool(x), crate::value::TableKey::Bool(y)) => x.cmp(y),
                });
                (array, map_entries)
            };

            // Helper to bind one (key, value) pair and run the body.
            let run_iter = |key: Value, value: Value| -> Result<Flow, RuntimeError> {
                let scope = Environment::with_parent(env.clone());
                match vars {
                    [(name, _)] => {
                        scope.borrow_mut().define(name.clone(), value);
                    }
                    [(key_name, _), (value_name, _)] => {
                        scope.borrow_mut().define(key_name.clone(), key);
                        scope.borrow_mut().define(value_name.clone(), value);
                    }
                    _ => {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "for-in loops support one value variable or a key/value pair, got {} variables",
                                vars.len()
                            ),
                            span: span.clone(),
                        });
                    }
                }
                exec_block(body, &scope)
            };

            for (i, value) in array.into_iter().enumerate() {
                match run_iter(Value::Int((i + 1) as i64), value)? {
                    Flow::Normal(_) | Flow::Continue => {}
                    Flow::Break => return Ok(Flow::nil()),
                    ret @ Flow::Return(_) => return Ok(ret),
                }
            }
            for (k, v) in map_entries {
                match run_iter(k.to_value(), v)? {
                    Flow::Normal(_) | Flow::Continue => {}
                    Flow::Break => return Ok(Flow::nil()),
                    ret @ Flow::Return(_) => return Ok(ret),
                }
            }
            Ok(Flow::nil())
        }
        other => {
            // For functions and instances we drive a closure-based iterator.
            // Instances must expose an `iter()` method that returns the closure.
            let driver: Value = match &other {
                Value::Function(_) | Value::Native(_) | Value::NativeClosure(_) => other.clone(),
                Value::Instance(_) => {
                    let result = expr::invoke_method_multi(
                        &other,
                        "iter",
                        Vec::new(),
                        span.clone(),
                    )?;
                    let Some(driver) = result.into_iter().next() else {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "`{}.iter()` returned no value — it must return a function",
                                other.type_name()
                            ),
                            span,
                        });
                    };
                    if !matches!(driver, Value::Function(_) | Value::Native(_) | Value::NativeClosure(_)) {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "`iter()` must return a function, got `{}`",
                                driver.type_name()
                            ),
                            span,
                        });
                    }
                    driver
                }
                _ => {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "cannot iterate over a `{}` with `for ... in` — use a table, a function, or a class that implements `Iterable`",
                            other.type_name()
                        ),
                        span,
                    });
                }
            };

            // Drive the closure: call repeatedly with no arguments. Stop when
            // the first returned value is `nil` (Lua's nil-terminator). Each
            // step's returns are bound positionally across the loop variables
            // (extras → nil, surplus values dropped).
            loop {
                let values = expr::call_value_multi(driver.clone(), &[], span.clone())?;
                if values.first().is_none_or(|v| matches!(v, Value::Nil)) {
                    break;
                }
                let scope = Environment::with_parent(env.clone());
                {
                    let mut scope_mut = scope.borrow_mut();
                    for (i, (name, _)) in vars.iter().enumerate() {
                        let v = values.get(i).cloned().unwrap_or(Value::Nil);
                        scope_mut.define(name.clone(), v);
                    }
                }
                match exec_block(body, &scope)? {
                    Flow::Normal(_) | Flow::Continue => {}
                    Flow::Break => return Ok(Flow::nil()),
                    ret @ Flow::Return(_) => return Ok(ret),
                }
            }
            Ok(Flow::nil())
        }
    }
}

//! Statement execution with control-flow propagation.

use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

use saule_ast::{ClassMember, Decl, EnumVariant, Expr, ImportNames, Method, Param, Spanned, Stmt};

use crate::env::Environment;
use crate::error::{RuntimeError, unsupported};
use crate::module;
use crate::value::{self, ClassObject, FieldDef, FunctionBody, FunctionObject, InterfaceObject, Value};

use super::{Flow, expr};

/// Execute a sequence of statements in `env`. Stops at the first non-`Normal`
/// outcome and propagates it.
pub fn exec_block(
    stmts: &[Spanned<Stmt>],
    env: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let mut last = Flow::nil();
    for stmt in stmts {
        match exec(stmt, env)? {
            Flow::Normal(v) => last = Flow::Normal(v),
            other => return Ok(other),
        }
    }
    Ok(last)
}

/// Run a block in a fresh child scope. The scope is dropped on return.
fn exec_scoped_block(
    stmts: &[Spanned<Stmt>],
    parent: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let scope = Environment::with_parent(parent.clone());
    exec_block(stmts, &scope)
}

/// Execute a single statement.
pub fn exec(stmt: &Spanned<Stmt>, env: &Rc<RefCell<Environment>>) -> Result<Flow, RuntimeError> {
    let span = stmt.span.clone();
    match &stmt.value {
        Stmt::Local { name, value, .. } => {
            let v = match value {
                Some(e) => expr::eval(e, env)?,
                None => Value::Nil,
            };
            env.borrow_mut().define(name.clone(), v);
            Ok(Flow::nil())
        }

        Stmt::LocalMulti { names, values } => {
            // Evaluate every RHS first so `local a, b = b, a` works at the
            // outer scope. The final expression may expand into multiple
            // return values (Lua-style destructuring semantics).
            let evaluated = eval_expr_list(values, env)?;
            for (i, (name, _)) in names.iter().enumerate() {
                let v = evaluated.get(i).cloned().unwrap_or(Value::Nil);
                env.borrow_mut().define(name.clone(), v);
            }
            Ok(Flow::nil())
        }

        Stmt::Assign { target, value } => exec_assign(target, value, env),

        Stmt::AssignMulti { targets, values } => {
            // Evaluate all RHS expressions first to support parallel
            // semantics (e.g. `a, b = b, a + b`). The final expression may
            // expand into multiple return values.
            let evaluated = eval_expr_list(values, env)?;
            for (i, target) in targets.iter().enumerate() {
                let v = evaluated.get(i).cloned().unwrap_or(Value::Nil);
                assign_target(target, v, env)?;
            }
            Ok(Flow::nil())
        }

        Stmt::Expr(e) => Ok(Flow::Normal(expr::eval(e, env)?)),

        Stmt::If {
            cond,
            then_block,
            elseifs,
            else_block,
        } => {
            if expr::eval(cond, env)?.is_truthy() {
                return exec_scoped_block(then_block, env);
            }
            for (econd, ebody) in elseifs {
                if expr::eval(econd, env)?.is_truthy() {
                    return exec_scoped_block(ebody, env);
                }
            }
            if let Some(eb) = else_block {
                return exec_scoped_block(eb, env);
            }
            Ok(Flow::nil())
        }

        Stmt::While { cond, body } => {
            while expr::eval(cond, env)?.is_truthy() {
                match exec_scoped_block(body, env)? {
                    Flow::Normal(_) | Flow::Continue => continue,
                    Flow::Break => break,
                    ret @ Flow::Return(_) => return Ok(ret),
                }
            }
            Ok(Flow::nil())
        }

        Stmt::Repeat { body, cond } => {
            // Lua semantics: the `until` condition sees locals declared in
            // the body, so condition and body must share the same scope.
            loop {
                let scope = Environment::with_parent(env.clone());
                match exec_block(body, &scope)? {
                    Flow::Normal(_) | Flow::Continue => {}
                    Flow::Break => break,
                    ret @ Flow::Return(_) => return Ok(ret),
                }
                if expr::eval(cond, &scope)?.is_truthy() {
                    break;
                }
            }
            Ok(Flow::nil())
        }

        Stmt::ForNumeric {
            var,
            var_ty: _,
            from,
            to,
            step,
            body,
        } => exec_for_numeric(var, from, to, step.as_ref(), body, env, span),

        Stmt::ForIn { vars, iter, body } => exec_for_in(vars, iter, body, env, span),

        Stmt::Return(exprs) => {
            let values = if exprs.is_empty() {
                vec![Value::Nil]
            } else {
                eval_expr_list(exprs, env)?
            };
            Ok(Flow::Return(values))
        }

        Stmt::Break => Ok(Flow::Break),
        Stmt::Continue => Ok(Flow::Continue),

        Stmt::Throw(_) => Err(unsupported("throw", span)),
        Stmt::Try { .. } => Err(unsupported("try/catch", span)),
        Stmt::Decl(decl) => exec_decl(decl, env),
    }
}

fn eval_expr_list(
    exprs: &[Spanned<Expr>],
    env: &Rc<RefCell<Environment>>,
) -> Result<Vec<Value>, RuntimeError> {
    let mut out = Vec::new();
    for (i, expr_node) in exprs.iter().enumerate() {
        if i + 1 == exprs.len() {
            out.extend(expr::eval_values(expr_node, env)?);
        } else {
            out.push(expr::eval(expr_node, env)?);
        }
    }
    Ok(out)
}

// ─── Declarations ────────────────────────────────────────────────────────────

fn exec_decl(
    decl: &Spanned<Decl>,
    env: &std::rc::Rc<std::cell::RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let span = decl.span.clone();
    match &decl.value {
        Decl::Function {
            name, params, body, ..
        } => {
            let func = FunctionObject {
                name: Some(name.clone()),
                params: params.clone(),
                body: FunctionBody::Block(body.clone()),
                closure: env.clone(),
                owner_class: std::cell::RefCell::new(None),
            };
            env.borrow_mut()
                .define(name.clone(), Value::Function(std::rc::Rc::new(func)));
            Ok(Flow::nil())
        }
        Decl::Class { .. } => exec_class_decl(decl, env),
         Decl::Interface { .. } => exec_interface_decl(decl, env),
         Decl::Enum { name, variants, methods, .. } => exec_enum_decl(name, variants, methods, env, span),
        Decl::Import { names, path } => exec_import(names, path, env, span),
    }
}

/// Materialize a `Decl::Class` into a [`ClassObject`] and install it under
/// the class's name in `env`. Method closures all capture `env` so they can
/// see the class itself (used by static calls) and other top-level names.
fn exec_class_decl(
    decl: &Spanned<Decl>,
    env: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let span = decl.span.clone();
    let Decl::Class {
        name,
        extends,
        implements,
        members,
        ..
    } = &decl.value
    else {
        unreachable!("exec_class_decl called with non-class decl");
    };

    // Resolve parent class, if any. Must already exist in scope.
    let parent = if let Some(pname) = extends {
        match env.borrow().get(pname) {
            Some(Value::Class(c)) => Some(c),
            Some(other) => {
                return Err(RuntimeError::TypeError {
                    message: format!(
                        "cannot extend `{}`: expected a class but got `{}` — check class definition",
                        pname, other.type_name()
                    ),
                    span,
                });
            }
            None => {
                return Err(RuntimeError::Undefined {
                    name: pname.clone(),
                    span,
                });
            }
        }
    } else {
        None
    };

    let mut field_defs: Vec<FieldDef> = Vec::new();
    let mut methods: HashMap<String, Rc<FunctionObject>> = HashMap::new();
    let mut static_fields: HashMap<String, Value> = HashMap::new();
    let mut static_methods: HashMap<String, Rc<FunctionObject>> = HashMap::new();
    let mut constructor: Option<Rc<FunctionObject>> = None;

    // Scan once so we know whether the class has a constructor (`fn init`).
    // When it doesn't, `local field = expr` declarations are promoted to
    // statics so callers can read them via `ClassName.field` (and through
    // the class-as-`self` convention used inside `static fn`s).
    let has_init_method = members.iter().any(|m| match &m.value {
        ClassMember::Method(meth) => meth.name == "init" && !meth.is_static,
        _ => false,
    });

    for member in members {
        match &member.value {
            ClassMember::Field {
                is_static,
                name: fname,
                default,
                ..
            } => {
                // Promote `local field = expr` to a static when there's no
                // constructor — otherwise we'd never be able to read it.
                let treat_as_static = *is_static || (!has_init_method && default.is_some());
                if treat_as_static {
                    // Static defaults are evaluated once, at class
                    // declaration time, in the enclosing scope.
                    let value = match default {
                        Some(e) => expr::eval(e, env)?,
                        None => Value::Nil,
                    };
                    static_fields.insert(fname.clone(), value);
                } else {
                    field_defs.push(FieldDef {
                        name: fname.clone(),
                        default: default.clone(),
                    });
                }
            }
            ClassMember::Method(m) => {
                let func = Rc::new(make_function(
                    Some(format!("{name}.{}", m.name)),
                    m.params.clone(),
                    m.body.clone(),
                    env,
                ));
                if m.is_static {
                    static_methods.insert(m.name.clone(), func);
                } else if m.name == "init" {
                    // `init` is the only constructor spelling — always promote.
                    constructor = Some(func);
                } else {
                    methods.insert(m.name.clone(), func);
                }
            }
        }
    }

    // Validate that all implemented interfaces' required methods are present.
    // Collect ALL missing methods across ALL interfaces so we report them together.
    let mut missing_methods: Vec<(String, String)> = Vec::new(); // (interface_name, method_name)

    for interface_name in implements {
        match env.borrow().get(interface_name) {
            Some(Value::Interface(iface)) => {
                for required_method in &iface.methods {
                    if !methods.contains_key(required_method.0) {
                        missing_methods.push((interface_name.clone(), required_method.0.clone()));
                    }
                }
            }
            Some(_) => {
                return Err(RuntimeError::TypeError {
                    message: format!(
                        "cannot implement `{}`: expected an interface but got something else",
                        interface_name
                    ),
                    span,
                });
            }
            None => {
                return Err(RuntimeError::Undefined {
                    name: interface_name.clone(),
                    span,
                });
            }
        }
    }

    // Report all missing methods at once
    if !missing_methods.is_empty() {
        let missing_list = missing_methods
            .iter()
            .map(|(iface, method)| format!("`{}` from interface `{}`", method, iface))
            .collect::<Vec<_>>()
            .join(", ");
        return Err(RuntimeError::TypeError {
            message: format!(
                "class `{}` is missing method{}: {}",
                name,
                if missing_methods.len() == 1 { "" } else { "s" },
                missing_list
            ),
            span,
        });
    }

    let class = Rc::new(ClassObject {
        name: name.clone(),
        parent,
        field_defs,
        methods,
        static_fields: RefCell::new(static_fields),
        static_methods,
        constructor,
    });

    // Back-link every method to its owning class so calls to a method via a
    // bare `Value::Function` (e.g. inside another static method that resolved
    // a sibling via `inject_class_statics`) still see the class's statics.
    for f in class.methods.values() {
        f.set_owner_class(&class);
    }
    for f in class.static_methods.values() {
        f.set_owner_class(&class);
    }
    if let Some(c) = class.constructor.as_ref() {
        c.set_owner_class(&class);
    }

    env.borrow_mut().define(name.clone(), Value::Class(class));
    Ok(Flow::nil())
 }

 /// Execute an interface declaration and install it in the environment.
 fn exec_interface_decl(
     decl: &Spanned<Decl>,
     env: &Rc<RefCell<Environment>>,
 ) -> Result<Flow, RuntimeError> {
     let Decl::Interface {
         name,
         extends,
         methods,
         ..
     } = &decl.value
     else {
         unreachable!("exec_interface_decl called with non-interface decl");
     };

     // Build a map of method signatures from the interface.
     // For now, we just store the method name and parameter count for basic validation.
     let mut method_sigs = HashMap::new();
     for method in methods {
         let param_count = method.params.len();
         let has_return_type = method.return_ty.is_some();
         method_sigs.insert(method.name.clone(), (param_count, has_return_type));
     }

     let interface_obj = Rc::new(InterfaceObject {
         name: name.clone(),
         extends: extends.clone(),
         methods: method_sigs,
     });

     env.borrow_mut()
         .define(name.clone(), Value::Interface(interface_obj));
     Ok(Flow::nil())
 }

 fn make_function(
    name: Option<String>,
    params: Vec<Param>,
    body: Vec<Spanned<Stmt>>,
    closure: &Rc<RefCell<Environment>>,
) -> FunctionObject {
    let _ = closure; // silence unused if we change capture
    FunctionObject {
        name,
        params,
        body: FunctionBody::Block(body),
        closure: closure.clone(),
        owner_class: std::cell::RefCell::new(None),
    }
}

fn exec_enum_decl(
    enum_name: &str,
    variants: &[Spanned<EnumVariant>],
    methods: &[Method],
    env: &Rc<RefCell<Environment>>,
    _span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    let mut variant_dict = HashMap::new();
    let mut enum_methods = HashMap::new();

    for method in methods {
        let func = Rc::new(make_function(
            Some(format!("{enum_name}.{}", method.name)),
            method.params.clone(),
            method.body.clone(),
            env,
        ));
        enum_methods.insert(method.name.clone(), func);
    }

    // Create all variants (without enum references initially)
    for variant in variants {
        match &variant.value {
            EnumVariant::Bare(name) => {
                let variant_obj = Rc::new(value::EnumVariantObject {
                    enum_name: enum_name.to_string(),
                    variant_name: name.clone(),
                    value: None,
                    enum_obj: RefCell::new(None),
                });
                variant_dict.insert(name.clone(), variant_obj);
            }
            EnumVariant::Valued(name, expr) => {
                let val = expr::eval(expr, env)?;
                let variant_obj = Rc::new(value::EnumVariantObject {
                    enum_name: enum_name.to_string(),
                    variant_name: name.clone(),
                    value: Some(val),
                    enum_obj: RefCell::new(None),
                });
                variant_dict.insert(name.clone(), variant_obj);
            }
        }
    }

    // Create the final enum object with all variants
    let final_enum = Rc::new(value::EnumObject {
        name: enum_name.to_string(),
        variants: variant_dict.clone(),
        methods: enum_methods,
    });

    // Now update each variant to reference the enum
    for variant in variant_dict.values() {
        *variant.enum_obj.borrow_mut() = Some(final_enum.clone());
    }

    env.borrow_mut()
        .define(enum_name.to_string(), Value::Enum(final_enum));
    Ok(Flow::nil())
}

// ─── Imports ─────────────────────────────────────────────────────────────────

/// Execute `import ... from "path"`:
///   1. Resolve `path` relative to the importing file's directory.
///   2. Load (or fetch cached) exports for that module via the shared
///      [`module::ModuleLoader`].
///   3. Bind the requested names — optionally aliased — into `env`.
fn exec_import(
    names: &ImportNames,
    path: &str,
    env: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    let loader = env.borrow().loader().ok_or_else(|| RuntimeError::ImportError {
        message: "no module loader available — running this file with `saule run` should attach one".to_string(),
        span: span.clone(),
    })?;
    let dir = env.borrow().module_dir().ok_or_else(|| RuntimeError::ImportError {
        message: "cannot resolve relative import: current file has no known directory".to_string(),
        span: span.clone(),
    })?;

    let abs = module::resolve_import_path(&dir, path).ok_or_else(|| RuntimeError::ImportError {
        message: format!(
            "could not find module `{path}` (looked for `.sau` / `.saule` / `init.sau`)"
        ),
        span: span.clone(),
    })?;

    let exports = module::load_module(&abs, &loader, span.clone())?;

    match names {
        ImportNames::All => {
            for (n, v) in &exports.values {
                env.borrow_mut().define(n.clone(), v.clone());
            }
        }
        ImportNames::List(list) => {
            for (n, alias) in list {
                let v = exports.values.get(n).cloned().ok_or_else(|| {
                    RuntimeError::ImportError {
                        message: format!(
                            "`{n}` is not exported from `{}`",
                            abs.display()
                        ),
                        span: span.clone(),
                    }
                })?;
                let bind = alias.clone().unwrap_or_else(|| n.clone());
                env.borrow_mut().define(bind, v);
            }
        }
    }

    Ok(Flow::nil())
}

// ─── Assignment ──────────────────────────────────────────────────────────────

fn exec_assign(
    target: &Spanned<Expr>,
    value: &Spanned<Expr>,
    env: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let v = expr::eval(value, env)?;
    assign_target(target, v, env)
}

fn assign_target(
    target: &Spanned<Expr>,
    v: Value,
    env: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    match &target.value {
        Expr::Ident(name) => {
            if env.borrow_mut().assign(name, v) {
                Ok(Flow::nil())
            } else {
                Err(RuntimeError::AssignUndeclared {
                    name: name.clone(),
                    span: target.span.clone(),
                })
            }
        }
        // `obj.field = v` / `Class.static = v`
        Expr::Member { obj, name } => {
            let receiver = expr::eval(obj, env)?;
            assign_member(&receiver, name, v, target.span.clone())
        }
        Expr::Index { obj, index } => {
            let receiver = expr::eval(obj, env)?;
            let index_value = expr::eval(index, env)?;
            assign_index(&receiver, index_value, v, target.span.clone())
        }
        _ => Err(RuntimeError::InvalidAssignTarget {
            span: target.span.clone(),
        }),
    }
}

fn assign_member(
    receiver: &Value,
    name: &str,
    value: Value,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    match receiver {
        Value::Instance(inst) => {
            inst.borrow_mut().fields.insert(name.to_string(), value);
            Ok(Flow::nil())
        }
        Value::Class(class) => {
            // Walk the chain — `Child.staticField = …` should update the
            // declaring class so the change is visible to every sibling.
            if set_static_in_chain(class, name, value.clone()) {
                Ok(Flow::nil())
            } else {
                // Define a fresh static on the most-derived class.
                class
                    .static_fields
                    .borrow_mut()
                    .insert(name.to_string(), value);
                Ok(Flow::nil())
            }
        }
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot assign field `{name}` on value of type `{}` — only instances and classes can have fields assigned",
                other.type_name()
            ),
            span,
        }),
    }
}

fn set_static_in_chain(class: &Rc<crate::value::ClassObject>, name: &str, value: Value) -> bool {
    if class.static_fields.borrow().contains_key(name) {
        class
            .static_fields
            .borrow_mut()
            .insert(name.to_string(), value);
        return true;
    }
    if let Some(parent) = &class.parent {
        return set_static_in_chain(parent, name, value);
    }
    false
}

fn assign_index(
    receiver: &Value,
    index: Value,
    value: Value,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    match receiver {
        Value::Table(items) => {
            items
                .borrow_mut()
                .set(&index, value)
                .map_err(|message| RuntimeError::TypeError {
                    message,
                    span: span.clone(),
                })?;
            Ok(Flow::nil())
        }
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot assign through `[index]` on a `{}` — only tables support indexed assignment",
                other.type_name()
            ),
            span,
        }),
    }
}

// ─── Numeric for ─────────────────────────────────────────────────────────────

fn exec_for_numeric(
    var: &str,
    from: &Spanned<Expr>,
    to: &Spanned<Expr>,
    step: Option<&Spanned<Expr>>,
    body: &[Spanned<Stmt>],
    env: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    let from_v = expr::eval(from, env)?;
    let to_v = expr::eval(to, env)?;
    let step_v = match step {
        Some(e) => expr::eval(e, env)?,
        // Default step matches the loop's numeric type.
        None => match &from_v {
            Value::Float(_) => Value::Float(1.0),
            _ => Value::Int(1),
        },
    };

    match (from_v, to_v, step_v) {
        (Value::Int(f), Value::Int(t), Value::Int(s)) => {
            if s == 0 {
                return Err(RuntimeError::ZeroStep { span });
            }
            run_numeric_loop_int(var, f, t, s, body, env)
        }
        (Value::Float(f), Value::Float(t), Value::Float(s)) => {
            if s == 0.0 {
                return Err(RuntimeError::ZeroStep { span });
            }
            run_numeric_loop_float(var, f, t, s, body, env)
        }
        (f, t, s) => Err(RuntimeError::TypeError {
            message: format!(
                "numeric `for` loop requires all bounds (from, to, step) to be the same numeric type — got `{}`, `{}`, `{}` (use matching integer or float bounds)",
                f.type_name(),
                t.type_name(),
                s.type_name()
            ),
            span,
        }),
    }
}

fn run_numeric_loop_int(
    var: &str,
    from: i64,
    to: i64,
    step: i64,
    body: &[Spanned<Stmt>],
    parent: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let mut i = from;
    while (step > 0 && i <= to) || (step < 0 && i >= to) {
        let scope = Environment::with_parent(parent.clone());
        scope.borrow_mut().define(var.to_string(), Value::Int(i));
        match exec_block(body, &scope)? {
            Flow::Normal(_) | Flow::Continue => {}
            Flow::Break => return Ok(Flow::nil()),
            ret @ Flow::Return(_) => return Ok(ret),
        }
        // Detect overflow so a too-large step doesn't loop forever.
        let (next, overflow) = i.overflowing_add(step);
        if overflow {
            break;
        }
        i = next;
    }
    Ok(Flow::nil())
}

fn run_numeric_loop_float(
    var: &str,
    from: f64,
    to: f64,
    step: f64,
    body: &[Spanned<Stmt>],
    parent: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let mut i = from;
    while (step > 0.0 && i <= to) || (step < 0.0 && i >= to) {
        let scope = Environment::with_parent(parent.clone());
        scope.borrow_mut().define(var.to_string(), Value::Float(i));
        match exec_block(body, &scope)? {
            Flow::Normal(_) | Flow::Continue => {}
            Flow::Break => return Ok(Flow::nil()),
            ret @ Flow::Return(_) => return Ok(ret),
        }
        i += step;
    }
    Ok(Flow::nil())
}

fn exec_for_in(
    vars: &[(String, Option<saule_ast::Type>)],
    iter: &Spanned<Expr>,
    body: &[Spanned<Stmt>],
    env: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    let iter_value = expr::eval(iter, env)?;
    match iter_value {
        Value::Table(items) => {
            // Snapshot to allow the table to mutate during iteration without
            // breaking the loop. Yield array entries first, then map entries.
            let (array, map_entries) = {
                let t = items.borrow();
                let array = t.array.clone();
                let mut map_entries: Vec<(crate::value::TableKey, Value)> =
                    t.map.iter().map(|(k, v)| (k.clone(), v.clone())).collect();
                // Deterministic order: int keys ascending, then strings, then bools.
                map_entries.sort_by(|a, b| match (&a.0, &b.0) {
                    (crate::value::TableKey::Int(x), crate::value::TableKey::Int(y)) => x.cmp(y),
                    (crate::value::TableKey::Int(_), _) => std::cmp::Ordering::Less,
                    (_, crate::value::TableKey::Int(_)) => std::cmp::Ordering::Greater,
                    (crate::value::TableKey::Str(x), crate::value::TableKey::Str(y)) => x.cmp(y),
                    (crate::value::TableKey::Str(_), _) => std::cmp::Ordering::Less,
                    (_, crate::value::TableKey::Str(_)) => std::cmp::Ordering::Greater,
                    (crate::value::TableKey::Bool(x), crate::value::TableKey::Bool(y)) => x.cmp(y),
                });
                (array, map_entries)
            };

            // Helper to bind one (key, value) pair and run the body.
            let run_iter = |key: Value, value: Value| -> Result<Flow, RuntimeError> {
                let scope = Environment::with_parent(env.clone());
                match vars {
                    [(name, _)] => {
                        scope.borrow_mut().define(name.clone(), value);
                    }
                    [(key_name, _), (value_name, _)] => {
                        scope.borrow_mut().define(key_name.clone(), key);
                        scope.borrow_mut().define(value_name.clone(), value);
                    }
                    _ => {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "for-in loops support one value variable or a key/value pair, got {} variables",
                                vars.len()
                            ),
                            span: span.clone(),
                        });
                    }
                }
                exec_block(body, &scope)
            };

            for (i, value) in array.into_iter().enumerate() {
                match run_iter(Value::Int((i + 1) as i64), value)? {
                    Flow::Normal(_) | Flow::Continue => {}
                    Flow::Break => return Ok(Flow::nil()),
                    ret @ Flow::Return(_) => return Ok(ret),
                }
            }
            for (k, v) in map_entries {
                match run_iter(k.to_value(), v)? {
                    Flow::Normal(_) | Flow::Continue => {}
                    Flow::Break => return Ok(Flow::nil()),
                    ret @ Flow::Return(_) => return Ok(ret),
                }
            }
            Ok(Flow::nil())
        }
        other => {
            // For functions and instances we drive a closure-based iterator.
            // Instances must expose an `iter()` method that returns the closure.
            let driver: Value = match &other {
                Value::Function(_) | Value::Native(_) | Value::NativeClosure(_) => other.clone(),
                Value::Instance(_) => {
                    let result = expr::invoke_method_multi(
                        &other,
                        "iter",
                        Vec::new(),
                        span.clone(),
                    )?;
                    let Some(driver) = result.into_iter().next() else {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "`{}.iter()` returned no value — it must return a function",
                                other.type_name()
                            ),
                            span,
                        });
                    };
                    if !matches!(driver, Value::Function(_) | Value::Native(_) | Value::NativeClosure(_)) {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "`iter()` must return a function, got `{}`",
                                driver.type_name()
                            ),
                            span,
                        });
                    }
                    driver
                }
                _ => {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "cannot iterate over a `{}` with `for ... in` — use a table, a function, or a class that implements `Iterable`",
                            other.type_name()
                        ),
                        span,
                    });
                }
            };

            // Drive the closure: call repeatedly with no arguments. Stop when
            // the first returned value is `nil` (Lua's nil-terminator). Each
            // step's returns are bound positionally across the loop variables
            // (extras → nil, surplus values dropped).
            loop {
                let values = expr::call_value_multi(driver.clone(), &[], span.clone())?;
                if values.first().is_none_or(|v| matches!(v, Value::Nil)) {
                    break;
                }
                let scope = Environment::with_parent(env.clone());
                {
                    let mut scope_mut = scope.borrow_mut();
                    for (i, (name, _)) in vars.iter().enumerate() {
                        let v = values.get(i).cloned().unwrap_or(Value::Nil);
                        scope_mut.define(name.clone(), v);
                    }
                }
                match exec_block(body, &scope)? {
                    Flow::Normal(_) | Flow::Continue => {}
                    Flow::Break => return Ok(Flow::nil()),
                    ret @ Flow::Return(_) => return Ok(ret),
                }
            }
            Ok(Flow::nil())
        }
    }
}

//! Static checks performed between parsing and evaluation.
//!
//! Two flavours of checks live here:
//!
//! 1. **Field initialization** — every non-nullable instance field of a class
//!    with a constructor must be assigned `self.field = ...` somewhere inside
//!    that constructor's body. Fields with defaults are exempt; nullable
//!    fields (`name: string?`) are exempt by design.
//!
//! 2. **Null safety** — values whose static type is nullable cannot be
//!    silently assigned to non-nullable bindings, and members cannot be read
//!    off a nullable receiver without `?.` / `!` / a prior nil-guard. A
//!    lightweight flow-narrowing pass treats `if x != nil then ... end` as
//!    proving `x` is non-nullable inside the then-block (and symmetrically
//!    for `if x == nil ... else ...`).
//!
//! The expression type inference here is intentionally partial: when the
//! checker can't prove a type (e.g. calls, member reads on unknown classes),
//! it returns `None` and conservatively skips the check rather than producing
//! a false positive.

use std::collections::HashMap;
use std::ops::Range;

use miette::Diagnostic;
use saule_ast::{
    BinOp, CallArg, ClassMember, Decl, Expr, LambdaBody, Method, Module, Param, Spanned, Stmt,
    Type,
};
use thiserror::Error;

/// One diagnostic produced by [`check`]. Carries a `miette` source span so
/// the CLI can render it with the offending snippet underlined.
#[derive(Debug, Error, Diagnostic)]
pub enum TypeCheckError {
    #[error("field `{field}` of class `{class}` is never initialized")]
    #[diagnostic(help(
        "assign `self.{field} = ...` in `init`, give the field a default value, or mark it nullable with `?`"
    ))]
    FieldNotInitialized {
        class: String,
        field: String,
        #[label("declared here")]
        span: miette::SourceSpan,
    },

    #[error("cannot assign `nil` to non-nullable type `{ty}`")]
    #[diagnostic(help(
        "mark the type nullable with `?` (e.g. `{ty}?`) or initialize it with a non-nil value"
    ))]
    NilToNonNullable {
        ty: String,
        #[label("`nil` not allowed here")]
        span: miette::SourceSpan,
    },

    #[error("cannot assign a nullable value of type `{from}` to non-nullable type `{to}`")]
    #[diagnostic(help(
        "guard with `if x != nil then ... end`, use `??` to provide a fallback, or force-unwrap with `!`"
    ))]
    NullableToNonNullable {
        from: String,
        to: String,
        #[label("this expression may be `nil`")]
        span: miette::SourceSpan,
    },

    #[error("cannot access `{member}` on nullable type `{ty}`")]
    #[diagnostic(help(
        "use `?.` for safe access, `!` to force-unwrap, or guard with `if x != nil then ... end`"
    ))]
    NullableMemberAccess {
        ty: String,
        member: String,
        #[label("receiver may be `nil`")]
        span: miette::SourceSpan,
    },

    #[error("default value for parameter `{param}` is incompatible with declared type `{ty}`")]
    #[diagnostic(help(
        "the default expression must produce a value of type `{ty}`"
    ))]
    DefaultParamTypeMismatch {
        param: String,
        ty: String,
        #[label("default here")]
        span: miette::SourceSpan,
    },

    #[error("return value is incompatible with declared return type `{ty}`")]
    #[diagnostic(help("this function must return a `{ty}`"))]
    WrongReturnType {
        ty: String,
        #[label("returned here")]
        span: miette::SourceSpan,
    },

    #[error("cannot access private member `{member}` of class `{class}` from outside the class")]
    #[diagnostic(help(
        "`local` fields and methods are only accessible from within `{class}`"
    ))]
    PrivateMemberAccess {
        class: String,
        member: String,
        #[label("private")]
        span: miette::SourceSpan,
    },

    #[error("table value of type `{found}` is incompatible with declared element type `{expected}`")]
    #[diagnostic(help(
        "every value stored in this table must be a `{expected}`"
    ))]
    TableElementTypeMismatch {
        expected: String,
        found: String,
        #[label("wrong value type")]
        span: miette::SourceSpan,
    },

    #[error("table key of type `{found}` is incompatible with declared key type `{expected}`")]
    #[diagnostic(help(
        "this table is declared with key type `{expected}` — pass an index of that type"
    ))]
    TableKeyTypeMismatch {
        expected: String,
        found: String,
        #[label("wrong key type")]
        span: miette::SourceSpan,
    },

    #[error("cannot initialise `table<{key}, {value}>` with an array-style literal")]
    #[diagnostic(help(
        "array-style `{{ ... }}` literals can only fill `table<T>` (integer-keyed); start from `{{}}` and assign by key instead"
    ))]
    TableArrayLiteralForMap {
        key: String,
        value: String,
        #[label("array literal not allowed for a map-typed table")]
        span: miette::SourceSpan,
    },

    #[error("cannot iterate over a `{class}` — it does not implement `Iterable` or `Iterable2`")]
    #[diagnostic(help(
        "add `implements Iterable<T>` (or `Iterable2<K, V>`) to `{class}` and define `fn iter() -> fn(): T?` returning a step closure"
    ))]
    NotIterable {
        class: String,
        #[label("class is not iterable")]
        span: miette::SourceSpan,
    },

    #[error("argument {arg} of `{callee}` expects `{expected}`, got `{found}`")]
    #[diagnostic(help(
        "pass a value of type `{expected}` here — check the signature of `{callee}`"
    ))]
    NativeArgTypeMismatch {
        callee: String,
        arg: usize,
        expected: String,
        found: String,
        #[label("wrong argument type")]
        span: miette::SourceSpan,
    },

    #[error("`{callee}` expects {expected} argument(s), got {found}")]
    #[diagnostic(help("check the signature of `{callee}`"))]
    NativeArity {
        callee: String,
        expected: usize,
        found: usize,
        #[label("wrong number of arguments")]
        span: miette::SourceSpan,
    },
}

fn to_source_span(r: Range<usize>) -> miette::SourceSpan {
    (r.start, r.end.saturating_sub(r.start)).into()
}

// ──────────────────────────────────────────────────────────────────────────────
// Scope: tracks the static types of `local` bindings in lexical scope.
// ──────────────────────────────────────────────────────────────────────────────

#[derive(Default, Clone)]
struct Scope {
    vars: HashMap<String, Type>,
}

impl Scope {
    fn lookup(&self, name: &str) -> Option<&Type> {
        self.vars.get(name)
    }

    fn bind(&mut self, name: String, ty: Type) {
        self.vars.insert(name, ty);
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Public entry point.
// ──────────────────────────────────────────────────────────────────────────────

/// Class info collected by a pre-pass so member-access checks can consult
/// member visibility, parent classes, etc.
#[derive(Default, Clone)]
struct ClassInfo {
    parent: Option<String>,
    /// Interfaces declared on the class (`class C implements A, B`).
    implements: Vec<String>,
    /// member name -> is_private
    members: HashMap<String, bool>,
}

type ClassRegistry = HashMap<String, ClassInfo>;

thread_local! {
    static CLASSES: std::cell::RefCell<ClassRegistry> = std::cell::RefCell::new(HashMap::new());
    static CURRENT_CLASS: std::cell::RefCell<Option<String>> = const { std::cell::RefCell::new(None) };
}

fn with_classes<R>(f: impl FnOnce(&ClassRegistry) -> R) -> R {
    CLASSES.with(|c| f(&c.borrow()))
}

fn current_class() -> Option<String> {
    CURRENT_CLASS.with(|c| c.borrow().clone())
}

fn set_current_class(name: Option<String>) -> Option<String> {
    CURRENT_CLASS.with(|c| std::mem::replace(&mut *c.borrow_mut(), name))
}

/// Look up `member` on `class` (walking the parent chain). Returns
/// `Some((owning_class, is_private))` if found.
fn lookup_member(class: &str, member: &str) -> Option<(String, bool)> {
    with_classes(|reg| {
        let mut cur = Some(class.to_string());
        while let Some(name) = cur {
            if let Some(info) = reg.get(&name) {
                if let Some(&priv_) = info.members.get(member) {
                    return Some((name, priv_));
                }
                cur = info.parent.clone();
            } else {
                return None;
            }
        }
        None
    })
}

/// Does the class (or any ancestor) declare it implements `Iterable` or
/// `Iterable2`? Used by the `for ... in` static check.
fn class_implements_iterable(class: &str) -> bool {
    with_classes(|reg| {
        let mut cur = Some(class.to_string());
        while let Some(name) = cur {
            let Some(info) = reg.get(&name) else {
                return false;
            };
            if info
                .implements
                .iter()
                .any(|i| i == "Iterable" || i == "Iterable2")
            {
                return true;
            }
            cur = info.parent.clone();
        }
        false
    })
}

fn build_registry(module: &Module) -> ClassRegistry {    let mut reg = ClassRegistry::new();
    for stmt in &module.stmts {
        if let Stmt::Decl(d) = &stmt.value
            && let Decl::Class {
                name,
                extends,
                implements,
                members,
                ..
            } = &d.value
        {
            let mut info = ClassInfo {
                parent: extends.clone(),
                implements: implements.clone(),
                members: HashMap::new(),
            };
            for m in members {
                match &m.value {
                    ClassMember::Field {
                        name, is_private, ..
                    } => {
                        info.members.insert(name.clone(), *is_private);
                    }
                    ClassMember::Method(meth) => {
                        info.members.insert(meth.name.clone(), meth.is_private);
                    }
                }
            }
            reg.insert(name.clone(), info);
        }
    }
    reg
}

/// Run the static checks on a parsed module. Returns *all* errors found so
/// the user sees everything in one pass.
pub fn check(module: &Module) -> Vec<TypeCheckError> {
    let reg = build_registry(module);
    CLASSES.with(|c| *c.borrow_mut() = reg);
    let _restore = set_current_class(None);
    let mut errors = Vec::new();
    let mut scope = Scope::default();
    for stmt in &module.stmts {
        check_stmt(&stmt.value, &mut scope, &mut errors);
    }
    CLASSES.with(|c| c.borrow_mut().clear());
    errors
}

// ──────────────────────────────────────────────────────────────────────────────
// Statement walker. Threads a `Scope` so we know the static type of every
// `local` we've seen on the current path, and so narrowing in `if`/`else` can
// override types for the duration of a sub-block.
// ──────────────────────────────────────────────────────────────────────────────

fn check_stmt(stmt: &Stmt, scope: &mut Scope, errors: &mut Vec<TypeCheckError>) {
    match stmt {
        Stmt::Decl(decl) => check_decl(&decl.value, errors),

        Stmt::Local { name, ty, value } => {
            if let (Some(ty), Some(v)) = (ty, value) {
                check_expr(v, scope, errors);
                check_assignment_compat(ty, v, scope, errors);
                scope.bind(name.clone(), ty.clone());
            } else if let Some(v) = value {
                check_expr(v, scope, errors);
                if let Some(t) = infer(v, scope) {
                    scope.bind(name.clone(), t);
                }
            } else if let Some(ty) = ty {
                scope.bind(name.clone(), ty.clone());
            }
        }

        Stmt::LocalMulti { names, values } => {
            for v in values {
                check_expr(v, scope, errors);
            }
            for (i, (name, ty_opt)) in names.iter().enumerate() {
                if let (Some(ty), Some(v)) = (ty_opt, values.get(i)) {
                    check_assignment_compat(ty, v, scope, errors);
                }
                if let Some(ty) = ty_opt {
                    scope.bind(name.clone(), ty.clone());
                } else if let Some(v) = values.get(i)
                    && let Some(t) = infer(v, scope)
                {
                    scope.bind(name.clone(), t);
                }
            }
        }

        Stmt::Assign { target, value } => {
            check_expr(target, scope, errors);
            check_expr(value, scope, errors);
            if let Expr::Ident(n) = &target.value
                && let Some(ty) = scope.lookup(n).cloned()
            {
                check_assignment_compat(&ty, value, scope, errors);
            }
            // `t[k] = v` — enforce the table's static key/value types.
            if let Expr::Index { obj, index } = &target.value
                && let Some(Type::Table { key, value: elem_ty }) = infer(obj, scope)
            {
                let key_ty = key
                    .as_deref()
                    .cloned()
                    .unwrap_or_else(|| Type::Named("integer".into()));
                check_table_key_compat(&key_ty, index, scope, errors);
                check_element_compat(&elem_ty, value, scope, errors);
            }
        }

        Stmt::AssignMulti { targets, values } => {
            for t in targets {
                check_expr(t, scope, errors);
            }
            for v in values {
                check_expr(v, scope, errors);
            }
            for (i, target) in targets.iter().enumerate() {
                if let Expr::Ident(n) = &target.value
                    && let (Some(ty), Some(v)) = (scope.lookup(n).cloned(), values.get(i))
                {
                    check_assignment_compat(&ty, v, scope, errors);
                }
            }
        }

        Stmt::Expr(e) => check_expr(e, scope, errors),

        Stmt::If {
            cond,
            then_block,
            elseifs,
            else_block,
        } => {
            check_expr(cond, scope, errors);

            // Branch the scope so narrowing in the then-block doesn't leak.
            let mut then_scope = scope.clone();
            narrow_truthy(cond, &mut then_scope);
            for s in then_block {
                check_stmt(&s.value, &mut then_scope, errors);
            }

            for (econd, ebody) in elseifs {
                check_expr(econd, scope, errors);
                let mut ei_scope = scope.clone();
                narrow_truthy(econd, &mut ei_scope);
                for s in ebody {
                    check_stmt(&s.value, &mut ei_scope, errors);
                }
            }

            if let Some(block) = else_block {
                let mut else_scope = scope.clone();
                narrow_falsy(cond, &mut else_scope);
                for s in block {
                    check_stmt(&s.value, &mut else_scope, errors);
                }
            }
        }

        Stmt::While { cond, body } | Stmt::Repeat { body, cond } => {
            check_expr(cond, scope, errors);
            let mut body_scope = scope.clone();
            narrow_truthy(cond, &mut body_scope);
            for s in body {
                check_stmt(&s.value, &mut body_scope, errors);
            }
        }

        Stmt::ForNumeric {
            var,
            var_ty,
            from,
            to,
            step,
            body,
        } => {
            check_expr(from, scope, errors);
            check_expr(to, scope, errors);
            if let Some(s) = step {
                check_expr(s, scope, errors);
            }
            let mut body_scope = scope.clone();
            let ty = var_ty.clone().unwrap_or(Type::Named("integer".into()));
            body_scope.bind(var.clone(), ty);
            for s in body {
                check_stmt(&s.value, &mut body_scope, errors);
            }
        }

        Stmt::ForIn { vars, iter, body } => {
            check_expr(iter, scope, errors);
            // If the iter expression is a known class instance, it must
            // implement `Iterable` or `Iterable2` (walking the parent chain).
            if let Some(Type::Named(class_name)) = infer(iter, scope)
                && with_classes(|reg| reg.contains_key(&class_name))
                && !class_implements_iterable(&class_name)
            {
                errors.push(TypeCheckError::NotIterable {
                    class: class_name,
                    span: to_source_span(iter.span.clone()),
                });
            }
            let mut body_scope = scope.clone();
            for (name, ty_opt) in vars {
                if let Some(ty) = ty_opt {
                    body_scope.bind(name.clone(), ty.clone());
                }
            }
            for s in body {
                check_stmt(&s.value, &mut body_scope, errors);
            }
        }

        Stmt::Return(values) => {
            for v in values {
                check_expr(v, scope, errors);
            }
        }

        Stmt::Throw(e) => check_expr(e, scope, errors),

        Stmt::Try {
            body,
            catch_var,
            catch_ty,
            catch_body,
        } => {
            let mut body_scope = scope.clone();
            for s in body {
                check_stmt(&s.value, &mut body_scope, errors);
            }
            let mut catch_scope = scope.clone();
            catch_scope.bind(catch_var.clone(), catch_ty.clone());
            for s in catch_body {
                check_stmt(&s.value, &mut catch_scope, errors);
            }
        }

        Stmt::Break | Stmt::Continue => {}
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Declaration walker.
// ──────────────────────────────────────────────────────────────────────────────

fn check_decl(decl: &Decl, errors: &mut Vec<TypeCheckError>) {
    match decl {
        Decl::Class {
            name: class_name,
            members,
            ..
        } => check_class(class_name, members, errors),
        Decl::Function {
            params,
            return_ty,
            body,
            ..
        } => {
            let mut scope = Scope::default();
            check_default_params(params, &scope, errors);
            seed_params(&mut scope, params);
            for s in body {
                check_stmt(&s.value, &mut scope, errors);
            }
            if let Some(rt) = return_ty {
                check_returns(body, rt, &scope, errors);
            }
        }
        _ => {}
    }
}

fn seed_params(scope: &mut Scope, params: &[Param]) {
    for p in params {
        scope.bind(p.name.clone(), p.ty.clone());
    }
}

/// Check each parameter default against the declared parameter type.
fn check_default_params(params: &[Param], scope: &Scope, errors: &mut Vec<TypeCheckError>) {
    for p in params {
        if let Some(d) = &p.default
            && !is_assignment_compatible(&p.ty, d, scope)
        {
            errors.push(TypeCheckError::DefaultParamTypeMismatch {
                param: p.name.clone(),
                ty: type_to_string(&p.ty),
                span: to_source_span(d.span.clone()),
            });
        }
    }
}

/// Walk a function/method body looking for `return v` statements whose first
/// value can be proved incompatible with `return_ty`.
fn check_returns(
    body: &[Spanned<Stmt>],
    return_ty: &Type,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    for s in body {
        walk_returns(&s.value, return_ty, scope, errors);
    }
}

fn walk_returns(
    stmt: &Stmt,
    return_ty: &Type,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    match stmt {
        Stmt::Return(values) => {
            if let Some(v) = values.first()
                && !is_assignment_compatible(return_ty, v, scope)
            {
                errors.push(TypeCheckError::WrongReturnType {
                    ty: type_to_string(return_ty),
                    span: to_source_span(v.span.clone()),
                });
            }
        }
        Stmt::If {
            then_block,
            elseifs,
            else_block,
            ..
        } => {
            for s in then_block {
                walk_returns(&s.value, return_ty, scope, errors);
            }
            for (_, b) in elseifs {
                for s in b {
                    walk_returns(&s.value, return_ty, scope, errors);
                }
            }
            if let Some(b) = else_block {
                for s in b {
                    walk_returns(&s.value, return_ty, scope, errors);
                }
            }
        }
        Stmt::While { body, .. }
        | Stmt::Repeat { body, .. }
        | Stmt::ForNumeric { body, .. }
        | Stmt::ForIn { body, .. } => {
            for s in body {
                walk_returns(&s.value, return_ty, scope, errors);
            }
        }
        Stmt::Try {
            body, catch_body, ..
        } => {
            for s in body {
                walk_returns(&s.value, return_ty, scope, errors);
            }
            for s in catch_body {
                walk_returns(&s.value, return_ty, scope, errors);
            }
        }
        _ => {}
    }
}

/// True when we can *prove* the value is incompatible-free with the target
/// type. Returns true when we can't decide (conservative: don't false-positive).
fn is_assignment_compatible(decl_ty: &Type, value: &Spanned<Expr>, scope: &Scope) -> bool {
    if is_nullable(decl_ty) {
        // Nullable target accepts anything we can express.
        return true;
    }
    if matches!(value.value, Expr::Nil) {
        return false;
    }
    let Some(value_ty) = infer(value, scope) else {
        return true;
    };
    if is_nullable(&value_ty) {
        return false;
    }
    match (decl_ty, &value_ty) {
        (Type::Named(a), Type::Named(b)) => {
            if a == b || a == "any" || b == "any" {
                true
            } else {
                // Allow numeric literals in either direction only when same name.
                false
            }
        }
        _ => true,
    }
}

fn check_class(
    class_name: &str,
    members: &[Spanned<ClassMember>],
    errors: &mut Vec<TypeCheckError>,
) {
    // Locate the constructor body: the non-static `fn init` method.
    let mut ctor_body: Option<&Vec<Spanned<Stmt>>> = None;
    for m in members {
        match &m.value {
            ClassMember::Method(Method {
                name,
                is_static: false,
                body,
                ..
            }) if name == "init" => {
                ctor_body = Some(body);
            }
            _ => {}
        }
    }

    // Validate field defaults: `local x: string = nil` is an error regardless
    // of whether a constructor exists or the field is static.
    for m in members {
        if let ClassMember::Field {
            ty,
            default: Some(default_expr),
            ..
        } = &m.value
        {
            let scope = Scope::default();
            check_assignment_compat(ty, default_expr, &scope, errors);
        }
    }

    if let Some(body) = ctor_body {
        let mut assigned: Vec<String> = Vec::new();
        for s in body {
            collect_self_assignments(&s.value, &mut assigned);
        }
        for m in members {
            if let ClassMember::Field {
                is_static: false,
                name,
                ty,
                default,
                ..
            } = &m.value
            {
                if default.is_some() || is_nullable(ty) {
                    continue;
                }
                if !assigned.iter().any(|a| a == name) {
                    errors.push(TypeCheckError::FieldNotInitialized {
                        class: class_name.to_string(),
                        field: name.clone(),
                        span: to_source_span(m.span.clone()),
                    });
                }
            }
        }
    }

    // Walk every method body with a scope seeded from its parameters,
    // and within `CURRENT_CLASS` set so private-member checks know we're
    // *inside* `class_name`. Also validate default parameters and return types.
    let prev = set_current_class(Some(class_name.to_string()));
    for m in members {
        if let ClassMember::Method(meth) = &m.value {
            let mut scope = Scope::default();
            // `self` resolves to the class itself in `static fn` and to an
            // instance otherwise. Seed it as the class name so member-existence
            // checks on `self.foo` consult the class registry.
            scope.bind("self".to_string(), Type::Named(class_name.to_string()));
            check_default_params(&meth.params, &scope, errors);
            seed_params(&mut scope, &meth.params);
            for s in &meth.body {
                check_stmt(&s.value, &mut scope, errors);
            }
            if let Some(rt) = &meth.return_ty {
                check_returns(&meth.body, rt, &scope, errors);
            }
        }
    }
    set_current_class(prev);
}

// ──────────────────────────────────────────────────────────────────────────────
// Expression checker — walks expressions looking for `obj.member` /
// `obj.method(...)` where `obj` has a statically-known nullable type.
// ──────────────────────────────────────────────────────────────────────────────

fn check_expr(expr: &Spanned<Expr>, scope: &Scope, errors: &mut Vec<TypeCheckError>) {
    match &expr.value {
        Expr::Member { obj, name } => {
            check_expr(obj, scope, errors);
            report_if_nullable_receiver(obj, name, scope, errors);
            report_if_private(obj, name, scope, errors);
        }
        Expr::MethodCall { obj, method, args } => {
            check_expr(obj, scope, errors);
            report_if_nullable_receiver(obj, method, scope, errors);
            report_if_private(obj, method, scope, errors);
            for a in args {
                check_arg(a, scope, errors);
            }
        }
        Expr::Call { callee, args } => {
            // `obj.method(args)` is parsed as Call(Member { obj, name }, args)
            // — same nullable-receiver rule applies.
            if let Expr::Member { obj, name } = &callee.value {
                check_expr(obj, scope, errors);
                report_if_nullable_receiver(obj, name, scope, errors);
                report_if_private(obj, name, scope, errors);
            } else {
                check_expr(callee, scope, errors);
            }
            for a in args {
                check_arg(a, scope, errors);
            }
            // If the callee resolves to a known native signature, check the
            // argument types positionally. Named arguments are skipped (those
            // aren't supported on natives anyway, and they error at runtime).
            if let Some(qname) = native_callee_name(callee)
                && let Some(sig) = crate::stdlib::sigs::lookup(&qname)
            {
                check_native_args(&qname, &sig, args, scope, errors, expr.span.clone());
            }
        }
        Expr::SafeMember { obj, .. } => check_expr(obj, scope, errors),
        Expr::Index { obj, index } => {
            check_expr(obj, scope, errors);
            check_expr(index, scope, errors);
        }
        Expr::Unary { rhs, .. } => check_expr(rhs, scope, errors),
        Expr::Binary { lhs, rhs, .. } => {
            check_expr(lhs, scope, errors);
            check_expr(rhs, scope, errors);
        }
        Expr::ForceUnwrap(inner) => check_expr(inner, scope, errors),
        Expr::Table(items) => {
            for e in items {
                check_expr(e, scope, errors);
            }
        }
        Expr::Lambda { params, body, .. } => {
            let mut lscope = scope.clone();
            seed_params(&mut lscope, params);
            match body {
                LambdaBody::Expr(e) => check_expr(e, &lscope, errors),
                LambdaBody::Block(stmts) => {
                    for s in stmts {
                        check_stmt(&s.value, &mut lscope, errors);
                    }
                }
            }
        }
        _ => {}
    }
}

fn check_arg(arg: &CallArg, scope: &Scope, errors: &mut Vec<TypeCheckError>) {
    match arg {
        CallArg::Positional(e) | CallArg::Named { value: e, .. } => check_expr(e, scope, errors),
    }
}

/// Check positional arguments of a native call against the registered
/// signature. Skips named arguments (natives don't support them; the runtime
/// will surface that as an error).
///
/// Heuristics intentionally lenient:
///   * `any` and `T?` parameters accept anything (incl. nil) — they're the
///     "I'll figure it out" slots.
///   * Variadic / over-supplied calls aren't penalised when the declared
///     param list runs out — many natives accept `...rest` (variadic) which
///     isn't expressed in the sig yet.
///   * If `infer` can't produce a type for the argument, we skip silently.
fn check_native_args(
    callee: &str,
    sig: &crate::stdlib::sigs::NativeSig,
    args: &[CallArg],
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
    call_span: std::ops::Range<usize>,
) {
    // Count required positional params (every param up to the first
    // nullable / `any` is required — nullable+`any` slots are optional).
    let required: usize = sig
        .params
        .iter()
        .take_while(|p| !is_nullable(p) && !is_any(p))
        .count();
    let positional: Vec<&CallArg> = args.iter().filter(|a| matches!(a, CallArg::Positional(_))).collect();
    if positional.len() < required {
        errors.push(TypeCheckError::NativeArity {
            callee: callee.to_string(),
            expected: required,
            found: positional.len(),
            span: to_source_span(call_span.clone()),
        });
        return;
    }

    // Reject extras when the native is not variadic. Don't bail though —
    // continue checking the known positions for type mismatches.
    if sig.variadic.is_none() && positional.len() > sig.params.len() {
        errors.push(TypeCheckError::NativeArity {
            callee: callee.to_string(),
            expected: sig.params.len(),
            found: positional.len(),
            span: to_source_span(call_span),
        });
    }

    for (i, arg) in args.iter().enumerate() {
        // Pick the expected type for slot `i`:
        //   - within declared params: use `params[i]`
        //   - past the end: use the variadic element type (or stop if absent)
        let expected = match sig.params.get(i) {
            Some(t) => t,
            None => match &sig.variadic {
                Some(t) => t,
                None => break,
            },
        };
        let value_expr = match arg {
            CallArg::Positional(e) => e,
            CallArg::Named { .. } => continue,
        };
        if is_any(expected) {
            continue;
        }
        let Some(found_ty) = infer(value_expr, scope) else {
            continue;
        };
        if !types_compatible(expected, &found_ty) {
            errors.push(TypeCheckError::NativeArgTypeMismatch {
                callee: callee.to_string(),
                arg: i + 1,
                expected: type_to_string(expected),
                found: type_to_string(&found_ty),
                span: to_source_span(value_expr.span.clone()),
            });
        }
    }
}

fn is_any(t: &Type) -> bool {
    matches!(t, Type::Named(n) if n == "any")
}

fn report_if_nullable_receiver(
    obj: &Spanned<Expr>,
    member: &str,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    if let Some(ty) = infer(obj, scope)
        && is_nullable(&ty)
    {
        errors.push(TypeCheckError::NullableMemberAccess {
            ty: type_to_string(&ty),
            member: member.to_string(),
            span: to_source_span(obj.span.clone()),
        });
    }
}

/// Reject access to `local` (private) members from outside the owning class.
/// `self.foo` is always permitted; access via any other expression is checked.
fn report_if_private(
    obj: &Spanned<Expr>,
    member: &str,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    // Accesses through `self` are always allowed (inside their own class).
    if matches!(obj.value, Expr::Self_) {
        return;
    }
    let Some(ty) = infer(obj, scope) else { return };
    let class_name = match strip_nullable(ty) {
        Type::Named(n) => n,
        _ => return,
    };
    let Some((owning, is_private)) = lookup_member(&class_name, member) else {
        return;
    };
    if is_private && current_class().as_deref() != Some(owning.as_str()) {
        errors.push(TypeCheckError::PrivateMemberAccess {
            class: owning,
            member: member.to_string(),
            span: to_source_span(obj.span.end..obj.span.end + member.len() + 1),
        });
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Assignment compatibility — only flags the cases we can prove are wrong.
// ──────────────────────────────────────────────────────────────────────────────

fn check_assignment_compat(
    decl_ty: &Type,
    value: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    if is_nullable(decl_ty) {
        return;
    }
    if matches!(value.value, Expr::Nil) {
        errors.push(TypeCheckError::NilToNonNullable {
            ty: type_to_string(decl_ty),
            span: to_source_span(value.span.clone()),
        });
        return;
    }

    // Table-aware checks for array-style literals assigned to a typed table.
    if let (Type::Table { key, value: elem_ty }, Expr::Table(items)) = (decl_ty, &value.value) {
        // `{a, b, c}` literal cannot fill a map-typed table whose key is not
        // integer-compatible.
        if let Some(k) = key
            && !is_integer_like(k)
            && !items.is_empty()
        {
            errors.push(TypeCheckError::TableArrayLiteralForMap {
                key: type_to_string(k),
                value: type_to_string(elem_ty),
                span: to_source_span(value.span.clone()),
            });
            return;
        }
        // Each element must match the declared value type.
        for item in items {
            check_element_compat(elem_ty, item, scope, errors);
        }
        return;
    }

    if let Some(value_ty) = infer(value, scope)
        && is_nullable(&value_ty)
    {
        errors.push(TypeCheckError::NullableToNonNullable {
            from: type_to_string(&value_ty),
            to: type_to_string(decl_ty),
            span: to_source_span(value.span.clone()),
        });
    }
}

/// Index key must match the table's declared key type.
fn check_table_key_compat(
    expected: &Type,
    index: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    if let Some(idx_ty) = infer(index, scope)
        && !types_compatible(expected, &idx_ty)
    {
        errors.push(TypeCheckError::TableKeyTypeMismatch {
            expected: type_to_string(expected),
            found: type_to_string(&idx_ty),
            span: to_source_span(index.span.clone()),
        });
    }
}

/// True for `integer` and `any` — the key types that an array-style literal
/// can satisfy.
fn is_integer_like(ty: &Type) -> bool {
    matches!(ty, Type::Named(n) if n == "integer" || n == "any")
}

/// Element-of-table compatibility — accepts literals/`Ident`s whose inferred
/// type matches, and stays quiet otherwise (conservative).
fn check_element_compat(
    expected: &Type,
    value: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    if let Some(value_ty) = infer(value, scope)
        && !types_compatible(expected, &value_ty)
    {
        errors.push(TypeCheckError::TableElementTypeMismatch {
            expected: type_to_string(expected),
            found: type_to_string(&value_ty),
            span: to_source_span(value.span.clone()),
        });
    }
}

/// Conservative type compatibility — names match (or either is `any`), or
/// `value_ty` is `Nullable` of a compatible inner, etc.
fn types_compatible(expected: &Type, value_ty: &Type) -> bool {
    match (expected, value_ty) {
        // Same-name primitives, plus `any` on either side, plus `nil` on the
        // value side (nil is universally assignable; nullable-rejection is
        // handled separately by `NullableToNonNullable`).
        (Type::Named(a), Type::Named(b)) => {
            if a == b || a == "any" || b == "any" || b == "nil" {
                return true;
            }
            // `number` is the sentinel used in native sigs to mean
            // "integer or float" — accept either.
            if a == "number" && (b == "integer" || b == "float" || b == "number") {
                return true;
            }
            false
        }
        // `table<any>` (or `table<any, any>`) matches any table — used by
        // native sigs like `pairs(t)` / `Table.insert(t, ...)` to mean
        // "any table".
        (
            Type::Table { key: ek, value: ev },
            Type::Table { key: vk, value: vv },
        ) => {
            let key_ok = match (ek, vk) {
                (None, None) => true,
                (Some(a), Some(b)) => types_compatible(a, b),
                // Cross-shape (`table<T>` vs `table<K, V>`) only when one
                // side is the `any` wildcard.
                _ => is_any(ev),
            };
            key_ok && (is_any(ev) || types_compatible(ev, vv))
        }
        // Expected table, but value is the bare type-name `table`, `any` or
        // `nil` — accept (caller has erased the element type, or it's nil).
        (Type::Table { .. }, Type::Named(n)) if n == "table" || n == "any" || n == "nil" => true,
        // Expected `any` / `table` / `nil` named slot, value is a table —
        // accept (we widen to the named slot).
        (Type::Named(n), Type::Table { .. }) if n == "table" || n == "any" => true,
        (Type::Nullable(a), b) => types_compatible(a, b),
        (a, Type::Nullable(b)) => types_compatible(a, b),
        // Function / Tuple shapes — only equal-shape is strictly compatible,
        // but the checker doesn't track those precisely yet. Accept rather
        // than emit false positives.
        (Type::Function { .. }, Type::Function { .. }) => true,
        (Type::Tuple(_), Type::Tuple(_)) => true,
        // Different kinds (e.g. table vs integer) — reject.
        _ => false,
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Lightweight type inference.
//
// Returns `Some(ty)` only when we can prove the type. Anything we can't see
// through (calls, member reads on unknown classes, indexing) returns `None`,
// and callers treat that as "don't know, don't complain".
// ──────────────────────────────────────────────────────────────────────────────

fn infer(expr: &Spanned<Expr>, scope: &Scope) -> Option<Type> {
    match &expr.value {
        Expr::Nil => Some(Type::Named("nil".into())),
        Expr::Int(_) => Some(Type::Named("integer".into())),
        Expr::Float(_) => Some(Type::Named("float".into())),
        Expr::Bool(_) => Some(Type::Named("boolean".into())),
        Expr::Str(_) => Some(Type::Named("string".into())),
        Expr::Ident(n) => scope.lookup(n).cloned(),
        Expr::SafeMember { .. } => Some(Type::Nullable(Box::new(Type::Named("any".into())))),
        Expr::ForceUnwrap(inner) => match infer(inner, scope)? {
            Type::Nullable(t) => Some(*t),
            other => Some(other),
        },
        Expr::Binary { op, lhs, rhs } => match op {
            BinOp::Coalesce => {
                // `lhs ?? rhs`: result is non-nullable iff `rhs` is non-nullable.
                match (infer(lhs, scope), infer(rhs, scope)) {
                    (Some(lt), Some(rt)) => {
                        let base = strip_nullable(lt);
                        if is_nullable(&rt) {
                            Some(Type::Nullable(Box::new(base)))
                        } else {
                            Some(base)
                        }
                    }
                    _ => None,
                }
            }
            BinOp::Eq | BinOp::NotEq | BinOp::Lt | BinOp::LtEq | BinOp::Gt | BinOp::GtEq => {
                Some(Type::Named("boolean".into()))
            }
            BinOp::And | BinOp::Or => None,
            BinOp::Concat => Some(Type::Named("string".into())),
            BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div | BinOp::Mod => {
                infer(lhs, scope).or_else(|| infer(rhs, scope))
            }
        },
        // `Foo(args)` where `Foo` is a known class → produces a `Foo`.
        // Otherwise, look up the qualified callee name in the native signature
        // table (e.g. `String.byte`, `Math.tointeger`, `assert`).
        Expr::Call { callee, .. } => {
            if let Expr::Ident(n) = &callee.value
                && with_classes(|reg| reg.contains_key(n))
            {
                Some(Type::Named(n.clone()))
            } else if let Some(qname) = native_callee_name(callee)
                && let Some(sig) = crate::stdlib::sigs::lookup(&qname)
            {
                first_or_tuple(sig.returns)
            } else {
                None
            }
        }
        _ => None,
    }
}

fn strip_nullable(ty: Type) -> Type {
    match ty {
        Type::Nullable(t) => *t,
        other => other,
    }
}

/// Build a qualified callee name suitable for `stdlib::sigs::lookup`:
/// `assert` or `String.byte`.
fn native_callee_name(callee: &Spanned<Expr>) -> Option<String> {
    match &callee.value {
        Expr::Ident(n) => Some(n.clone()),
        Expr::Member { obj, name } => {
            if let Expr::Ident(class) = &obj.value {
                Some(format!("{class}.{name}"))
            } else {
                None
            }
        }
        _ => None,
    }
}

/// Collapse a returns-list into a single inferred type: single returns stay
/// as-is, multi-returns become a `Type::Tuple`.
fn first_or_tuple(returns: Vec<Type>) -> Option<Type> {
    match returns.len() {
        0 => None,
        1 => returns.into_iter().next(),
        _ => Some(Type::Tuple(returns)),
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Flow narrowing.
//
// `narrow_truthy(cond, scope)` — apply the assumptions that hold when `cond`
// is true. Today: `x != nil` and `nil != x` strip `Nullable` off `x`. `and`
// chains compose.
//
// `narrow_falsy(cond, scope)` — apply the assumptions when `cond` is false.
// Used by the else-branch: `if x == nil then ... else ... end` narrows `x`
// in the else.
// ──────────────────────────────────────────────────────────────────────────────

fn narrow_truthy(cond: &Spanned<Expr>, scope: &mut Scope) {
    match &cond.value {
        Expr::Binary {
            op: BinOp::NotEq,
            lhs,
            rhs,
        } => {
            if let Some(name) = pick_ident_compared_to_nil(lhs, rhs)
                && let Some(Type::Nullable(t)) = scope.lookup(name).cloned()
            {
                scope.bind(name.to_string(), *t);
            }
        }
        Expr::Binary {
            op: BinOp::And,
            lhs,
            rhs,
        } => {
            narrow_truthy(lhs, scope);
            narrow_truthy(rhs, scope);
        }
        _ => {}
    }
}

fn narrow_falsy(cond: &Spanned<Expr>, scope: &mut Scope) {
    if let Expr::Binary {
        op: BinOp::Eq,
        lhs,
        rhs,
    } = &cond.value
        && let Some(name) = pick_ident_compared_to_nil(lhs, rhs)
        && let Some(Type::Nullable(t)) = scope.lookup(name).cloned()
    {
        scope.bind(name.to_string(), *t);
    }
}

/// If `lhs` / `rhs` is `(Ident(x), Nil)` in either order, return `Some(x)`.
fn pick_ident_compared_to_nil<'a>(
    lhs: &'a Spanned<Expr>,
    rhs: &'a Spanned<Expr>,
) -> Option<&'a str> {
    match (&lhs.value, &rhs.value) {
        (Expr::Ident(n), Expr::Nil) => Some(n),
        (Expr::Nil, Expr::Ident(n)) => Some(n),
        _ => None,
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Misc helpers.
// ──────────────────────────────────────────────────────────────────────────────

fn type_to_string(ty: &Type) -> String {
    match ty {
        Type::Named(n) => n.clone(),
        Type::Nullable(inner) => format!("{}?", type_to_string(inner)),
        Type::Table { key: None, value } => format!("table<{}>", type_to_string(value)),
        Type::Table {
            key: Some(k),
            value,
        } => format!("table<{}, {}>", type_to_string(k), type_to_string(value)),
        other => format!("{:?}", other),
    }
}

fn is_nullable(ty: &Type) -> bool {
    match ty {
        Type::Nullable(_) => true,
        Type::Named(n) => n == "nil",
        _ => false,
    }
}

/// Walk a statement collecting every `self.NAME` that appears on the LHS of
/// an `=`. Recurses through control-flow statements so an assignment inside
/// an `if` still counts.
fn collect_self_assignments(stmt: &Stmt, out: &mut Vec<String>) {
    match stmt {
        Stmt::Assign { target, .. } => {
            if let Expr::Member { obj, name } = &target.value
                && matches!(obj.value, Expr::Self_)
                && !out.iter().any(|n| n == name)
            {
                out.push(name.clone());
            }
        }
        Stmt::AssignMulti { targets, .. } => {
            for target in targets {
                if let Expr::Member { obj, name } = &target.value
                    && matches!(obj.value, Expr::Self_)
                    && !out.iter().any(|n| n == name)
                {
                    out.push(name.clone());
                }
            }
        }
        Stmt::If {
            then_block,
            elseifs,
            else_block,
            ..
        } => {
            for s in then_block {
                collect_self_assignments(&s.value, out);
            }
            for (_, block) in elseifs {
                for s in block {
                    collect_self_assignments(&s.value, out);
                }
            }
            if let Some(block) = else_block {
                for s in block {
                    collect_self_assignments(&s.value, out);
                }
            }
        }
        Stmt::While { body, .. }
        | Stmt::Repeat { body, .. }
        | Stmt::ForNumeric { body, .. }
        | Stmt::ForIn { body, .. } => {
            for s in body {
                collect_self_assignments(&s.value, out);
            }
        }
        Stmt::Try {
            body, catch_body, ..
        } => {
            for s in body {
                collect_self_assignments(&s.value, out);
            }
            for s in catch_body {
                collect_self_assignments(&s.value, out);
            }
        }
        _ => {}
    }
}

//! Static checks performed between parsing and evaluation.
//!
//! Two flavours of checks live here:
//!
//! 1. **Field initialization** — every non-nullable instance field of a class
//!    with a constructor must be assigned `self.field = ...` somewhere inside
//!    that constructor's body. Fields with defaults are exempt; nullable
//!    fields (`name: string?`) are exempt by design.
//!
//! 2. **Null safety** — values whose static type is nullable cannot be
//!    silently assigned to non-nullable bindings, and members cannot be read
//!    off a nullable receiver without `?.` / `!` / a prior nil-guard. A
//!    lightweight flow-narrowing pass treats `if x != nil then ... end` as
//!    proving `x` is non-nullable inside the then-block (and symmetrically
//!    for `if x == nil ... else ...`).
//!
//! The expression type inference here is intentionally partial: when the
//! checker can't prove a type (e.g. calls, member reads on unknown classes),
//! it returns `None` and conservatively skips the check rather than producing
//! a false positive.

use std::collections::HashMap;
use std::ops::Range;

use miette::Diagnostic;
use saule_ast::{
    BinOp, CallArg, ClassMember, Decl, Expr, LambdaBody, Method, Module, Param, Spanned, Stmt,
    Type,
};
use thiserror::Error;

/// One diagnostic produced by [`check`]. Carries a `miette` source span so
/// the CLI can render it with the offending snippet underlined.
#[derive(Debug, Error, Diagnostic)]
pub enum TypeCheckError {
    #[error("field `{field}` of class `{class}` is never initialized")]
    #[diagnostic(help(
        "assign `self.{field} = ...` in `init`, give the field a default value, or mark it nullable with `?`"
    ))]
    FieldNotInitialized {
        class: String,
        field: String,
        #[label("declared here")]
        span: miette::SourceSpan,
    },

    #[error("cannot assign `nil` to non-nullable type `{ty}`")]
    #[diagnostic(help(
        "mark the type nullable with `?` (e.g. `{ty}?`) or initialize it with a non-nil value"
    ))]
    NilToNonNullable {
        ty: String,
        #[label("`nil` not allowed here")]
        span: miette::SourceSpan,
    },

    #[error("cannot assign a nullable value of type `{from}` to non-nullable type `{to}`")]
    #[diagnostic(help(
        "guard with `if x != nil then ... end`, use `??` to provide a fallback, or force-unwrap with `!`"
    ))]
    NullableToNonNullable {
        from: String,
        to: String,
        #[label("this expression may be `nil`")]
        span: miette::SourceSpan,
    },

    #[error("cannot access `{member}` on nullable type `{ty}`")]
    #[diagnostic(help(
        "use `?.` for safe access, `!` to force-unwrap, or guard with `if x != nil then ... end`"
    ))]
    NullableMemberAccess {
        ty: String,
        member: String,
        #[label("receiver may be `nil`")]
        span: miette::SourceSpan,
    },

    #[error("default value for parameter `{param}` is incompatible with declared type `{ty}`")]
    #[diagnostic(help(
        "the default expression must produce a value of type `{ty}`"
    ))]
    DefaultParamTypeMismatch {
        param: String,
        ty: String,
        #[label("default here")]
        span: miette::SourceSpan,
    },

    #[error("return value is incompatible with declared return type `{ty}`")]
    #[diagnostic(help("this function must return a `{ty}`"))]
    WrongReturnType {
        ty: String,
        #[label("returned here")]
        span: miette::SourceSpan,
    },

    #[error("cannot access private member `{member}` of class `{class}` from outside the class")]
    #[diagnostic(help(
        "`local` fields and methods are only accessible from within `{class}`"
    ))]
    PrivateMemberAccess {
        class: String,
        member: String,
        #[label("private")]
        span: miette::SourceSpan,
    },

    #[error("table value of type `{found}` is incompatible with declared element type `{expected}`")]
    #[diagnostic(help(
        "every value stored in this table must be a `{expected}`"
    ))]
    TableElementTypeMismatch {
        expected: String,
        found: String,
        #[label("wrong value type")]
        span: miette::SourceSpan,
    },

    #[error("table key of type `{found}` is incompatible with declared key type `{expected}`")]
    #[diagnostic(help(
        "this table is declared with key type `{expected}` — pass an index of that type"
    ))]
    TableKeyTypeMismatch {
        expected: String,
        found: String,
        #[label("wrong key type")]
        span: miette::SourceSpan,
    },

    #[error("cannot initialise `table<{key}, {value}>` with an array-style literal")]
    #[diagnostic(help(
        "array-style `{{ ... }}` literals can only fill `table<T>` (integer-keyed); start from `{{}}` and assign by key instead"
    ))]
    TableArrayLiteralForMap {
        key: String,
        value: String,
        #[label("array literal not allowed for a map-typed table")]
        span: miette::SourceSpan,
    },

    #[error("cannot iterate over a `{class}` — it does not implement `Iterable` or `Iterable2`")]
    #[diagnostic(help(
        "add `implements Iterable<T>` (or `Iterable2<K, V>`) to `{class}` and define `fn iter() -> fn(): T?` returning a step closure"
    ))]
    NotIterable {
        class: String,
        #[label("class is not iterable")]
        span: miette::SourceSpan,
    },

    #[error("argument {arg} of `{callee}` expects `{expected}`, got `{found}`")]
    #[diagnostic(help(
        "pass a value of type `{expected}` here — check the signature of `{callee}`"
    ))]
    NativeArgTypeMismatch {
        callee: String,
        arg: usize,
        expected: String,
        found: String,
        #[label("wrong argument type")]
        span: miette::SourceSpan,
    },

    #[error("`{callee}` expects {expected} argument(s), got {found}")]
    #[diagnostic(help("check the signature of `{callee}`"))]
    NativeArity {
        callee: String,
        expected: usize,
        found: usize,
        #[label("wrong number of arguments")]
        span: miette::SourceSpan,
    },
}

fn to_source_span(r: Range<usize>) -> miette::SourceSpan {
    (r.start, r.end.saturating_sub(r.start)).into()
}

// ──────────────────────────────────────────────────────────────────────────────
// Scope: tracks the static types of `local` bindings in lexical scope.
// ──────────────────────────────────────────────────────────────────────────────

#[derive(Default, Clone)]
struct Scope {
    vars: HashMap<String, Type>,
}

impl Scope {
    fn lookup(&self, name: &str) -> Option<&Type> {
        self.vars.get(name)
    }

    fn bind(&mut self, name: String, ty: Type) {
        self.vars.insert(name, ty);
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Public entry point.
// ──────────────────────────────────────────────────────────────────────────────

/// Class info collected by a pre-pass so member-access checks can consult
/// member visibility, parent classes, etc.
#[derive(Default, Clone)]
struct ClassInfo {
    parent: Option<String>,
    /// Interfaces declared on the class (`class C implements A, B`).
    implements: Vec<String>,
    /// member name -> is_private
    members: HashMap<String, bool>,
}

type ClassRegistry = HashMap<String, ClassInfo>;

thread_local! {
    static CLASSES: std::cell::RefCell<ClassRegistry> = std::cell::RefCell::new(HashMap::new());
    static CURRENT_CLASS: std::cell::RefCell<Option<String>> = const { std::cell::RefCell::new(None) };
}

fn with_classes<R>(f: impl FnOnce(&ClassRegistry) -> R) -> R {
    CLASSES.with(|c| f(&c.borrow()))
}

fn current_class() -> Option<String> {
    CURRENT_CLASS.with(|c| c.borrow().clone())
}

fn set_current_class(name: Option<String>) -> Option<String> {
    CURRENT_CLASS.with(|c| std::mem::replace(&mut *c.borrow_mut(), name))
}

/// Look up `member` on `class` (walking the parent chain). Returns
/// `Some((owning_class, is_private))` if found.
fn lookup_member(class: &str, member: &str) -> Option<(String, bool)> {
    with_classes(|reg| {
        let mut cur = Some(class.to_string());
        while let Some(name) = cur {
            if let Some(info) = reg.get(&name) {
                if let Some(&priv_) = info.members.get(member) {
                    return Some((name, priv_));
                }
                cur = info.parent.clone();
            } else {
                return None;
            }
        }
        None
    })
}

/// Does the class (or any ancestor) declare it implements `Iterable` or
/// `Iterable2`? Used by the `for ... in` static check.
fn class_implements_iterable(class: &str) -> bool {
    with_classes(|reg| {
        let mut cur = Some(class.to_string());
        while let Some(name) = cur {
            let Some(info) = reg.get(&name) else {
                return false;
            };
            if info
                .implements
                .iter()
                .any(|i| i == "Iterable" || i == "Iterable2")
            {
                return true;
            }
            cur = info.parent.clone();
        }
        false
    })
}

fn build_registry(module: &Module) -> ClassRegistry {    let mut reg = ClassRegistry::new();
    for stmt in &module.stmts {
        if let Stmt::Decl(d) = &stmt.value
            && let Decl::Class {
                name,
                extends,
                implements,
                members,
                ..
            } = &d.value
        {
            let mut info = ClassInfo {
                parent: extends.clone(),
                implements: implements.clone(),
                members: HashMap::new(),
            };
            for m in members {
                match &m.value {
                    ClassMember::Field {
                        name, is_private, ..
                    } => {
                        info.members.insert(name.clone(), *is_private);
                    }
                    ClassMember::Method(meth) => {
                        info.members.insert(meth.name.clone(), meth.is_private);
                    }
                }
            }
            reg.insert(name.clone(), info);
        }
    }
    reg
}

/// Run the static checks on a parsed module. Returns *all* errors found so
/// the user sees everything in one pass.
pub fn check(module: &Module) -> Vec<TypeCheckError> {
    let reg = build_registry(module);
    CLASSES.with(|c| *c.borrow_mut() = reg);
    let _restore = set_current_class(None);
    let mut errors = Vec::new();
    let mut scope = Scope::default();
    for stmt in &module.stmts {
        check_stmt(&stmt.value, &mut scope, &mut errors);
    }
    CLASSES.with(|c| c.borrow_mut().clear());
    errors
}

// ──────────────────────────────────────────────────────────────────────────────
// Statement walker. Threads a `Scope` so we know the static type of every
// `local` we've seen on the current path, and so narrowing in `if`/`else` can
// override types for the duration of a sub-block.
// ──────────────────────────────────────────────────────────────────────────────

fn check_stmt(stmt: &Stmt, scope: &mut Scope, errors: &mut Vec<TypeCheckError>) {
    match stmt {
        Stmt::Decl(decl) => check_decl(&decl.value, errors),

        Stmt::Local { name, ty, value } => {
            if let (Some(ty), Some(v)) = (ty, value) {
                check_expr(v, scope, errors);
                check_assignment_compat(ty, v, scope, errors);
                scope.bind(name.clone(), ty.clone());
            } else if let Some(v) = value {
                check_expr(v, scope, errors);
                if let Some(t) = infer(v, scope) {
                    scope.bind(name.clone(), t);
                }
            } else if let Some(ty) = ty {
                scope.bind(name.clone(), ty.clone());
            }
        }

        Stmt::LocalMulti { names, values } => {
            for v in values {
                check_expr(v, scope, errors);
            }
            for (i, (name, ty_opt)) in names.iter().enumerate() {
                if let (Some(ty), Some(v)) = (ty_opt, values.get(i)) {
                    check_assignment_compat(ty, v, scope, errors);
                }
                if let Some(ty) = ty_opt {
                    scope.bind(name.clone(), ty.clone());
                } else if let Some(v) = values.get(i)
                    && let Some(t) = infer(v, scope)
                {
                    scope.bind(name.clone(), t);
                }
            }
        }

        Stmt::Assign { target, value } => {
            check_expr(target, scope, errors);
            check_expr(value, scope, errors);
            if let Expr::Ident(n) = &target.value
                && let Some(ty) = scope.lookup(n).cloned()
            {
                check_assignment_compat(&ty, value, scope, errors);
            }
            // `t[k] = v` — enforce the table's static key/value types.
            if let Expr::Index { obj, index } = &target.value
                && let Some(Type::Table { key, value: elem_ty }) = infer(obj, scope)
            {
                let key_ty = key
                    .as_deref()
                    .cloned()
                    .unwrap_or_else(|| Type::Named("integer".into()));
                check_table_key_compat(&key_ty, index, scope, errors);
                check_element_compat(&elem_ty, value, scope, errors);
            }
        }

        Stmt::AssignMulti { targets, values } => {
            for t in targets {
                check_expr(t, scope, errors);
            }
            for v in values {
                check_expr(v, scope, errors);
            }
            for (i, target) in targets.iter().enumerate() {
                if let Expr::Ident(n) = &target.value
                    && let (Some(ty), Some(v)) = (scope.lookup(n).cloned(), values.get(i))
                {
                    check_assignment_compat(&ty, v, scope, errors);
                }
            }
        }

        Stmt::Expr(e) => check_expr(e, scope, errors),

        Stmt::If {
            cond,
            then_block,
            elseifs,
            else_block,
        } => {
            check_expr(cond, scope, errors);

            // Branch the scope so narrowing in the then-block doesn't leak.
            let mut then_scope = scope.clone();
            narrow_truthy(cond, &mut then_scope);
            for s in then_block {
                check_stmt(&s.value, &mut then_scope, errors);
            }

            for (econd, ebody) in elseifs {
                check_expr(econd, scope, errors);
                let mut ei_scope = scope.clone();
                narrow_truthy(econd, &mut ei_scope);
                for s in ebody {
                    check_stmt(&s.value, &mut ei_scope, errors);
                }
            }

            if let Some(block) = else_block {
                let mut else_scope = scope.clone();
                narrow_falsy(cond, &mut else_scope);
                for s in block {
                    check_stmt(&s.value, &mut else_scope, errors);
                }
            }
        }

        Stmt::While { cond, body } | Stmt::Repeat { body, cond } => {
            check_expr(cond, scope, errors);
            let mut body_scope = scope.clone();
            narrow_truthy(cond, &mut body_scope);
            for s in body {
                check_stmt(&s.value, &mut body_scope, errors);
            }
        }

        Stmt::ForNumeric {
            var,
            var_ty,
            from,
            to,
            step,
            body,
        } => {
            check_expr(from, scope, errors);
            check_expr(to, scope, errors);
            if let Some(s) = step {
                check_expr(s, scope, errors);
            }
            let mut body_scope = scope.clone();
            let ty = var_ty.clone().unwrap_or(Type::Named("integer".into()));
            body_scope.bind(var.clone(), ty);
            for s in body {
                check_stmt(&s.value, &mut body_scope, errors);
            }
        }

        Stmt::ForIn { vars, iter, body } => {
            check_expr(iter, scope, errors);
            // If the iter expression is a known class instance, it must
            // implement `Iterable` or `Iterable2` (walking the parent chain).
            if let Some(Type::Named(class_name)) = infer(iter, scope)
                && with_classes(|reg| reg.contains_key(&class_name))
                && !class_implements_iterable(&class_name)
            {
                errors.push(TypeCheckError::NotIterable {
                    class: class_name,
                    span: to_source_span(iter.span.clone()),
                });
            }
            let mut body_scope = scope.clone();
            for (name, ty_opt) in vars {
                if let Some(ty) = ty_opt {
                    body_scope.bind(name.clone(), ty.clone());
                }
            }
            for s in body {
                check_stmt(&s.value, &mut body_scope, errors);
            }
        }

        Stmt::Return(values) => {
            for v in values {
                check_expr(v, scope, errors);
            }
        }

        Stmt::Throw(e) => check_expr(e, scope, errors),

        Stmt::Try {
            body,
            catch_var,
            catch_ty,
            catch_body,
        } => {
            let mut body_scope = scope.clone();
            for s in body {
                check_stmt(&s.value, &mut body_scope, errors);
            }
            let mut catch_scope = scope.clone();
            catch_scope.bind(catch_var.clone(), catch_ty.clone());
            for s in catch_body {
                check_stmt(&s.value, &mut catch_scope, errors);
            }
        }

        Stmt::Break | Stmt::Continue => {}
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Declaration walker.
// ──────────────────────────────────────────────────────────────────────────────

fn check_decl(decl: &Decl, errors: &mut Vec<TypeCheckError>) {
    match decl {
        Decl::Class {
            name: class_name,
            members,
            ..
        } => check_class(class_name, members, errors),
        Decl::Function {
            params,
            return_ty,
            body,
            ..
        } => {
            let mut scope = Scope::default();
            check_default_params(params, &scope, errors);
            seed_params(&mut scope, params);
            for s in body {
                check_stmt(&s.value, &mut scope, errors);
            }
            if let Some(rt) = return_ty {
                check_returns(body, rt, &scope, errors);
            }
        }
        _ => {}
    }
}

fn seed_params(scope: &mut Scope, params: &[Param]) {
    for p in params {
        scope.bind(p.name.clone(), p.ty.clone());
    }
}

/// Check each parameter default against the declared parameter type.
fn check_default_params(params: &[Param], scope: &Scope, errors: &mut Vec<TypeCheckError>) {
    for p in params {
        if let Some(d) = &p.default
            && !is_assignment_compatible(&p.ty, d, scope)
        {
            errors.push(TypeCheckError::DefaultParamTypeMismatch {
                param: p.name.clone(),
                ty: type_to_string(&p.ty),
                span: to_source_span(d.span.clone()),
            });
        }
    }
}

/// Walk a function/method body looking for `return v` statements whose first
/// value can be proved incompatible with `return_ty`.
fn check_returns(
    body: &[Spanned<Stmt>],
    return_ty: &Type,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    for s in body {
        walk_returns(&s.value, return_ty, scope, errors);
    }
}

fn walk_returns(
    stmt: &Stmt,
    return_ty: &Type,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    match stmt {
        Stmt::Return(values) => {
            if let Some(v) = values.first()
                && !is_assignment_compatible(return_ty, v, scope)
            {
                errors.push(TypeCheckError::WrongReturnType {
                    ty: type_to_string(return_ty),
                    span: to_source_span(v.span.clone()),
                });
            }
        }
        Stmt::If {
            then_block,
            elseifs,
            else_block,
            ..
        } => {
            for s in then_block {
                walk_returns(&s.value, return_ty, scope, errors);
            }
            for (_, b) in elseifs {
                for s in b {
                    walk_returns(&s.value, return_ty, scope, errors);
                }
            }
            if let Some(b) = else_block {
                for s in b {
                    walk_returns(&s.value, return_ty, scope, errors);
                }
            }
        }
        Stmt::While { body, .. }
        | Stmt::Repeat { body, .. }
        | Stmt::ForNumeric { body, .. }
        | Stmt::ForIn { body, .. } => {
            for s in body {
                walk_returns(&s.value, return_ty, scope, errors);
            }
        }
        Stmt::Try {
            body, catch_body, ..
        } => {
            for s in body {
                walk_returns(&s.value, return_ty, scope, errors);
            }
            for s in catch_body {
                walk_returns(&s.value, return_ty, scope, errors);
            }
        }
        _ => {}
    }
}

/// True when we can *prove* the value is incompatible-free with the target
/// type. Returns true when we can't decide (conservative: don't false-positive).
fn is_assignment_compatible(decl_ty: &Type, value: &Spanned<Expr>, scope: &Scope) -> bool {
    if is_nullable(decl_ty) {
        // Nullable target accepts anything we can express.
        return true;
    }
    if matches!(value.value, Expr::Nil) {
        return false;
    }
    let Some(value_ty) = infer(value, scope) else {
        return true;
    };
    if is_nullable(&value_ty) {
        return false;
    }
    match (decl_ty, &value_ty) {
        (Type::Named(a), Type::Named(b)) => {
            if a == b || a == "any" || b == "any" {
                true
            } else {
                // Allow numeric literals in either direction only when same name.
                false
            }
        }
        _ => true,
    }
}

fn check_class(
    class_name: &str,
    members: &[Spanned<ClassMember>],
    errors: &mut Vec<TypeCheckError>,
) {
    // Locate the constructor body: the non-static `fn init` method.
    let mut ctor_body: Option<&Vec<Spanned<Stmt>>> = None;
    for m in members {
        match &m.value {
            ClassMember::Method(Method {
                name,
                is_static: false,
                body,
                ..
            }) if name == "init" => {
                ctor_body = Some(body);
            }
            _ => {}
        }
    }

    // Validate field defaults: `local x: string = nil` is an error regardless
    // of whether a constructor exists or the field is static.
    for m in members {
        if let ClassMember::Field {
            ty,
            default: Some(default_expr),
            ..
        } = &m.value
        {
            let scope = Scope::default();
            check_assignment_compat(ty, default_expr, &scope, errors);
        }
    }

    if let Some(body) = ctor_body {
        let mut assigned: Vec<String> = Vec::new();
        for s in body {
            collect_self_assignments(&s.value, &mut assigned);
        }
        for m in members {
            if let ClassMember::Field {
                is_static: false,
                name,
                ty,
                default,
                ..
            } = &m.value
            {
                if default.is_some() || is_nullable(ty) {
                    continue;
                }
                if !assigned.iter().any(|a| a == name) {
                    errors.push(TypeCheckError::FieldNotInitialized {
                        class: class_name.to_string(),
                        field: name.clone(),
                        span: to_source_span(m.span.clone()),
                    });
                }
            }
        }
    }

    // Walk every method body with a scope seeded from its parameters,
    // and within `CURRENT_CLASS` set so private-member checks know we're
    // *inside* `class_name`. Also validate default parameters and return types.
    let prev = set_current_class(Some(class_name.to_string()));
    for m in members {
        if let ClassMember::Method(meth) = &m.value {
            let mut scope = Scope::default();
            // `self` resolves to the class itself in `static fn` and to an
            // instance otherwise. Seed it as the class name so member-existence
            // checks on `self.foo` consult the class registry.
            scope.bind("self".to_string(), Type::Named(class_name.to_string()));
            check_default_params(&meth.params, &scope, errors);
            seed_params(&mut scope, &meth.params);
            for s in &meth.body {
                check_stmt(&s.value, &mut scope, errors);
            }
            if let Some(rt) = &meth.return_ty {
                check_returns(&meth.body, rt, &scope, errors);
            }
        }
    }
    set_current_class(prev);
}

// ──────────────────────────────────────────────────────────────────────────────
// Expression checker — walks expressions looking for `obj.member` /
// `obj.method(...)` where `obj` has a statically-known nullable type.
// ──────────────────────────────────────────────────────────────────────────────

fn check_expr(expr: &Spanned<Expr>, scope: &Scope, errors: &mut Vec<TypeCheckError>) {
    match &expr.value {
        Expr::Member { obj, name } => {
            check_expr(obj, scope, errors);
            report_if_nullable_receiver(obj, name, scope, errors);
            report_if_private(obj, name, scope, errors);
        }
        Expr::MethodCall { obj, method, args } => {
            check_expr(obj, scope, errors);
            report_if_nullable_receiver(obj, method, scope, errors);
            report_if_private(obj, method, scope, errors);
            for a in args {
                check_arg(a, scope, errors);
            }
        }
        Expr::Call { callee, args } => {
            // `obj.method(args)` is parsed as Call(Member { obj, name }, args)
            // — same nullable-receiver rule applies.
            if let Expr::Member { obj, name } = &callee.value {
                check_expr(obj, scope, errors);
                report_if_nullable_receiver(obj, name, scope, errors);
                report_if_private(obj, name, scope, errors);
            } else {
                check_expr(callee, scope, errors);
            }
            for a in args {
                check_arg(a, scope, errors);
            }
            // If the callee resolves to a known native signature, check the
            // argument types positionally. Named arguments are skipped (those
            // aren't supported on natives anyway, and they error at runtime).
            if let Some(qname) = native_callee_name(callee)
                && let Some(sig) = crate::stdlib::sigs::lookup(&qname)
            {
                check_native_args(&qname, &sig, args, scope, errors, expr.span.clone());
            }
        }
        Expr::SafeMember { obj, .. } => check_expr(obj, scope, errors),
        Expr::Index { obj, index } => {
            check_expr(obj, scope, errors);
            check_expr(index, scope, errors);
        }
        Expr::Unary { rhs, .. } => check_expr(rhs, scope, errors),
        Expr::Binary { lhs, rhs, .. } => {
            check_expr(lhs, scope, errors);
            check_expr(rhs, scope, errors);
        }
        Expr::ForceUnwrap(inner) => check_expr(inner, scope, errors),
        Expr::Table(items) => {
            for e in items {
                check_expr(e, scope, errors);
            }
        }
        Expr::Lambda { params, body, .. } => {
            let mut lscope = scope.clone();
            seed_params(&mut lscope, params);
            match body {
                LambdaBody::Expr(e) => check_expr(e, &lscope, errors),
                LambdaBody::Block(stmts) => {
                    for s in stmts {
                        check_stmt(&s.value, &mut lscope, errors);
                    }
                }
            }
        }
        _ => {}
    }
}

fn check_arg(arg: &CallArg, scope: &Scope, errors: &mut Vec<TypeCheckError>) {
    match arg {
        CallArg::Positional(e) | CallArg::Named { value: e, .. } => check_expr(e, scope, errors),
    }
}

/// Check positional arguments of a native call against the registered
/// signature. Skips named arguments (natives don't support them; the runtime
/// will surface that as an error).
///
/// Heuristics intentionally lenient:
///   * `any` and `T?` parameters accept anything (incl. nil) — they're the
///     "I'll figure it out" slots.
///   * Variadic / over-supplied calls aren't penalised when the declared
///     param list runs out — many natives accept `...rest` (variadic) which
///     isn't expressed in the sig yet.
///   * If `infer` can't produce a type for the argument, we skip silently.
fn check_native_args(
    callee: &str,
    sig: &crate::stdlib::sigs::NativeSig,
    args: &[CallArg],
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
    call_span: std::ops::Range<usize>,
) {
    // Count required positional params (every param up to the first
    // nullable / `any` is required — nullable+`any` slots are optional).
    let required: usize = sig
        .params
        .iter()
        .take_while(|p| !is_nullable(p) && !is_any(p))
        .count();
    let positional: Vec<&CallArg> = args.iter().filter(|a| matches!(a, CallArg::Positional(_))).collect();
    if positional.len() < required {
        errors.push(TypeCheckError::NativeArity {
            callee: callee.to_string(),
            expected: required,
            found: positional.len(),
            span: to_source_span(call_span.clone()),
        });
        return;
    }

    // Reject extras when the native is not variadic. Don't bail though —
    // continue checking the known positions for type mismatches.
    if sig.variadic.is_none() && positional.len() > sig.params.len() {
        errors.push(TypeCheckError::NativeArity {
            callee: callee.to_string(),
            expected: sig.params.len(),
            found: positional.len(),
            span: to_source_span(call_span),
        });
    }

    for (i, arg) in args.iter().enumerate() {
        // Pick the expected type for slot `i`:
        //   - within declared params: use `params[i]`
        //   - past the end: use the variadic element type (or stop if absent)
        let expected = match sig.params.get(i) {
            Some(t) => t,
            None => match &sig.variadic {
                Some(t) => t,
                None => break,
            },
        };
        let value_expr = match arg {
            CallArg::Positional(e) => e,
            CallArg::Named { .. } => continue,
        };
        if is_any(expected) {
            continue;
        }
        let Some(found_ty) = infer(value_expr, scope) else {
            continue;
        };
        if !types_compatible(expected, &found_ty) {
            errors.push(TypeCheckError::NativeArgTypeMismatch {
                callee: callee.to_string(),
                arg: i + 1,
                expected: type_to_string(expected),
                found: type_to_string(&found_ty),
                span: to_source_span(value_expr.span.clone()),
            });
        }
    }
}

fn is_any(t: &Type) -> bool {
    matches!(t, Type::Named(n) if n == "any")
}

fn report_if_nullable_receiver(
    obj: &Spanned<Expr>,
    member: &str,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    if let Some(ty) = infer(obj, scope)
        && is_nullable(&ty)
    {
        errors.push(TypeCheckError::NullableMemberAccess {
            ty: type_to_string(&ty),
            member: member.to_string(),
            span: to_source_span(obj.span.clone()),
        });
    }
}

/// Reject access to `local` (private) members from outside the owning class.
/// `self.foo` is always permitted; access via any other expression is checked.
fn report_if_private(
    obj: &Spanned<Expr>,
    member: &str,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    // Accesses through `self` are always allowed (inside their own class).
    if matches!(obj.value, Expr::Self_) {
        return;
    }
    // Resolve the class name we're reading the member off:
    //   * `obj.member` where `obj` is an *instance* → infer the receiver type.
    //   * `Class.member` where the receiver is the class itself
    //     (e.g. `Bank.secret`) → use the ident directly.
    let class_name = match &obj.value {
        Expr::Ident(n) if with_classes(|reg| reg.contains_key(n)) => n.clone(),
        _ => match infer(obj, scope) {
            Some(ty) => match strip_nullable(ty) {
                Type::Named(n) => n,
                _ => return,
            },
            None => return,
        },
    };
    let Some((owning, is_private)) = lookup_member(&class_name, member) else {
        return;
    };
    if is_private && current_class().as_deref() != Some(owning.as_str()) {
        errors.push(TypeCheckError::PrivateMemberAccess {
            class: owning,
            member: member.to_string(),
            span: to_source_span(obj.span.end..obj.span.end + member.len() + 1),
        });
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Assignment compatibility — only flags the cases we can prove are wrong.
// ──────────────────────────────────────────────────────────────────────────────

fn check_assignment_compat(
    decl_ty: &Type,
    value: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    if is_nullable(decl_ty) {
        return;
    }
    if matches!(value.value, Expr::Nil) {
        errors.push(TypeCheckError::NilToNonNullable {
            ty: type_to_string(decl_ty),
            span: to_source_span(value.span.clone()),
        });
        return;
    }

    // Table-aware checks for array-style literals assigned to a typed table.
    if let (Type::Table { key, value: elem_ty }, Expr::Table(items)) = (decl_ty, &value.value) {
        // `{a, b, c}` literal cannot fill a map-typed table whose key is not
        // integer-compatible.
        if let Some(k) = key
            && !is_integer_like(k)
            && !items.is_empty()
        {
            errors.push(TypeCheckError::TableArrayLiteralForMap {
                key: type_to_string(k),
                value: type_to_string(elem_ty),
                span: to_source_span(value.span.clone()),
            });
            return;
        }
        // Each element must match the declared value type.
        for item in items {
            check_element_compat(elem_ty, item, scope, errors);
        }
        return;
    }

    if let Some(value_ty) = infer(value, scope)
        && is_nullable(&value_ty)
    {
        errors.push(TypeCheckError::NullableToNonNullable {
            from: type_to_string(&value_ty),
            to: type_to_string(decl_ty),
            span: to_source_span(value.span.clone()),
        });
    }
}

/// Index key must match the table's declared key type.
fn check_table_key_compat(
    expected: &Type,
    index: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    if let Some(idx_ty) = infer(index, scope)
        && !types_compatible(expected, &idx_ty)
    {
        errors.push(TypeCheckError::TableKeyTypeMismatch {
            expected: type_to_string(expected),
            found: type_to_string(&idx_ty),
            span: to_source_span(index.span.clone()),
        });
    }
}

/// True for `integer` and `any` — the key types that an array-style literal
/// can satisfy.
fn is_integer_like(ty: &Type) -> bool {
    matches!(ty, Type::Named(n) if n == "integer" || n == "any")
}

/// Element-of-table compatibility — accepts literals/`Ident`s whose inferred
/// type matches, and stays quiet otherwise (conservative).
fn check_element_compat(
    expected: &Type,
    value: &Spanned<Expr>,
    scope: &Scope,
    errors: &mut Vec<TypeCheckError>,
) {
    if let Some(value_ty) = infer(value, scope)
        && !types_compatible(expected, &value_ty)
    {
        errors.push(TypeCheckError::TableElementTypeMismatch {
            expected: type_to_string(expected),
            found: type_to_string(&value_ty),
            span: to_source_span(value.span.clone()),
        });
    }
}

/// Conservative type compatibility — names match (or either is `any`), or
/// `value_ty` is `Nullable` of a compatible inner, etc.
fn types_compatible(expected: &Type, value_ty: &Type) -> bool {
    match (expected, value_ty) {
        // Same-name primitives, plus `any` on either side, plus `nil` on the
        // value side (nil is universally assignable; nullable-rejection is
        // handled separately by `NullableToNonNullable`).
        (Type::Named(a), Type::Named(b)) => {
            if a == b || a == "any" || b == "any" || b == "nil" {
                return true;
            }
            // `number` is the sentinel used in native sigs to mean
            // "integer or float" — accept either.
            if a == "number" && (b == "integer" || b == "float" || b == "number") {
                return true;
            }
            false
        }
        // `table<any>` (or `table<any, any>`) matches any table — used by
        // native sigs like `pairs(t)` / `Table.insert(t, ...)` to mean
        // "any table".
        (
            Type::Table { key: ek, value: ev },
            Type::Table { key: vk, value: vv },
        ) => {
            let key_ok = match (ek, vk) {
                (None, None) => true,
                (Some(a), Some(b)) => types_compatible(a, b),
                // Cross-shape (`table<T>` vs `table<K, V>`) only when one
                // side is the `any` wildcard.
                _ => is_any(ev),
            };
            key_ok && (is_any(ev) || types_compatible(ev, vv))
        }
        // Expected table, but value is the bare type-name `table`, `any` or
        // `nil` — accept (caller has erased the element type, or it's nil).
        (Type::Table { .. }, Type::Named(n)) if n == "table" || n == "any" || n == "nil" => true,
        // Expected `any` / `table` / `nil` named slot, value is a table —
        // accept (we widen to the named slot).
        (Type::Named(n), Type::Table { .. }) if n == "table" || n == "any" => true,
        (Type::Nullable(a), b) => types_compatible(a, b),
        (a, Type::Nullable(b)) => types_compatible(a, b),
        // Function / Tuple shapes — only equal-shape is strictly compatible,
        // but the checker doesn't track those precisely yet. Accept rather
        // than emit false positives.
        (Type::Function { .. }, Type::Function { .. }) => true,
        (Type::Tuple(_), Type::Tuple(_)) => true,
        // Different kinds (e.g. table vs integer) — reject.
        _ => false,
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Lightweight type inference.
//
// Returns `Some(ty)` only when we can prove the type. Anything we can't see
// through (calls, member reads on unknown classes, indexing) returns `None`,
// and callers treat that as "don't know, don't complain".
// ──────────────────────────────────────────────────────────────────────────────

fn infer(expr: &Spanned<Expr>, scope: &Scope) -> Option<Type> {
    match &expr.value {
        Expr::Nil => Some(Type::Named("nil".into())),
        Expr::Int(_) => Some(Type::Named("integer".into())),
        Expr::Float(_) => Some(Type::Named("float".into())),
        Expr::Bool(_) => Some(Type::Named("boolean".into())),
        Expr::Str(_) => Some(Type::Named("string".into())),
        Expr::Ident(n) => scope.lookup(n).cloned(),
        Expr::SafeMember { .. } => Some(Type::Nullable(Box::new(Type::Named("any".into())))),
        Expr::ForceUnwrap(inner) => match infer(inner, scope)? {
            Type::Nullable(t) => Some(*t),
            other => Some(other),
        },
        Expr::Binary { op, lhs, rhs } => match op {
            BinOp::Coalesce => {
                // `lhs ?? rhs`: result is non-nullable iff `rhs` is non-nullable.
                match (infer(lhs, scope), infer(rhs, scope)) {
                    (Some(lt), Some(rt)) => {
                        let base = strip_nullable(lt);
                        if is_nullable(&rt) {
                            Some(Type::Nullable(Box::new(base)))
                        } else {
                            Some(base)
                        }
                    }
                    _ => None,
                }
            }
            BinOp::Eq | BinOp::NotEq | BinOp::Lt | BinOp::LtEq | BinOp::Gt | BinOp::GtEq => {
                Some(Type::Named("boolean".into()))
            }
            BinOp::And | BinOp::Or => None,
            BinOp::Concat => Some(Type::Named("string".into())),
            BinOp::Add | BinOp::Sub | BinOp::Mul | BinOp::Div | BinOp::Mod => {
                infer(lhs, scope).or_else(|| infer(rhs, scope))
            }
        },
        // `Foo(args)` where `Foo` is a known class → produces a `Foo`.
        // Otherwise, look up the qualified callee name in the native signature
        // table (e.g. `String.byte`, `Math.tointeger`, `assert`).
        Expr::Call { callee, .. } => {
            if let Expr::Ident(n) = &callee.value
                && with_classes(|reg| reg.contains_key(n))
            {
                Some(Type::Named(n.clone()))
            } else if let Some(qname) = native_callee_name(callee)
                && let Some(sig) = crate::stdlib::sigs::lookup(&qname)
            {
                first_or_tuple(sig.returns)
            } else {
                None
            }
        }
        _ => None,
    }
}

fn strip_nullable(ty: Type) -> Type {
    match ty {
        Type::Nullable(t) => *t,
        other => other,
    }
}

/// Build a qualified callee name suitable for `stdlib::sigs::lookup`:
/// `assert` or `String.byte`.
fn native_callee_name(callee: &Spanned<Expr>) -> Option<String> {
    match &callee.value {
        Expr::Ident(n) => Some(n.clone()),
        Expr::Member { obj, name } => {
            if let Expr::Ident(class) = &obj.value {
                Some(format!("{class}.{name}"))
            } else {
                None
            }
        }
        _ => None,
    }
}

/// Collapse a returns-list into a single inferred type: single returns stay
/// as-is, multi-returns become a `Type::Tuple`.
fn first_or_tuple(returns: Vec<Type>) -> Option<Type> {
    match returns.len() {
        0 => None,
        1 => returns.into_iter().next(),
        _ => Some(Type::Tuple(returns)),
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Flow narrowing.
//
// `narrow_truthy(cond, scope)` — apply the assumptions that hold when `cond`
// is true. Today: `x != nil` and `nil != x` strip `Nullable` off `x`. `and`
// chains compose.
//
// `narrow_falsy(cond, scope)` — apply the assumptions when `cond` is false.
// Used by the else-branch: `if x == nil then ... else ... end` narrows `x`
// in the else.
// ──────────────────────────────────────────────────────────────────────────────

fn narrow_truthy(cond: &Spanned<Expr>, scope: &mut Scope) {
    match &cond.value {
        Expr::Binary {
            op: BinOp::NotEq,
            lhs,
            rhs,
        } => {
            if let Some(name) = pick_ident_compared_to_nil(lhs, rhs)
                && let Some(Type::Nullable(t)) = scope.lookup(name).cloned()
            {
                scope.bind(name.to_string(), *t);
            }
        }
        Expr::Binary {
            op: BinOp::And,
            lhs,
            rhs,
        } => {
            narrow_truthy(lhs, scope);
            narrow_truthy(rhs, scope);
        }
        _ => {}
    }
}

fn narrow_falsy(cond: &Spanned<Expr>, scope: &mut Scope) {
    if let Expr::Binary {
        op: BinOp::Eq,
        lhs,
        rhs,
    } = &cond.value
        && let Some(name) = pick_ident_compared_to_nil(lhs, rhs)
        && let Some(Type::Nullable(t)) = scope.lookup(name).cloned()
    {
        scope.bind(name.to_string(), *t);
    }
}

/// If `lhs` / `rhs` is `(Ident(x), Nil)` in either order, return `Some(x)`.
fn pick_ident_compared_to_nil<'a>(
    lhs: &'a Spanned<Expr>,
    rhs: &'a Spanned<Expr>,
) -> Option<&'a str> {
    match (&lhs.value, &rhs.value) {
        (Expr::Ident(n), Expr::Nil) => Some(n),
        (Expr::Nil, Expr::Ident(n)) => Some(n),
        _ => None,
    }
}

// ──────────────────────────────────────────────────────────────────────────────
// Misc helpers.
// ──────────────────────────────────────────────────────────────────────────────

fn type_to_string(ty: &Type) -> String {
    match ty {
        Type::Named(n) => n.clone(),
        Type::Nullable(inner) => format!("{}?", type_to_string(inner)),
        Type::Table { key: None, value } => format!("table<{}>", type_to_string(value)),
        Type::Table {
            key: Some(k),
            value,
        } => format!("table<{}, {}>", type_to_string(k), type_to_string(value)),
        other => format!("{:?}", other),
    }
}

fn is_nullable(ty: &Type) -> bool {
    match ty {
        Type::Nullable(_) => true,
        Type::Named(n) => n == "nil",
        _ => false,
    }
}

/// Walk a statement collecting every `self.NAME` that appears on the LHS of
/// an `=`. Recurses through control-flow statements so an assignment inside
/// an `if` still counts.
fn collect_self_assignments(stmt: &Stmt, out: &mut Vec<String>) {
    match stmt {
        Stmt::Assign { target, .. } => {
            if let Expr::Member { obj, name } = &target.value
                && matches!(obj.value, Expr::Self_)
                && !out.iter().any(|n| n == name)
            {
                out.push(name.clone());
            }
        }
        Stmt::AssignMulti { targets, .. } => {
            for target in targets {
                if let Expr::Member { obj, name } = &target.value
                    && matches!(obj.value, Expr::Self_)
                    && !out.iter().any(|n| n == name)
                {
                    out.push(name.clone());
                }
            }
        }
        Stmt::If {
            then_block,
            elseifs,
            else_block,
            ..
        } => {
            for s in then_block {
                collect_self_assignments(&s.value, out);
            }
            for (_, block) in elseifs {
                for s in block {
                    collect_self_assignments(&s.value, out);
                }
            }
            if let Some(block) = else_block {
                for s in block {
                    collect_self_assignments(&s.value, out);
                }
            }
        }
        Stmt::While { body, .. }
        | Stmt::Repeat { body, .. }
        | Stmt::ForNumeric { body, .. }
        | Stmt::ForIn { body, .. } => {
            for s in body {
                collect_self_assignments(&s.value, out);
            }
        }
        Stmt::Try {
            body, catch_body, ..
        } => {
            for s in body {
                collect_self_assignments(&s.value, out);
            }
            for s in catch_body {
                collect_self_assignments(&s.value, out);
            }
        }
        _ => {}
    }
}

//! Runtime values for the Saule interpreter.
//!
//! When adding a new variant, remember to extend [`Value::type_name`],
//! [`Value::is_truthy`], [`Value::to_display_string`], and the `PartialEq`
//! impl below.

use std::cell::RefCell;
use std::collections::HashMap;
use std::fmt;
use std::rc::Rc;

use saule_ast::{Expr, Param, Spanned, Stmt};

use crate::env::Environment;

/// A Saule runtime value.
#[derive(Debug, Clone)]
pub enum Value {
    Nil,
    Bool(bool),
    Int(i64),
    Float(f64),
    /// Interned via `Rc` so cloning a value is cheap.
    Str(Rc<String>),
    /// Hybrid table storage: a dense array part plus a hashmap part. `table<T>`
    /// uses only the array; `table<K, V>` uses the map (and may also use the
    /// array when keys happen to be positive integers). Shared by reference so
    /// aliasing behaves like Lua tables.
    Table(Rc<RefCell<TableObject>>),
    /// Built-in function written in Rust (e.g. `print`).
    Native(Rc<NativeFn>),
    /// Built-in function with captured Rust state (e.g. iterators). Same call
    /// shape as `Native` but stateful and may return multiple values.
    NativeClosure(Rc<NativeClosure>),
    /// User-defined function or lambda. The `Rc` makes cloning cheap and
    /// gives recursive closures something stable to point at.
    Function(Rc<FunctionObject>),
    /// A class declaration — carries its statics, instance template, and
    /// optional parent. Compared by identity.
    Class(Rc<ClassObject>),
    /// An instance produced by `new ClassName(args)`. Fields are mutable
    /// behind a `RefCell`; identity is the `Rc` pointer.
    Instance(Rc<RefCell<InstanceObject>>),
    /// An enum variant: carries the enum name, variant name, and optional
    /// value. Compared by identity so each access to `Status.Alive` returns
    /// the same `Rc` pointer.
    EnumVariant(Rc<EnumVariantObject>),
    /// An enum declaration — carries its variants and methods.
    Enum(Rc<EnumObject>),
    /// An interface declaration — carries method signatures.
    Interface(Rc<InterfaceObject>),
    /// An open (or closed) file handle returned by `Io.open` and the
    /// `Io.stdin`/`stdout`/`stderr` statics. Methods are dispatched via a
    /// static table inside `stdlib::io`.
    File(Rc<RefCell<FileHandle>>),
}

/// Backing storage for a `Value::File`. Variants split read- and write-side
/// state so we can buffer line reads via `BufReader` while leaving writes
/// unbuffered (the caller can call `:flush` explicitly when needed).
pub enum FileHandle {
    Stdin(std::io::BufReader<std::io::Stdin>),
    Stdout,
    Stderr,
    Open {
        path: String,
        reader: Option<std::io::BufReader<std::fs::File>>,
        writer: Option<std::fs::File>,
    },
    Closed,
}

impl fmt::Debug for FileHandle {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            FileHandle::Stdin(_) => write!(f, "<file stdin>"),
            FileHandle::Stdout => write!(f, "<file stdout>"),
            FileHandle::Stderr => write!(f, "<file stderr>"),
            FileHandle::Open { path, .. } => write!(f, "<file {path}>"),
            FileHandle::Closed => write!(f, "<closed file>"),
        }
    }
}

#[derive(Debug)]
pub struct EnumVariantObject {
    pub enum_name: String,
    pub variant_name: String,
    pub value: Option<Value>,
    /// Reference to the enum so we can access methods. Stored in RefCell to
    /// allow updating after enum creation (breaking the circular reference issue).
    pub enum_obj: std::cell::RefCell<Option<Rc<EnumObject>>>,
}

#[derive(Debug)]
pub struct EnumObject {
    pub name: String,
    /// Enum variants, keyed by name. Each variant is cached so identity is stable.
    pub variants: HashMap<String, Rc<EnumVariantObject>>,
    /// Methods defined on the enum, keyed by name.
    pub methods: HashMap<String, Rc<FunctionObject>>,
}

/// Rust-implemented function exposed to Saule.
///
/// The function returns `Result<Value, String>` where the error string is
/// surfaced as a `RuntimeError::TypeError` at the call site.
pub struct NativeFn {
    pub name: &'static str,
    pub func: fn(&[Value]) -> Result<Value, String>,
}

impl fmt::Debug for NativeFn {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "<native fn {}>", self.name)
    }
}

/// Stateful Rust-implemented function. The closure may capture arbitrary
/// Rust state (e.g. an iterator's cursor) and may return multiple values.
pub struct NativeClosure {
    pub name: &'static str,
    pub func: Box<dyn Fn(&[Value]) -> Result<Vec<Value>, String>>,
}

impl fmt::Debug for NativeClosure {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "<native closure {}>", self.name)
    }
}

/// A user-defined function carrying its body and lexical closure.
#[derive(Debug)]
pub struct FunctionObject {
    /// `Some(name)` for named declarations, `None` for lambdas.
    pub name: Option<String>,
    pub params: Vec<Param>,
    pub body: FunctionBody,
    /// The environment that was in scope when the function was created.
    /// Captured by reference so inner functions see live bindings.
    pub closure: Rc<RefCell<Environment>>,
}

/// Function bodies come in two shapes:
///   * a block of statements (named `fn` decls, block-body lambdas),
///   * a single expression (arrow-style lambdas like `(x) => x + 1`).
#[derive(Debug, Clone)]
pub enum FunctionBody {
    Block(Vec<Spanned<Stmt>>),
    Expr(Box<Spanned<saule_ast::Expr>>),
}

/// Runtime representation of a `class` declaration.
///
/// Instance fields live on the [`InstanceObject`]; statics live here (behind
/// a `RefCell` because they can be reassigned). Methods are stored as
/// already-constructed [`FunctionObject`]s capturing the module-level
/// environment so they can refer to other top-level names (including the
/// class itself for static calls).
#[derive(Debug)]
pub struct ClassObject {
    pub name: String,
    pub parent: Option<Rc<ClassObject>>,
    /// Instance-field templates evaluated on construction.
    pub field_defs: Vec<FieldDef>,
    /// Instance methods, keyed by name. First parameter is the user-written
    /// `self`, so calling `obj:method(a)` is the same as `method(obj, a)`.
    pub methods: HashMap<String, Rc<FunctionObject>>,
    /// Static fields. Mutable through `ClassName.field = …`.
    pub static_fields: RefCell<HashMap<String, Value>>,
    /// Static methods (no implicit `self`).
    pub static_methods: HashMap<String, Rc<FunctionObject>>,
    /// `constructor(args) … end`. None means the class has no explicit
    /// constructor — `new` still produces a valid instance.
    pub constructor: Option<Rc<FunctionObject>>,
}

#[derive(Debug, Clone)]
pub struct FieldDef {
    pub name: String,
    /// Evaluated in the constructor scope each time an instance is built.
    pub default: Option<Spanned<Expr>>,
}

#[derive(Debug)]
pub struct InstanceObject {
    pub class: Rc<ClassObject>,
    pub fields: HashMap<String, Value>,
}

impl ClassObject {
    /// Walk the inheritance chain for a method.
    pub fn lookup_method(self: &Rc<Self>, name: &str) -> Option<Rc<FunctionObject>> {
        if let Some(m) = self.methods.get(name) {
            return Some(m.clone());
        }
        self.parent.as_ref().and_then(|p| p.lookup_method(name))
    }

    /// Walk the inheritance chain for a static method.
    pub fn lookup_static_method(self: &Rc<Self>, name: &str) -> Option<Rc<FunctionObject>> {
        if let Some(m) = self.static_methods.get(name) {
            return Some(m.clone());
        }
        self.parent
            .as_ref()
            .and_then(|p| p.lookup_static_method(name))
    }

    /// Walk the inheritance chain for a static field.
    pub fn lookup_static_field(self: &Rc<Self>, name: &str) -> Option<Value> {
        if let Some(v) = self.static_fields.borrow().get(name) {
            return Some(v.clone());
        }
        self.parent
            .as_ref()
            .and_then(|p| p.lookup_static_field(name))
    }
}

impl Value {
    /// Human-readable type name for error messages — matches the names used
    /// in the README's type system.
    pub fn type_name(&self) -> &'static str {
        match self {
            Value::Nil => "nil",
            Value::Bool(_) => "boolean",
            Value::Int(_) => "integer",
            Value::Float(_) => "float",
            Value::Str(_) => "string",
            Value::Table(_) => "table",
            Value::Native(_) | Value::NativeClosure(_) | Value::Function(_) => "function",
            Value::Class(_) => "class",
            Value::Instance(_) => "instance",
            Value::EnumVariant(_) => "enum",
            Value::Enum(_) => "enum",
            Value::Interface(_) => "interface",
            Value::File(_) => "file",
        }
    }

    /// Lua-style truthiness: only `nil` and `false` are falsy.
    pub fn is_truthy(&self) -> bool {
        !matches!(self, Value::Nil | Value::Bool(false))
    }

    /// Format used by `print` and the `..` operator.
    pub fn to_display_string(&self) -> String {
        match self {
            Value::Nil => "nil".into(),
            Value::Bool(b) => b.to_string(),
            Value::Int(n) => n.to_string(),
            Value::Float(f) => {
                // Always show a decimal point so floats are visually distinct
                // from ints, matching the README's display style.
                if f.fract() == 0.0 && f.is_finite() {
                    format!("{f:.1}")
                } else {
                    f.to_string()
                }
            }
            Value::Str(s) => (**s).clone(),
            Value::Table(items) => {
                let t = items.borrow();
                let array_parts = t.array.iter().map(Value::to_display_string);
                let map_parts = t
                    .map
                    .iter()
                    .map(|(k, v)| format!("{}={}", k.display(), v.to_display_string()));
                let parts: Vec<String> = array_parts.chain(map_parts).collect();
                format!("{{{}}}", parts.join(", "))
            }
            Value::EnumVariant(ev) => {
                format!("{}.{}", ev.enum_name, ev.variant_name)
            }
            Value::Enum(e) => format!("<enum {}>", e.name),
            Value::Interface(iface) => format!("<interface {}>", iface.name),
            Value::Native(nf) => format!("<native fn {}>", nf.name),
            Value::NativeClosure(nc) => format!("<native fn {}>", nc.name),
            Value::Function(f) => match &f.name {
                Some(n) => format!("<fn {n}>"),
                None => "<lambda>".into(),
            },
            Value::Class(c) => format!("<class {}>", c.name),
            Value::Instance(i) => format!("<instance of {}>", i.borrow().class.name),
            Value::File(h) => format!("{:?}", h.borrow()),
        }
    }
}

// Equality is used by tests and by the `==` / `~=` operators. Functions
// (native or user-defined) compare by identity.
impl PartialEq for Value {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (Value::Nil, Value::Nil) => true,
            (Value::Bool(a), Value::Bool(b)) => a == b,
            (Value::Int(a), Value::Int(b)) => a == b,
            (Value::Float(a), Value::Float(b)) => a == b,
            (Value::Str(a), Value::Str(b)) => a == b,
            (Value::Table(a), Value::Table(b)) => Rc::ptr_eq(a, b),
            (Value::Native(a), Value::Native(b)) => Rc::ptr_eq(a, b),
            (Value::NativeClosure(a), Value::NativeClosure(b)) => Rc::ptr_eq(a, b),
            (Value::Function(a), Value::Function(b)) => Rc::ptr_eq(a, b),
            (Value::Class(a), Value::Class(b)) => Rc::ptr_eq(a, b),
            (Value::Instance(a), Value::Instance(b)) => Rc::ptr_eq(a, b),
            (Value::EnumVariant(a), Value::EnumVariant(b)) => Rc::ptr_eq(a, b),
            (Value::Enum(a), Value::Enum(b)) => Rc::ptr_eq(a, b),
            (Value::Interface(a), Value::Interface(b)) => Rc::ptr_eq(a, b),
            (Value::File(a), Value::File(b)) => Rc::ptr_eq(a, b),
            _ => false,
        }
    }
}

/// Runtime representation of an `interface` declaration.
///
/// Carries the interface's method signatures. Used for compile-time and
/// runtime verification that implementing classes have the required methods.
#[derive(Debug)]
pub struct InterfaceObject {
    pub name: String,
    /// Parent interfaces (for interface extension).
    pub extends: Vec<String>,
    /// Method signatures required by this interface.
    /// Key is method name, value is (param_count, has_return_type).
    pub methods: HashMap<String, (usize, bool)>,
}

// ──────────────────────────────────────────────────────────────────────────────
// Tables — hybrid array + map storage.
//
// The static type system decides how a table is *typed* (`table<T>` array or
// `table<K, V>` map). At runtime there is a single representation so a table
// passed across these boundaries (e.g. through `any`) never has to be
// converted. Positive integer keys collapse into the dense `array` part so the
// common array iteration path stays a `Vec` walk.
// ──────────────────────────────────────────────────────────────────────────────

/// A hashable key for the map part of a table.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum TableKey {
    Int(i64),
    Str(String),
    Bool(bool),
}

impl TableKey {
    pub fn from_value(v: &Value) -> Option<TableKey> {
        match v {
            Value::Int(i) => Some(TableKey::Int(*i)),
            Value::Str(s) => Some(TableKey::Str((**s).clone())),
            Value::Bool(b) => Some(TableKey::Bool(*b)),
            _ => None,
        }
    }

    pub fn to_value(&self) -> Value {
        match self {
            TableKey::Int(i) => Value::Int(*i),
            TableKey::Str(s) => Value::Str(Rc::new(s.clone())),
            TableKey::Bool(b) => Value::Bool(*b),
        }
    }

    pub fn display(&self) -> String {
        match self {
            TableKey::Int(i) => i.to_string(),
            TableKey::Str(s) => format!("\"{s}\""),
            TableKey::Bool(b) => b.to_string(),
        }
    }
}

#[derive(Debug, Default)]
pub struct TableObject {
    /// 1-based logical indices stored 0-based here.
    pub array: Vec<Value>,
    /// All non-array entries (non-integer keys or sparse integer keys).
    pub map: HashMap<TableKey, Value>,
}

impl TableObject {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn from_array(items: Vec<Value>) -> Self {
        Self {
            array: items,
            map: HashMap::new(),
        }
    }

    /// Array length (Lua-style `#t`). Does not include map entries.
    pub fn array_len(&self) -> usize {
        self.array.len()
    }

    /// Read by arbitrary value index. Returns `Nil` for missing keys.
    pub fn get(&self, key: &Value) -> Value {
        if let Value::Int(i) = key {
            if *i >= 1 && (*i as usize) <= self.array.len() {
                return self.array[(*i as usize) - 1].clone();
            }
        }
        match TableKey::from_value(key) {
            Some(k) => self.map.get(&k).cloned().unwrap_or(Value::Nil),
            None => Value::Nil,
        }
    }

    /// Write by arbitrary value index. Positive integers ≤ len+1 grow the
    /// array part; everything else lands in the map.
    pub fn set(&mut self, key: &Value, value: Value) -> Result<(), String> {
        if let Value::Int(i) = key
            && *i >= 1
        {
            let slot = (*i as usize) - 1;
            if slot < self.array.len() {
                self.array[slot] = value;
                return Ok(());
            }
            if slot == self.array.len() {
                self.array.push(value);
                // Pull any contiguous map entries into the array.
                let mut next = self.array.len() as i64 + 1;
                while let Some(v) = self.map.remove(&TableKey::Int(next)) {
                    self.array.push(v);
                    next += 1;
                }
                return Ok(());
            }
        }
        let Some(k) = TableKey::from_value(key) else {
            return Err(format!(
                "table keys must be integer, string, or boolean, got `{}`",
                key.type_name()
            ));
        };
        self.map.insert(k, value);
        Ok(())
    }
}

//! Runtime values for the Saule interpreter.
//!
//! When adding a new variant, remember to extend [`Value::type_name`],
//! [`Value::is_truthy`], [`Value::to_display_string`], and the `PartialEq`
//! impl below.

use std::cell::RefCell;
use std::collections::HashMap;
use std::fmt;
use std::rc::Rc;

use saule_ast::{Expr, Param, Spanned, Stmt};

use crate::env::Environment;

/// A Saule runtime value.
#[derive(Debug, Clone)]
pub enum Value {
    Nil,
    Bool(bool),
    Int(i64),
    Float(f64),
    /// Interned via `Rc` so cloning a value is cheap.
    Str(Rc<String>),
    /// Hybrid table storage: a dense array part plus a hashmap part. `table<T>`
    /// uses only the array; `table<K, V>` uses the map (and may also use the
    /// array when keys happen to be positive integers). Shared by reference so
    /// aliasing behaves like Lua tables.
    Table(Rc<RefCell<TableObject>>),
    /// Built-in function written in Rust (e.g. `print`).
    Native(Rc<NativeFn>),
    /// Built-in function with captured Rust state (e.g. iterators). Same call
    /// shape as `Native` but stateful and may return multiple values.
    NativeClosure(Rc<NativeClosure>),
    /// User-defined function or lambda. The `Rc` makes cloning cheap and
    /// gives recursive closures something stable to point at.
    Function(Rc<FunctionObject>),
    /// A class declaration — carries its statics, instance template, and
    /// optional parent. Compared by identity.
    Class(Rc<ClassObject>),
    /// An instance produced by `new ClassName(args)`. Fields are mutable
    /// behind a `RefCell`; identity is the `Rc` pointer.
    Instance(Rc<RefCell<InstanceObject>>),
    /// An enum variant: carries the enum name, variant name, and optional
    /// value. Compared by identity so each access to `Status.Alive` returns
    /// the same `Rc` pointer.
    EnumVariant(Rc<EnumVariantObject>),
    /// An enum declaration — carries its variants and methods.
    Enum(Rc<EnumObject>),
    /// An interface declaration — carries method signatures.
    Interface(Rc<InterfaceObject>),
    /// An open (or closed) file handle returned by `Io.open` and the
    /// `Io.stdin`/`stdout`/`stderr` statics. Methods are dispatched via a
    /// static table inside `stdlib::io`.
    File(Rc<RefCell<FileHandle>>),
}

/// Backing storage for a `Value::File`. Variants split read- and write-side
/// state so we can buffer line reads via `BufReader` while leaving writes
/// unbuffered (the caller can call `:flush` explicitly when needed).
pub enum FileHandle {
    Stdin(std::io::BufReader<std::io::Stdin>),
    Stdout,
    Stderr,
    Open {
        path: String,
        reader: Option<std::io::BufReader<std::fs::File>>,
        writer: Option<std::fs::File>,
    },
    Closed,
}

impl fmt::Debug for FileHandle {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            FileHandle::Stdin(_) => write!(f, "<file stdin>"),
            FileHandle::Stdout => write!(f, "<file stdout>"),
            FileHandle::Stderr => write!(f, "<file stderr>"),
            FileHandle::Open { path, .. } => write!(f, "<file {path}>"),
            FileHandle::Closed => write!(f, "<closed file>"),
        }
    }
}

#[derive(Debug)]
pub struct EnumVariantObject {
    pub enum_name: String,
    pub variant_name: String,
    pub value: Option<Value>,
    /// Reference to the enum so we can access methods. Stored in RefCell to
    /// allow updating after enum creation (breaking the circular reference issue).
    pub enum_obj: std::cell::RefCell<Option<Rc<EnumObject>>>,
}

#[derive(Debug)]
pub struct EnumObject {
    pub name: String,
    /// Enum variants, keyed by name. Each variant is cached so identity is stable.
    pub variants: HashMap<String, Rc<EnumVariantObject>>,
    /// Methods defined on the enum, keyed by name.
    pub methods: HashMap<String, Rc<FunctionObject>>,
}

/// Rust-implemented function exposed to Saule.
///
/// The function returns `Result<Value, String>` where the error string is
/// surfaced as a `RuntimeError::TypeError` at the call site.
pub struct NativeFn {
    pub name: &'static str,
    pub func: fn(&[Value]) -> Result<Value, String>,
}

impl fmt::Debug for NativeFn {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "<native fn {}>", self.name)
    }
}

/// Stateful Rust-implemented function. The closure may capture arbitrary
/// Rust state (e.g. an iterator's cursor) and may return multiple values.
pub struct NativeClosure {
    pub name: &'static str,
    pub func: Box<dyn Fn(&[Value]) -> Result<Vec<Value>, String>>,
}

impl fmt::Debug for NativeClosure {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "<native closure {}>", self.name)
    }
}

/// A user-defined function carrying its body and lexical closure.
#[derive(Debug)]
pub struct FunctionObject {
    /// `Some(name)` for named declarations, `None` for lambdas.
    pub name: Option<String>,
    pub params: Vec<Param>,
    pub body: FunctionBody,
    /// The environment that was in scope when the function was created.
    /// Captured by reference so inner functions see live bindings.
    pub closure: Rc<RefCell<Environment>>,
    /// `Some(class)` when this function is a method (static or instance) of
    /// a class. Set after class construction via [`set_owner_class`]. The
    /// call sites consult this to re-inject the owning class's statics into
    /// the call scope, so a static method can reach sibling statics by their
    /// bare names even when invoked as a plain `Value::Function`.
    pub owner_class: RefCell<Option<std::rc::Weak<ClassObject>>>,
}

impl FunctionObject {
    /// Attach this function to its owning class. No-op when called more than
    /// once; the first owner wins.
    pub fn set_owner_class(&self, class: &Rc<ClassObject>) {
        let mut slot = self.owner_class.borrow_mut();
        if slot.is_none() {
            *slot = Some(Rc::downgrade(class));
        }
    }

    /// Resolve the owning class, if any. Returns `None` once the class has
    /// been dropped (which shouldn't happen in practice because the class
    /// outlives its methods).
    pub fn resolved_owner(&self) -> Option<Rc<ClassObject>> {
        self.owner_class.borrow().as_ref().and_then(|w| w.upgrade())
    }
}

/// Function bodies come in two shapes:
///   * a block of statements (named `fn` decls, block-body lambdas),
///   * a single expression (arrow-style lambdas like `(x) => x + 1`).
#[derive(Debug, Clone)]
pub enum FunctionBody {
    Block(Vec<Spanned<Stmt>>),
    Expr(Box<Spanned<saule_ast::Expr>>),
}

/// Runtime representation of a `class` declaration.
///
/// Instance fields live on the [`InstanceObject`]; statics live here (behind
/// a `RefCell` because they can be reassigned). Methods are stored as
/// already-constructed [`FunctionObject`]s capturing the module-level
/// environment so they can refer to other top-level names (including the
/// class itself for static calls).
#[derive(Debug)]
pub struct ClassObject {
    pub name: String,
    pub parent: Option<Rc<ClassObject>>,
    /// Instance-field templates evaluated on construction.
    pub field_defs: Vec<FieldDef>,
    /// Instance methods, keyed by name. First parameter is the user-written
    /// `self`, so calling `obj:method(a)` is the same as `method(obj, a)`.
    pub methods: HashMap<String, Rc<FunctionObject>>,
    /// Static fields. Mutable through `ClassName.field = …`.
    pub static_fields: RefCell<HashMap<String, Value>>,
    /// Static methods (no implicit `self`).
    pub static_methods: HashMap<String, Rc<FunctionObject>>,
    /// `constructor(args) … end`. None means the class has no explicit
    /// constructor — `new` still produces a valid instance.
    pub constructor: Option<Rc<FunctionObject>>,
}

#[derive(Debug, Clone)]
pub struct FieldDef {
    pub name: String,
    /// Evaluated in the constructor scope each time an instance is built.
    pub default: Option<Spanned<Expr>>,
}

#[derive(Debug)]
pub struct InstanceObject {
    pub class: Rc<ClassObject>,
    pub fields: HashMap<String, Value>,
}

impl ClassObject {
    /// Walk the inheritance chain for a method.
    pub fn lookup_method(self: &Rc<Self>, name: &str) -> Option<Rc<FunctionObject>> {
        if let Some(m) = self.methods.get(name) {
            return Some(m.clone());
        }
        self.parent.as_ref().and_then(|p| p.lookup_method(name))
    }

    /// Walk the inheritance chain for a static method.
    pub fn lookup_static_method(self: &Rc<Self>, name: &str) -> Option<Rc<FunctionObject>> {
        if let Some(m) = self.static_methods.get(name) {
            return Some(m.clone());
        }
        self.parent
            .as_ref()
            .and_then(|p| p.lookup_static_method(name))
    }

    /// Walk the inheritance chain for a static field.
    pub fn lookup_static_field(self: &Rc<Self>, name: &str) -> Option<Value> {
        if let Some(v) = self.static_fields.borrow().get(name) {
            return Some(v.clone());
        }
        self.parent
            .as_ref()
            .and_then(|p| p.lookup_static_field(name))
    }
}

impl Value {
    /// Human-readable type name for error messages — matches the names used
    /// in the README's type system.
    pub fn type_name(&self) -> &'static str {
        match self {
            Value::Nil => "nil",
            Value::Bool(_) => "boolean",
            Value::Int(_) => "integer",
            Value::Float(_) => "float",
            Value::Str(_) => "string",
            Value::Table(_) => "table",
            Value::Native(_) | Value::NativeClosure(_) | Value::Function(_) => "function",
            Value::Class(_) => "class",
            Value::Instance(_) => "instance",
            Value::EnumVariant(_) => "enum",
            Value::Enum(_) => "enum",
            Value::Interface(_) => "interface",
            Value::File(_) => "file",
        }
    }

    /// Lua-style truthiness: only `nil` and `false` are falsy.
    pub fn is_truthy(&self) -> bool {
        !matches!(self, Value::Nil | Value::Bool(false))
    }

    /// Format used by `print` and the `..` operator.
    pub fn to_display_string(&self) -> String {
        match self {
            Value::Nil => "nil".into(),
            Value::Bool(b) => b.to_string(),
            Value::Int(n) => n.to_string(),
            Value::Float(f) => {
                // Always show a decimal point so floats are visually distinct
                // from ints, matching the README's display style.
                if f.fract() == 0.0 && f.is_finite() {
                    format!("{f:.1}")
                } else {
                    f.to_string()
                }
            }
            Value::Str(s) => (**s).clone(),
            Value::Table(items) => {
                let t = items.borrow();
                let array_parts = t.array.iter().map(Value::to_display_string);
                let map_parts = t
                    .map
                    .iter()
                    .map(|(k, v)| format!("{}={}", k.display(), v.to_display_string()));
                let parts: Vec<String> = array_parts.chain(map_parts).collect();
                format!("{{{}}}", parts.join(", "))
            }
            Value::EnumVariant(ev) => {
                format!("{}.{}", ev.enum_name, ev.variant_name)
            }
            Value::Enum(e) => format!("<enum {}>", e.name),
            Value::Interface(iface) => format!("<interface {}>", iface.name),
            Value::Native(nf) => format!("<native fn {}>", nf.name),
            Value::NativeClosure(nc) => format!("<native fn {}>", nc.name),
            Value::Function(f) => match &f.name {
                Some(n) => format!("<fn {n}>"),
                None => "<lambda>".into(),
            },
            Value::Class(c) => format!("<class {}>", c.name),
            Value::Instance(i) => format!("<instance of {}>", i.borrow().class.name),
            Value::File(h) => format!("{:?}", h.borrow()),
        }
    }
}

// Equality is used by tests and by the `==` / `~=` operators. Functions
// (native or user-defined) compare by identity.
impl PartialEq for Value {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (Value::Nil, Value::Nil) => true,
            (Value::Bool(a), Value::Bool(b)) => a == b,
            (Value::Int(a), Value::Int(b)) => a == b,
            (Value::Float(a), Value::Float(b)) => a == b,
            (Value::Str(a), Value::Str(b)) => a == b,
            (Value::Table(a), Value::Table(b)) => Rc::ptr_eq(a, b),
            (Value::Native(a), Value::Native(b)) => Rc::ptr_eq(a, b),
            (Value::NativeClosure(a), Value::NativeClosure(b)) => Rc::ptr_eq(a, b),
            (Value::Function(a), Value::Function(b)) => Rc::ptr_eq(a, b),
            (Value::Class(a), Value::Class(b)) => Rc::ptr_eq(a, b),
            (Value::Instance(a), Value::Instance(b)) => Rc::ptr_eq(a, b),
            (Value::EnumVariant(a), Value::EnumVariant(b)) => Rc::ptr_eq(a, b),
            (Value::Enum(a), Value::Enum(b)) => Rc::ptr_eq(a, b),
            (Value::Interface(a), Value::Interface(b)) => Rc::ptr_eq(a, b),
            (Value::File(a), Value::File(b)) => Rc::ptr_eq(a, b),
            _ => false,
        }
    }
}

/// Runtime representation of an `interface` declaration.
///
/// Carries the interface's method signatures. Used for compile-time and
/// runtime verification that implementing classes have the required methods.
#[derive(Debug)]
pub struct InterfaceObject {
    pub name: String,
    /// Parent interfaces (for interface extension).
    pub extends: Vec<String>,
    /// Method signatures required by this interface.
    /// Key is method name, value is (param_count, has_return_type).
    pub methods: HashMap<String, (usize, bool)>,
}

// ──────────────────────────────────────────────────────────────────────────────
// Tables — hybrid array + map storage.
//
// The static type system decides how a table is *typed* (`table<T>` array or
// `table<K, V>` map). At runtime there is a single representation so a table
// passed across these boundaries (e.g. through `any`) never has to be
// converted. Positive integer keys collapse into the dense `array` part so the
// common array iteration path stays a `Vec` walk.
// ──────────────────────────────────────────────────────────────────────────────

/// A hashable key for the map part of a table.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum TableKey {
    Int(i64),
    Str(String),
    Bool(bool),
}

impl TableKey {
    pub fn from_value(v: &Value) -> Option<TableKey> {
        match v {
            Value::Int(i) => Some(TableKey::Int(*i)),
            Value::Str(s) => Some(TableKey::Str((**s).clone())),
            Value::Bool(b) => Some(TableKey::Bool(*b)),
            _ => None,
        }
    }

    pub fn to_value(&self) -> Value {
        match self {
            TableKey::Int(i) => Value::Int(*i),
            TableKey::Str(s) => Value::Str(Rc::new(s.clone())),
            TableKey::Bool(b) => Value::Bool(*b),
        }
    }

    pub fn display(&self) -> String {
        match self {
            TableKey::Int(i) => i.to_string(),
            TableKey::Str(s) => format!("\"{s}\""),
            TableKey::Bool(b) => b.to_string(),
        }
    }
}

#[derive(Debug, Default)]
pub struct TableObject {
    /// 1-based logical indices stored 0-based here.
    pub array: Vec<Value>,
    /// All non-array entries (non-integer keys or sparse integer keys).
    pub map: HashMap<TableKey, Value>,
}

impl TableObject {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn from_array(items: Vec<Value>) -> Self {
        Self {
            array: items,
            map: HashMap::new(),
        }
    }

    /// Array length (Lua-style `#t`). Does not include map entries.
    pub fn array_len(&self) -> usize {
        self.array.len()
    }

    /// Read by arbitrary value index. Returns `Nil` for missing keys.
    pub fn get(&self, key: &Value) -> Value {
        if let Value::Int(i) = key {
            if *i >= 1 && (*i as usize) <= self.array.len() {
                return self.array[(*i as usize) - 1].clone();
            }
        }
        match TableKey::from_value(key) {
            Some(k) => self.map.get(&k).cloned().unwrap_or(Value::Nil),
            None => Value::Nil,
        }
    }

    /// Write by arbitrary value index. Positive integers ≤ len+1 grow the
    /// array part; everything else lands in the map.
    pub fn set(&mut self, key: &Value, value: Value) -> Result<(), String> {
        if let Value::Int(i) = key
            && *i >= 1
        {
            let slot = (*i as usize) - 1;
            if slot < self.array.len() {
                self.array[slot] = value;
                return Ok(());
            }
            if slot == self.array.len() {
                self.array.push(value);
                // Pull any contiguous map entries into the array.
                let mut next = self.array.len() as i64 + 1;
                while let Some(v) = self.map.remove(&TableKey::Int(next)) {
                    self.array.push(v);
                    next += 1;
                }
                return Ok(());
            }
        }
        let Some(k) = TableKey::from_value(key) else {
            return Err(format!(
                "table keys must be integer, string, or boolean, got `{}`",
                key.type_name()
            ));
        };
        self.map.insert(k, value);
        Ok(())
    }
}

//! Core prelude functions.

use std::rc::Rc;

use crate::env::Environment;
use crate::stdlib::{define_native, expect_arity};
use crate::value::Value;

pub fn install(env: &std::rc::Rc<std::cell::RefCell<Environment>>) {
    define_native(env, "print", builtin_print);
    define_native(env, "println", builtin_println);
    define_native(env, "printf", builtin_printf);
    define_native(env, "tostring", builtin_tostring);
    define_native(env, "type", builtin_type);
    define_native(env, "int", builtin_int);
    define_native(env, "float", builtin_float);
    define_native(env, "assert", builtin_assert);
}

fn builtin_print(args: &[Value]) -> Result<Value, String> {
    let parts: Vec<String> = args.iter().map(|v| v.to_display_string()).collect();
    print!("{}", parts.join("\t"));
    Ok(Value::Nil)
}

fn builtin_println(args: &[Value]) -> Result<Value, String> {
    let parts: Vec<String> = args.iter().map(|v| v.to_display_string()).collect();
    println!("{}", parts.join("\t"));
    Ok(Value::Nil)
}

fn builtin_tostring(args: &[Value]) -> Result<Value, String> {
    let v = args.first().cloned().unwrap_or(Value::Nil);
    Ok(Value::Str(Rc::new(v.to_display_string())))
}

fn builtin_type(args: &[Value]) -> Result<Value, String> {
    let v = args.first().cloned().unwrap_or(Value::Nil);
    let name = match &v {
        Value::Instance(inst) => inst.borrow().class.name.clone(),
        _ => v.type_name().to_string(),
    };
    Ok(Value::Str(Rc::new(name)))
}

fn builtin_int(args: &[Value]) -> Result<Value, String> {
    expect_arity("int", args, 1)?;
    match &args[0] {
        Value::Int(n) => Ok(Value::Int(*n)),
        Value::Float(f) => Ok(Value::Int(f.trunc() as i64)),
        other => Err(format!(
            "int expects integer or float, got `{}`",
            other.type_name()
        )),
    }
}

fn builtin_float(args: &[Value]) -> Result<Value, String> {
    expect_arity("float", args, 1)?;
    match &args[0] {
        Value::Float(f) => Ok(Value::Float(*f)),
        Value::Int(n) => Ok(Value::Float(*n as f64)),
        other => Err(format!(
            "float expects integer or float, got `{}`",
            other.type_name()
        )),
    }
}

fn builtin_assert(args: &[Value]) -> Result<Value, String> {
    if args.is_empty() {
        return Err("assert expects at least 1 argument".to_string());
    }
    if args[0].is_truthy() {
        return Ok(args.get(1).cloned().unwrap_or_else(|| args[0].clone()));
    }

    let message = args
        .get(1)
        .cloned()
        .unwrap_or_else(|| Value::Str(Rc::new("assertion failed".to_string())));
    Err(format!("assertion failed: {}", message.to_display_string()))
}

fn builtin_error(args: &[Value]) -> Result<Value, String> {
    let msg = args
        .first()
        .cloned()
        .unwrap_or_else(|| Value::Str(Rc::new("error".to_string())));
    Err(msg.to_display_string())
}

