//! Expression evaluation.

use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

use saule_ast::{BinOp, CallArg, Expr, LambdaBody, Spanned, Type};

use crate::env::Environment;
use crate::error::RuntimeError;
use crate::value::{ClassObject, FunctionBody, FunctionObject, InstanceObject, Value};

use super::{Flow, ops};

const SUPER_OWNER_BINDING: &str = "__saule_super_owner";

#[derive(Clone)]
pub(crate) enum EvaluatedArg {
    Positional(Value),
    Named { name: String, value: Value },
}

pub fn eval(expr: &Spanned<Expr>, env: &Rc<RefCell<Environment>>) -> Result<Value, RuntimeError> {
    let span = expr.span.clone();
    match &expr.value {
        Expr::Int(n) => Ok(Value::Int(*n)),
        Expr::Float(f) => Ok(Value::Float(*f)),
        Expr::Bool(b) => Ok(Value::Bool(*b)),
        Expr::Str(s) => Ok(Value::Str(Rc::new(s.clone()))),
        Expr::Nil => Ok(Value::Nil),

        Expr::Ident(name) => env
            .borrow()
            .get(name)
            .ok_or_else(|| RuntimeError::Undefined {
                name: name.clone(),
                span,
            }),

        Expr::Unary { op, rhs } => {
            let v = eval(rhs, env)?;
            ops::unary(*op, v, span)
        }

        Expr::Binary { op, lhs, rhs } => match op {
            // `and` / `or` short-circuit, so evaluate lazily.
            BinOp::And => {
                let l = eval(lhs, env)?;
                if l.is_truthy() { eval(rhs, env) } else { Ok(l) }
            }
            BinOp::Or => {
                let l = eval(lhs, env)?;
                if l.is_truthy() { Ok(l) } else { eval(rhs, env) }
            }
            // `??` short-circuits: only evaluate RHS when LHS is nil.
            BinOp::Coalesce => {
                let l = eval(lhs, env)?;
                if matches!(l, Value::Nil) { eval(rhs, env) } else { Ok(l) }
            }
            _ => {
                let l = eval(lhs, env)?;
                let r = eval(rhs, env)?;
                ops::binary(*op, l, r, span)
            }
        },

        Expr::Call { callee, args } => {
            // Dotted calls (`obj.method(args)`) and `self.super(args)` need
            // special handling so we can auto-bind `self` and route to the
            // parent constructor respectively. Saule lets instance methods
            // omit the explicit `self` parameter — see `call_instance_method`.
            if let Expr::Member { obj, name } = &callee.value {
                if name == "super" {
                    return super_call(obj, args, env, span);
                }
                let receiver = eval(obj, env)?;
                let vs = eval_call_args(args, env)?;
                return dispatch_member_call(&receiver, name, vs, span);
            }

            let cv = eval(callee, env)?;
            let vs = eval_call_args(args, env)?;
            call_value(cv, &vs, span)
        }

        // Postfix / composite forms — wait until later phases.
        Expr::Member { obj, name } => {
            let receiver = eval(obj, env)?;
            read_member(&receiver, name, span)
        }
        Expr::SafeMember { obj, name } => {
            let receiver = eval(obj, env)?;
            if matches!(receiver, Value::Nil) {
                Ok(Value::Nil)
            } else {
                read_member(&receiver, name, span)
            }
        }
        Expr::Index { obj, index } => {
            let receiver = eval(obj, env)?;
            let index_value = eval(index, env)?;
            read_index(&receiver, index_value, span)
        }
        Expr::MethodCall { obj, method, args } => {
            let receiver = eval(obj, env)?;
            let evaled = eval_call_args(args, env)?;
            invoke_method(&receiver, method, evaled, span)
        }
        Expr::ForceUnwrap(inner) => {
            let v = eval(inner, env)?;
            if matches!(v, Value::Nil) {
                Err(RuntimeError::ForceUnwrapNil { span })
            } else {
                Ok(v)
            }
        }
        Expr::Table(items) => {
            let mut values = Vec::with_capacity(items.len());
            for item in items {
                values.push(eval(item, env)?);
            }
            Ok(Value::Table(Rc::new(RefCell::new(
                crate::value::TableObject::from_array(values),
            ))))
        }

        Expr::Lambda { params, body, .. } => {
            let body = match body {
                LambdaBody::Expr(e) => FunctionBody::Expr(e.clone()),
                LambdaBody::Block(stmts) => FunctionBody::Block(stmts.clone()),
            };
            Ok(Value::Function(Rc::new(FunctionObject {
                name: None,
                params: params.clone(),
                body,
                closure: env.clone(),
            })))
        }

        Expr::Self_ => env
            .borrow()
            .get("self")
            .ok_or_else(|| RuntimeError::Undefined {
                name: "self".to_string(),
                span,
            }),
    }
}

fn first_or_nil(values: Vec<Value>) -> Value {
    values.into_iter().next().unwrap_or(Value::Nil)
}

pub(crate) fn eval_values(
    expr: &Spanned<Expr>,
    env: &Rc<RefCell<Environment>>,
) -> Result<Vec<Value>, RuntimeError> {
    let span = expr.span.clone();
    match &expr.value {
        Expr::Call { callee, args } => {
            if let Expr::Member { obj, name } = &callee.value {
                if name == "super" {
                    return Ok(vec![super_call(obj, args, env, span)?]);
                }
                let receiver = eval(obj, env)?;
                let vs = eval_call_args(args, env)?;
                return dispatch_member_call_multi(&receiver, name, vs, span);
            }

            let cv = eval(callee, env)?;
            let vs = eval_call_args(args, env)?;
            call_value_multi(cv, &vs, span)
        }
        Expr::MethodCall { obj, method, args } => {
            let receiver = eval(obj, env)?;
            let evaled = eval_call_args(args, env)?;
            invoke_method_multi(&receiver, method, evaled, span)
        }
        _ => Ok(vec![eval(expr, env)?]),
    }
}

/// Invoke a callable [`Value`]. Handles both native and user-defined
/// functions.
fn call_value(
    callee: Value,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(call_value_multi(callee, args, span)?))
}

pub(crate) fn call_value_multi(
    callee: Value,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    match callee {
        Value::Native(nf) => {
            let mut positional = Vec::with_capacity(args.len());
            for arg in args {
                match arg {
                    EvaluatedArg::Positional(v) => positional.push(v.clone()),
                    EvaluatedArg::Named { name: _, .. } => {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "named arguments are not supported for built-in function `{}` — use positional arguments instead",
                                nf.name
                            ),
                            span,
                        });
                    }
                }
            }
            (nf.func)(&positional)
                .map(|v| vec![v])
                .map_err(|message| RuntimeError::TypeError { message, span })
        }
        Value::Function(f) => call_function_multi(&f, args, span),
        Value::NativeClosure(nc) => {
            let mut positional = Vec::with_capacity(args.len());
            for arg in args {
                match arg {
                    EvaluatedArg::Positional(v) => positional.push(v.clone()),
                    EvaluatedArg::Named { name: _, .. } => {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "named arguments are not supported for built-in function `{}` — use positional arguments instead",
                                nc.name
                            ),
                            span,
                        });
                    }
                }
            }
            (nc.func)(&positional)
                .map_err(|message| RuntimeError::TypeError { message, span })
        }
        // `ClassName(args)` constructs an instance.
        Value::Class(c) => construct(c, args, span).map(|v| vec![v]),
        other => Err(RuntimeError::TypeError {
            message: format!(
                "value of type `{}` is not callable — only functions, classes, and methods can be called",
                other.type_name()
            ),
            span,
        }),
    }
}

/// Bind `params` into `scope` from `args`, evaluating defaults lazily. Used
/// by every kind of call (free function, instance method, static method,
/// constructor) so the rules stay in one place.
fn bind_params(
    scope: &Rc<RefCell<Environment>>,
    params: &[saule_ast::Param],
    args: &[EvaluatedArg],
    span: &std::ops::Range<usize>,
) -> Result<(), RuntimeError> {
    let variadic_indices: Vec<usize> = params
        .iter()
        .enumerate()
        .filter_map(|(i, p)| p.variadic.then_some(i))
        .collect();
    if variadic_indices.len() > 1 {
        return Err(RuntimeError::TypeError {
            message: "a function can declare at most one variadic parameter".to_string(),
            span: params[variadic_indices[1]].span.clone(),
        });
    }
    let variadic_idx = variadic_indices.first().copied();
    if let Some(idx) = variadic_idx
        && idx + 1 != params.len()
    {
        return Err(RuntimeError::TypeError {
            message: format!(
                "variadic parameter `{}` must be the last parameter in the list",
                params[idx].name
            ),
            span: params[idx].span.clone(),
        });
    }

    let mut assigned: Vec<Option<Value>> = vec![None; params.len()];
    let mut variadic_values: Vec<Value> = Vec::new();
    let mut next_positional = 0usize;
    let mut seen_named = false;
    let mut named_arg_count = 0usize;

    for arg in args {
        match arg {
            EvaluatedArg::Positional(value) => {
                if seen_named {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "positional argument #{} cannot follow named arguments; all positional arguments must come first",
                            next_positional + 1
                        ),
                        span: span.clone(),
                    });
                }
                if let Some(var_idx) = variadic_idx
                    && next_positional >= var_idx
                {
                    variadic_values.push(value.clone());
                    next_positional += 1;
                    continue;
                }
                if next_positional >= params.len() {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "too many arguments: expected {} but got at least {}",
                            params.len(),
                            next_positional + 1
                        ),
                        span: span.clone(),
                    });
                }
                assigned[next_positional] = Some(value.clone());
                next_positional += 1;
            }
            EvaluatedArg::Named { name, value } => {
                seen_named = true;
                named_arg_count += 1;
                let Some(idx) = params.iter().position(|p| p.name == *name) else {
                    let valid_params: Vec<String> = params.iter().map(|p| p.name.clone()).collect();
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "unknown named argument `{name}` (argument #{} of {}) — valid parameters: {}",
                            named_arg_count,
                            args.len(),
                            valid_params.join(", ")
                        ),
                        span: span.clone(),
                    });
                };
                if params[idx].variadic {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "variadic parameter `{name}` cannot be passed by name — provide any extra arguments positionally"
                        ),
                        span: span.clone(),
                    });
                }
                if assigned[idx].is_some() {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "duplicate argument for parameter `{name}` — this parameter was already provided"
                        ),
                        span: span.clone(),
                    });
                }
                assigned[idx] = Some(value.clone());
            }
        }
    }

    let missing_required: Vec<String> = params
        .iter()
        .enumerate()
        .filter_map(|(i, p)| {
            if assigned[i].is_none()
                && !p.variadic
                && p.default.is_none()
                && !is_nullable_type(&p.ty)
            {
                Some(p.name.clone())
            } else {
                None
            }
        })
        .collect();

    for (i, param) in params.iter().enumerate() {
        if param.variadic {
            scope.borrow_mut().define(
                param.name.clone(),
                Value::Table(Rc::new(RefCell::new(crate::value::TableObject::from_array(
                    variadic_values.clone(),
                )))),
            );
            continue;
        }
        let value = if let Some(v) = assigned[i].clone() {
            v
        } else if let Some(default) = &param.default {
            eval(default, scope)?
        } else if is_nullable_type(&param.ty) {
            Value::Nil
        } else {
            let help = if missing_required.len() == 1 {
                Some(format!(
                    "add argument `{}` to this call (positionally or by name)",
                    missing_required[0]
                ))
            } else {
                Some(format!(
                    "add required arguments to this call: {}",
                    missing_required
                        .iter()
                        .map(|n| format!("`{n}`"))
                        .collect::<Vec<_>>()
                        .join(", ")
                ))
            };
            return Err(RuntimeError::ArgumentError {
                message: if missing_required.len() == 1 {
                    format!("missing required argument for parameter `{}`", param.name)
                } else {
                    format!(
                        "missing {} required argument(s): {}",
                        missing_required.len(),
                        missing_required.join(", ")
                    )
                },
                help,
                span: span.clone(),
            });
        };
        scope.borrow_mut().define(param.name.clone(), value);
    }
    Ok(())
}

fn is_nullable_type(ty: &Type) -> bool {
    matches!(ty, Type::Nullable(_)) || matches!(ty, Type::Named(n) if n == "nil")
}

#[allow(dead_code)]
pub(crate) fn table_index_to_slot(index: &Value) -> Result<Option<usize>, String> {
    match index {
        Value::Int(i) if *i <= 0 => Ok(None),
        Value::Int(i) => Ok(Some((*i as usize) - 1)),
        other => Err(format!(
            "table indices must be integers, got `{}`",
            other.type_name()
        )),
    }
}

fn read_index(
    receiver: &Value,
    index: Value,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    match receiver {
        Value::Table(items) => Ok(items.borrow().get(&index)),
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot index a `{}` — only tables support `[index]` access",
                other.type_name()
            ),
            span,
        }),
    }
}

fn eval_call_args(
    args: &[CallArg],
    env: &Rc<RefCell<Environment>>,
) -> Result<Vec<EvaluatedArg>, RuntimeError> {
    let mut out = Vec::with_capacity(args.len());
    for arg in args {
        match arg {
            CallArg::Positional(expr) => out.push(EvaluatedArg::Positional(eval(expr, env)?)),
            CallArg::Named { name, value } => out.push(EvaluatedArg::Named {
                name: name.clone(),
                value: eval(value, env)?,
            }),
        }
    }
    Ok(out)
}

fn run_function_body(
    f: &FunctionObject,
    scope: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(run_function_body_multi(f, scope, span)?))
}

fn run_function_body_multi(
    f: &FunctionObject,
    scope: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    let outcome = match &f.body {
        FunctionBody::Block(stmts) => super::stmt::exec_block(stmts, scope)?,
        FunctionBody::Expr(e) => Flow::Return(vec![eval(e, scope)?]),
    };
    match outcome {
        Flow::Return(values) => Ok(values),
        Flow::Normal(_) => Ok(vec![Value::Nil]),
        Flow::Break => Err(RuntimeError::LoopControlOutsideLoop {
            which: "break",
            span,
        }),
        Flow::Continue => Err(RuntimeError::LoopControlOutsideLoop {
            which: "continue",
            span,
        }),
    }
}

/// Skip a leading `self` parameter (so explicit-self style still works
/// alongside the implicit-self style this language prefers).
fn user_params(f: &FunctionObject) -> &[saule_ast::Param] {
    if f.params.first().map(|p| p.name == "self").unwrap_or(false) {
        &f.params[1..]
    } else {
        &f.params
    }
}

/// Call a user-defined function: binds args (with defaults), executes the
/// body in a fresh scope parented to the function's closure, and converts
/// the resulting [`Flow`] into a return value.
pub(crate) fn call_function(
    f: &FunctionObject,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(call_function_multi(f, args, span)?))
}

fn call_function_multi(
    f: &FunctionObject,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    let scope = Environment::with_parent(f.closure.clone());
    bind_params(&scope, &f.params, args, &span)?;
    run_function_body_multi(f, &scope, span)
}

fn call_instance_method_multi(
    f: &FunctionObject,
    receiver: Value,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    let scope = Environment::with_parent(f.closure.clone());
    // Inject the class's static fields/methods so the method body can refer
    // to them by their bare names — see `inject_class_statics` for why.
    if let Value::Instance(inst) = &receiver {
        inject_class_statics(&scope, &inst.borrow().class);
    }
    scope.borrow_mut().define("self".to_string(), receiver);
    bind_params(&scope, user_params(f), args, &span)?;
    run_function_body_multi(f, &scope, span)
}

/// Invoke a static method with `self` bound to the class itself, which is
/// what makes `self.staticField` inside a `static fn` resolve to the right
/// thing (and is the only way `Main.main()` can reach `Main.lauris`).
fn call_static_method(
    f: &FunctionObject,
    class: &Rc<ClassObject>,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(call_static_method_multi(f, class, args, span)?))
}

fn call_static_method_multi(
    f: &FunctionObject,
    class: &Rc<ClassObject>,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    let scope = Environment::with_parent(f.closure.clone());
    inject_class_statics(&scope, class);
    scope
        .borrow_mut()
        .define("self".to_string(), Value::Class(class.clone()));
    bind_params(&scope, user_params(f), args, &span)?;
    run_function_body_multi(f, &scope, span)
}

/// Make the class's static fields and methods directly visible inside a
/// method body, so users can write `lauris.introduce()` instead of
/// `self.lauris.introduce()` or `Main.lauris.introduce()`. Parent statics
/// are seeded first and overridden by child statics, matching the lookup
/// order used for member access. Locals and parameters bound later still
/// shadow these, so the user can introduce a same-named local without
/// surprise.
fn inject_class_statics(scope: &Rc<RefCell<Environment>>, class: &Rc<ClassObject>) {
    // Collect the chain root-first so the most-derived class wins.
    let mut chain: Vec<Rc<ClassObject>> = Vec::new();
    let mut cur = Some(class.clone());
    while let Some(c) = cur {
        chain.push(c.clone());
        cur = c.parent.clone();
    }
    for c in chain.iter().rev() {
        for (n, v) in c.static_fields.borrow().iter() {
            scope.borrow_mut().define(n.clone(), v.clone());
        }
        for (n, f) in &c.static_methods {
            scope
                .borrow_mut()
                .define(n.clone(), Value::Function(f.clone()));
        }
    }
}

/// Public re-export of [`call_static_method`] for embedders. Kept as a thin
/// wrapper so the implementation details (param binding, `self` injection)
/// stay private to this module.
pub(crate) fn call_static_method_public(
    f: &FunctionObject,
    class: &Rc<ClassObject>,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    call_static_method(f, class, args, span)
}

/// Resolve `obj.name(args)` where the lookup intent is to *invoke* the
/// result. Instance methods get implicit `self`; static methods get the
/// class as `self`; non-function fields are simply invoked through
/// [`call_value`].
fn dispatch_member_call(
    receiver: &Value,
    name: &str,
    args: Vec<EvaluatedArg>,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(dispatch_member_call_multi(receiver, name, args, span)?))
}

fn dispatch_member_call_multi(
    receiver: &Value,
    name: &str,
    args: Vec<EvaluatedArg>,
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    match receiver {
        Value::Instance(inst) => {
            let class = inst.borrow().class.clone();
            if let Some(m) = class.lookup_method(name) {
                return call_instance_method_multi(&m, receiver.clone(), &args, span);
            }
            if let Some(m) = class.lookup_static_method(name) {
                return call_static_method_multi(&m, &class, &args, span);
            }
            // Fall back: maybe the instance has a callable field.
            if let Some(v) = inst.borrow().fields.get(name).cloned() {
                return call_value_multi(v, &args, span);
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no method or field `{name}` on instance of class `{}` — instance members are case-sensitive",
                    class.name
                ),
                span,
            })
        }
        Value::Class(class) => {
            if let Some(m) = class.lookup_static_method(name) {
                return call_static_method_multi(&m, class, &args, span);
            }
            if let Some(v) = class.lookup_static_field(name) {
                return call_value_multi(v, &args, span);
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no static member `{name}` on class `{}` — check the class definition for the correct name",
                    class.name
                ),
                span,
            })
        }
        Value::EnumVariant(_variant) => {
            // Look up the method in the enum's method list, then call with
            // self bound to the variant.
            let v = read_member(receiver, name, span.clone())?;
            match v {
                Value::Function(m) => {
                    call_instance_method_multi(&m, receiver.clone(), &args, span)
                }
                _ => call_value_multi(v, &args, span),
            }
        }
        _ => {
            // Generic: read the field, then call it.
            let v = read_member(receiver, name, span.clone())?;
            call_value_multi(v, &args, span)
        }
    }
}

/// `self.super(args)` — call the parent class's constructor on the current
/// instance. The receiver expression must evaluate to an instance whose
/// class has a parent.
fn super_call(
    obj: &Spanned<Expr>,
    args: &[CallArg],
    env: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    let receiver = eval(obj, env)?;
    let inst = match receiver {
        Value::Instance(i) => i,
        other => {
            return Err(RuntimeError::TypeError {
                message: format!(
                    "`super(...)` requires `self` (an instance receiver), but got a `{}` — use `self.super(...)` inside a constructor",
                    other.type_name()
                ),
                span,
            });
        }
    };
    let owner_class = super_owner_class(env).unwrap_or_else(|| inst.borrow().class.clone());
    let parent = owner_class
        .parent
        .clone()
        .ok_or_else(|| RuntimeError::TypeError {
            message: format!(
                "class `{}` has no parent to call `super` on",
                owner_class.name
            ),
            span: span.clone(),
        })?;
    let ctor = constructor_chain(&parent).ok_or_else(|| RuntimeError::TypeError {
        message: format!("parent class `{}` has no constructor", parent.name),
        span: span.clone(),
    })?;

    let vs = eval_super_args(args, env, &span)?;

    let scope = Environment::with_parent(ctor.closure.clone());
    scope
        .borrow_mut()
        .define("self".to_string(), Value::Instance(inst));
    scope.borrow_mut().define(
        SUPER_OWNER_BINDING.to_string(),
        Value::Class(parent.clone()),
    );
    bind_params(&scope, user_params(&ctor), &vs, &span)?;
    run_function_body(&ctor, &scope, span).map(|_| Value::Nil)
}

fn eval_super_args(
    args: &[CallArg],
    env: &Rc<RefCell<Environment>>,
    span: &std::ops::Range<usize>,
) -> Result<Vec<EvaluatedArg>, RuntimeError> {
    let mut out = Vec::with_capacity(args.len());
    for arg in args {
        match arg {
            CallArg::Positional(expr) => out.push(EvaluatedArg::Positional(eval(expr, env)?)),
            CallArg::Named { .. } => {
                return Err(RuntimeError::TypeError {
                    message: "named arguments are not supported in `super(...)`".to_string(),
                    span: span.clone(),
                });
            }
        }
    }
    Ok(out)
}

fn super_owner_class(env: &Rc<RefCell<Environment>>) -> Option<Rc<ClassObject>> {
    match env.borrow().get(SUPER_OWNER_BINDING) {
        Some(Value::Class(c)) => Some(c),
        _ => None,
    }
}

// ─── Class / instance helpers ───────────────────────────────────────────────

/// Read `receiver.name`.
///
/// On an instance:
///   1. instance fields,
///   2. class methods (returned as a `Function` — useful for `obj.method`
///      access, though most call sites use the `obj:method()` form),
///   3. class static fields (so `instance.maxHealth` still works the same
///      as `Class.maxHealth`).
///
/// On a class:
///   1. static fields,
///   2. static methods.
fn read_member(
    receiver: &Value,
    name: &str,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    match receiver {
        Value::Instance(inst) => {
            let inst_ref = inst.borrow();
            if let Some(v) = inst_ref.fields.get(name) {
                return Ok(v.clone());
            }
            if let Some(m) = inst_ref.class.lookup_method(name) {
                return Ok(Value::Function(m));
            }
            if let Some(v) = inst_ref.class.lookup_static_field(name) {
                return Ok(v);
            }
            if let Some(m) = inst_ref.class.lookup_static_method(name) {
                return Ok(Value::Function(m));
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no field or method `{name}` on instance of class `{}` — available fields: (check class definition)",
                    inst_ref.class.name
                ),
                span,
            })
        }
        Value::Class(class) => {
            if let Some(v) = class.lookup_static_field(name) {
                return Ok(v);
            }
            if let Some(m) = class.lookup_static_method(name) {
                return Ok(Value::Function(m));
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no static member `{name}` on class `{}` — try `{}:` method notation or check if this is an instance method",
                    class.name,
                    class.name
                ),
                span,
            })
        }
        Value::Enum(enum_obj) => {
            if let Some(variant) = enum_obj.variants.get(name) {
                return Ok(Value::EnumVariant(variant.clone()));
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no variant `{name}` on enum `{}` — check enum definition",
                    enum_obj.name
                ),
                span,
            })
        }
        Value::EnumVariant(variant) => {
            match name {
                "value" => {
                    Ok(variant
                        .value
                        .clone()
                        .unwrap_or(Value::Str(Rc::new(variant.variant_name.clone()))))
                }
                "name" => {
                    Ok(Value::Str(Rc::new(variant.variant_name.clone())))
                }
                _ => {
                    if let Some(enum_obj) = variant.enum_obj.borrow().as_ref() {
                        if let Some(m) = enum_obj.methods.get(name) {
                            return Ok(Value::Function(m.clone()));
                        }
                    }
                    Err(RuntimeError::TypeError {
                        message: format!(
                            "no property or method `{name}` on enum variant `{}.{}`",
                            variant.enum_name, variant.variant_name
                        ),
                        span,
                    })
                }
            }
        }
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot read field `{name}` on value of type `{}` — only instances, classes, and enums have members",
                other.type_name()
            ),
            span,
        }),
    }
}

/// Dispatch `receiver:name(args)`. For instances we prepend `self`; for
/// classes we call the static method as-is.
/// Dispatch `receiver:name(args)` (the colon-call form). Delegates to the
/// shared [`dispatch_member_call`] so the dot and colon forms behave the
/// same way at runtime.
fn invoke_method(
    receiver: &Value,
    name: &str,
    args: Vec<EvaluatedArg>,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    dispatch_member_call(receiver, name, args, span)
}

pub(crate) fn invoke_method_multi(
    receiver: &Value,
    name: &str,
    args: Vec<EvaluatedArg>,
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    dispatch_member_call_multi(receiver, name, args, span)
}

/// `new Class(args)` — create an instance, populate field defaults, then
/// run the constructor (if any) with `self` bound to the new object.
pub(crate) fn construct(
    class: Rc<ClassObject>,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    // Allocate the instance up-front so the constructor can stash it as
    // `self` and observe its own writes.
    let inst = Rc::new(RefCell::new(InstanceObject {
        class: class.clone(),
        fields: HashMap::new(),
    }));

    // Initialize instance fields from defaults (walking the inheritance
    // chain parent-first so the most-derived defaults win).
    init_fields(&class, &inst, &span)?;

    // Run the constructor — first declared on this class, otherwise the
    // nearest parent's. If none exists, fields stay at their defaults.
    if let Some(ctor) = constructor_chain(&class) {
        let scope = Environment::with_parent(ctor.closure.clone());
        inject_class_statics(&scope, &class);
        scope
            .borrow_mut()
            .define("self".to_string(), Value::Instance(inst.clone()));
        scope
            .borrow_mut()
            .define(SUPER_OWNER_BINDING.to_string(), Value::Class(class.clone()));
        // Skip a leading explicit `self` parameter if present (the
        // constructor / `init` body uses the auto-bound one).
        bind_params(&scope, user_params(&ctor), args, &span)?;
        run_function_body(&ctor, &scope, span)?;
    }

    Ok(Value::Instance(inst))
}

fn init_fields(
    class: &Rc<ClassObject>,
    inst: &Rc<RefCell<InstanceObject>>,
    span: &std::ops::Range<usize>,
) -> Result<(), RuntimeError> {
    if let Some(parent) = &class.parent {
        init_fields(parent, inst, span)?;
    }
    // Field-default expressions evaluate in the class's declaration scope.
    // We approximate by using the constructor's closure (every method on a
    // class shares that closure), falling back to a fresh prelude-less env
    // when none exists.
    let scope = if let Some(ctor) = &class.constructor {
        Environment::with_parent(ctor.closure.clone())
    } else if let Some(m) = class.methods.values().next() {
        Environment::with_parent(m.closure.clone())
    } else if let Some(m) = class.static_methods.values().next() {
        Environment::with_parent(m.closure.clone())
    } else {
        Environment::new()
    };
    // `self` is visible to default expressions too.
    scope
        .borrow_mut()
        .define("self".to_string(), Value::Instance(inst.clone()));

    for field in &class.field_defs {
        let value = match &field.default {
            Some(e) => eval(e, &scope)?,
            None => Value::Nil,
        };
        inst.borrow_mut().fields.insert(field.name.clone(), value);
    }
    Ok(())
}

fn constructor_chain(class: &Rc<ClassObject>) -> Option<Rc<FunctionObject>> {
    if let Some(c) = &class.constructor {
        return Some(c.clone());
    }
    class.parent.as_ref().and_then(constructor_chain)
}

//! Expression evaluation.

use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

use saule_ast::{BinOp, CallArg, Expr, LambdaBody, Spanned, Type};

use crate::env::Environment;
use crate::error::RuntimeError;
use crate::value::{ClassObject, FunctionBody, FunctionObject, InstanceObject, Value};

use super::{Flow, ops};

const SUPER_OWNER_BINDING: &str = "__saule_super_owner";

#[derive(Clone)]
pub(crate) enum EvaluatedArg {
    Positional(Value),
    Named { name: String, value: Value },
}

pub fn eval(expr: &Spanned<Expr>, env: &Rc<RefCell<Environment>>) -> Result<Value, RuntimeError> {
    let span = expr.span.clone();
    match &expr.value {
        Expr::Int(n) => Ok(Value::Int(*n)),
        Expr::Float(f) => Ok(Value::Float(*f)),
        Expr::Bool(b) => Ok(Value::Bool(*b)),
        Expr::Str(s) => Ok(Value::Str(Rc::new(s.clone()))),
        Expr::Nil => Ok(Value::Nil),

        Expr::Ident(name) => env
            .borrow()
            .get(name)
            .ok_or_else(|| RuntimeError::Undefined {
                name: name.clone(),
                span,
            }),

        Expr::Unary { op, rhs } => {
            let v = eval(rhs, env)?;
            ops::unary(*op, v, span)
        }

        Expr::Binary { op, lhs, rhs } => match op {
            // `and` / `or` short-circuit, so evaluate lazily.
            BinOp::And => {
                let l = eval(lhs, env)?;
                if l.is_truthy() { eval(rhs, env) } else { Ok(l) }
            }
            BinOp::Or => {
                let l = eval(lhs, env)?;
                if l.is_truthy() { Ok(l) } else { eval(rhs, env) }
            }
            // `??` short-circuits: only evaluate RHS when LHS is nil.
            BinOp::Coalesce => {
                let l = eval(lhs, env)?;
                if matches!(l, Value::Nil) { eval(rhs, env) } else { Ok(l) }
            }
            _ => {
                let l = eval(lhs, env)?;
                let r = eval(rhs, env)?;
                ops::binary(*op, l, r, span)
            }
        },

        Expr::Call { callee, args } => {
            // Dotted calls (`obj.method(args)`) and `self.super(args)` need
            // special handling so we can auto-bind `self` and route to the
            // parent constructor respectively. Saule lets instance methods
            // omit the explicit `self` parameter — see `call_instance_method`.
            if let Expr::Member { obj, name } = &callee.value {
                if name == "super" {
                    return super_call(obj, args, env, span);
                }
                let receiver = eval(obj, env)?;
                let vs = eval_call_args(args, env)?;
                return dispatch_member_call(&receiver, name, vs, span);
            }

            let cv = eval(callee, env)?;
            let vs = eval_call_args(args, env)?;
            call_value(cv, &vs, span)
        }

        // Postfix / composite forms — wait until later phases.
        Expr::Member { obj, name } => {
            let receiver = eval(obj, env)?;
            read_member(&receiver, name, span)
        }
        Expr::SafeMember { obj, name } => {
            let receiver = eval(obj, env)?;
            if matches!(receiver, Value::Nil) {
                Ok(Value::Nil)
            } else {
                read_member(&receiver, name, span)
            }
        }
        Expr::Index { obj, index } => {
            let receiver = eval(obj, env)?;
            let index_value = eval(index, env)?;
            read_index(&receiver, index_value, span)
        }
        Expr::MethodCall { obj, method, args } => {
            let receiver = eval(obj, env)?;
            let evaled = eval_call_args(args, env)?;
            invoke_method(&receiver, method, evaled, span)
        }
        Expr::ForceUnwrap(inner) => {
            let v = eval(inner, env)?;
            if matches!(v, Value::Nil) {
                Err(RuntimeError::ForceUnwrapNil { span })
            } else {
                Ok(v)
            }
        }
        Expr::Table(items) => {
            let mut values = Vec::with_capacity(items.len());
            for item in items {
                values.push(eval(item, env)?);
            }
            Ok(Value::Table(Rc::new(RefCell::new(
                crate::value::TableObject::from_array(values),
            ))))
        }

        Expr::Lambda { params, body, .. } => {
            let body = match body {
                LambdaBody::Expr(e) => FunctionBody::Expr(e.clone()),
                LambdaBody::Block(stmts) => FunctionBody::Block(stmts.clone()),
            };
            Ok(Value::Function(Rc::new(FunctionObject {
                name: None,
                params: params.clone(),
                body,
                closure: env.clone(),
            })))
        }

        Expr::Self_ => env
            .borrow()
            .get("self")
            .ok_or_else(|| RuntimeError::Undefined {
                name: "self".to_string(),
                span,
            }),
    }
}

fn first_or_nil(values: Vec<Value>) -> Value {
    values.into_iter().next().unwrap_or(Value::Nil)
}

pub(crate) fn eval_values(
    expr: &Spanned<Expr>,
    env: &Rc<RefCell<Environment>>,
) -> Result<Vec<Value>, RuntimeError> {
    let span = expr.span.clone();
    match &expr.value {
        Expr::Call { callee, args } => {
            if let Expr::Member { obj, name } = &callee.value {
                if name == "super" {
                    return Ok(vec![super_call(obj, args, env, span)?]);
                }
                let receiver = eval(obj, env)?;
                let vs = eval_call_args(args, env)?;
                return dispatch_member_call_multi(&receiver, name, vs, span);
            }

            let cv = eval(callee, env)?;
            let vs = eval_call_args(args, env)?;
            call_value_multi(cv, &vs, span)
        }
        Expr::MethodCall { obj, method, args } => {
            let receiver = eval(obj, env)?;
            let evaled = eval_call_args(args, env)?;
            invoke_method_multi(&receiver, method, evaled, span)
        }
        _ => Ok(vec![eval(expr, env)?]),
    }
}

/// Invoke a callable [`Value`]. Handles both native and user-defined
/// functions.
fn call_value(
    callee: Value,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(call_value_multi(callee, args, span)?))
}

pub(crate) fn call_value_multi(
    callee: Value,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    match callee {
        Value::Native(nf) => {
            let mut positional = Vec::with_capacity(args.len());
            for arg in args {
                match arg {
                    EvaluatedArg::Positional(v) => positional.push(v.clone()),
                    EvaluatedArg::Named { name: _, .. } => {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "named arguments are not supported for built-in function `{}` — use positional arguments instead",
                                nf.name
                            ),
                            span,
                        });
                    }
                }
            }
            (nf.func)(&positional)
                .map(|v| vec![v])
                .map_err(|message| RuntimeError::TypeError { message, span })
        }
        Value::Function(f) => call_function_multi(&f, args, span),
        Value::NativeClosure(nc) => {
            let mut positional = Vec::with_capacity(args.len());
            for arg in args {
                match arg {
                    EvaluatedArg::Positional(v) => positional.push(v.clone()),
                    EvaluatedArg::Named { name: _, .. } => {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "named arguments are not supported for built-in function `{}` — use positional arguments instead",
                                nc.name
                            ),
                            span,
                        });
                    }
                }
            }
            (nc.func)(&positional)
                .map_err(|message| RuntimeError::TypeError { message, span })
        }
        // `ClassName(args)` constructs an instance.
        Value::Class(c) => construct(c, args, span).map(|v| vec![v]),
        other => Err(RuntimeError::TypeError {
            message: format!(
                "value of type `{}` is not callable — only functions, classes, and methods can be called",
                other.type_name()
            ),
            span,
        }),
    }
}

/// Bind `params` into `scope` from `args`, evaluating defaults lazily. Used
/// by every kind of call (free function, instance method, static method,
/// constructor) so the rules stay in one place.
fn bind_params(
    scope: &Rc<RefCell<Environment>>,
    params: &[saule_ast::Param],
    args: &[EvaluatedArg],
    span: &std::ops::Range<usize>,
) -> Result<(), RuntimeError> {
    let variadic_indices: Vec<usize> = params
        .iter()
        .enumerate()
        .filter_map(|(i, p)| p.variadic.then_some(i))
        .collect();
    if variadic_indices.len() > 1 {
        return Err(RuntimeError::TypeError {
            message: "a function can declare at most one variadic parameter".to_string(),
            span: params[variadic_indices[1]].span.clone(),
        });
    }
    let variadic_idx = variadic_indices.first().copied();
    if let Some(idx) = variadic_idx
        && idx + 1 != params.len()
    {
        return Err(RuntimeError::TypeError {
            message: format!(
                "variadic parameter `{}` must be the last parameter in the list",
                params[idx].name
            ),
            span: params[idx].span.clone(),
        });
    }

    let mut assigned: Vec<Option<Value>> = vec![None; params.len()];
    let mut variadic_values: Vec<Value> = Vec::new();
    let mut next_positional = 0usize;
    let mut seen_named = false;
    let mut named_arg_count = 0usize;

    for arg in args {
        match arg {
            EvaluatedArg::Positional(value) => {
                if seen_named {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "positional argument #{} cannot follow named arguments; all positional arguments must come first",
                            next_positional + 1
                        ),
                        span: span.clone(),
                    });
                }
                if let Some(var_idx) = variadic_idx
                    && next_positional >= var_idx
                {
                    variadic_values.push(value.clone());
                    next_positional += 1;
                    continue;
                }
                if next_positional >= params.len() {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "too many arguments: expected {} but got at least {}",
                            params.len(),
                            next_positional + 1
                        ),
                        span: span.clone(),
                    });
                }
                assigned[next_positional] = Some(value.clone());
                next_positional += 1;
            }
            EvaluatedArg::Named { name, value } => {
                seen_named = true;
                named_arg_count += 1;
                let Some(idx) = params.iter().position(|p| p.name == *name) else {
                    let valid_params: Vec<String> = params.iter().map(|p| p.name.clone()).collect();
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "unknown named argument `{name}` (argument #{} of {}) — valid parameters: {}",
                            named_arg_count,
                            args.len(),
                            valid_params.join(", ")
                        ),
                        span: span.clone(),
                    });
                };
                if params[idx].variadic {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "variadic parameter `{name}` cannot be passed by name — provide any extra arguments positionally"
                        ),
                        span: span.clone(),
                    });
                }
                if assigned[idx].is_some() {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "duplicate argument for parameter `{name}` — this parameter was already provided"
                        ),
                        span: span.clone(),
                    });
                }
                assigned[idx] = Some(value.clone());
            }
        }
    }

    let missing_required: Vec<String> = params
        .iter()
        .enumerate()
        .filter_map(|(i, p)| {
            if assigned[i].is_none()
                && !p.variadic
                && p.default.is_none()
                && !is_nullable_type(&p.ty)
            {
                Some(p.name.clone())
            } else {
                None
            }
        })
        .collect();

    for (i, param) in params.iter().enumerate() {
        if param.variadic {
            scope.borrow_mut().define(
                param.name.clone(),
                Value::Table(Rc::new(RefCell::new(crate::value::TableObject::from_array(
                    variadic_values.clone(),
                )))),
            );
            continue;
        }
        let value = if let Some(v) = assigned[i].clone() {
            v
        } else if let Some(default) = &param.default {
            eval(default, scope)?
        } else if is_nullable_type(&param.ty) {
            Value::Nil
        } else {
            let help = if missing_required.len() == 1 {
                Some(format!(
                    "add argument `{}` to this call (positionally or by name)",
                    missing_required[0]
                ))
            } else {
                Some(format!(
                    "add required arguments to this call: {}",
                    missing_required
                        .iter()
                        .map(|n| format!("`{n}`"))
                        .collect::<Vec<_>>()
                        .join(", ")
                ))
            };
            return Err(RuntimeError::ArgumentError {
                message: if missing_required.len() == 1 {
                    format!("missing required argument for parameter `{}`", param.name)
                } else {
                    format!(
                        "missing {} required argument(s): {}",
                        missing_required.len(),
                        missing_required.join(", ")
                    )
                },
                help,
                span: span.clone(),
            });
        };
        scope.borrow_mut().define(param.name.clone(), value);
    }
    Ok(())
}

fn is_nullable_type(ty: &Type) -> bool {
    matches!(ty, Type::Nullable(_)) || matches!(ty, Type::Named(n) if n == "nil")
}

#[allow(dead_code)]
pub(crate) fn table_index_to_slot(index: &Value) -> Result<Option<usize>, String> {
    match index {
        Value::Int(i) if *i <= 0 => Ok(None),
        Value::Int(i) => Ok(Some((*i as usize) - 1)),
        other => Err(format!(
            "table indices must be integers, got `{}`",
            other.type_name()
        )),
    }
}

fn read_index(
    receiver: &Value,
    index: Value,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    match receiver {
        Value::Table(items) => Ok(items.borrow().get(&index)),
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot index a `{}` — only tables support `[index]` access",
                other.type_name()
            ),
            span,
        }),
    }
}

fn eval_call_args(
    args: &[CallArg],
    env: &Rc<RefCell<Environment>>,
) -> Result<Vec<EvaluatedArg>, RuntimeError> {
    let mut out = Vec::with_capacity(args.len());
    for arg in args {
        match arg {
            CallArg::Positional(expr) => out.push(EvaluatedArg::Positional(eval(expr, env)?)),
            CallArg::Named { name, value } => out.push(EvaluatedArg::Named {
                name: name.clone(),
                value: eval(value, env)?,
            }),
        }
    }
    Ok(out)
}

fn run_function_body(
    f: &FunctionObject,
    scope: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(run_function_body_multi(f, scope, span)?))
}

fn run_function_body_multi(
    f: &FunctionObject,
    scope: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    let outcome = match &f.body {
        FunctionBody::Block(stmts) => super::stmt::exec_block(stmts, scope)?,
        FunctionBody::Expr(e) => Flow::Return(vec![eval(e, scope)?]),
    };
    match outcome {
        Flow::Return(values) => Ok(values),
        Flow::Normal(_) => Ok(vec![Value::Nil]),
        Flow::Break => Err(RuntimeError::LoopControlOutsideLoop {
            which: "break",
            span,
        }),
        Flow::Continue => Err(RuntimeError::LoopControlOutsideLoop {
            which: "continue",
            span,
        }),
    }
}

/// Skip a leading `self` parameter (so explicit-self style still works
/// alongside the implicit-self style this language prefers).
fn user_params(f: &FunctionObject) -> &[saule_ast::Param] {
    if f.params.first().map(|p| p.name == "self").unwrap_or(false) {
        &f.params[1..]
    } else {
        &f.params
    }
}

/// Call a user-defined function: binds args (with defaults), executes the
/// body in a fresh scope parented to the function's closure, and converts
/// the resulting [`Flow`] into a return value.
pub(crate) fn call_function(
    f: &FunctionObject,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(call_function_multi(f, args, span)?))
}

fn call_function_multi(
    f: &FunctionObject,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    let scope = Environment::with_parent(f.closure.clone());
    bind_params(&scope, &f.params, args, &span)?;
    run_function_body_multi(f, &scope, span)
}

fn call_instance_method_multi(
    f: &FunctionObject,
    receiver: Value,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    let scope = Environment::with_parent(f.closure.clone());
    // Inject the class's static fields/methods so the method body can refer
    // to them by their bare names — see `inject_class_statics` for why.
    if let Value::Instance(inst) = &receiver {
        inject_class_statics(&scope, &inst.borrow().class);
    }
    scope.borrow_mut().define("self".to_string(), receiver);
    bind_params(&scope, user_params(f), args, &span)?;
    run_function_body_multi(f, &scope, span)
}

/// Invoke a static method with `self` bound to the class itself, which is
/// what makes `self.staticField` inside a `static fn` resolve to the right
/// thing (and is the only way `Main.main()` can reach `Main.lauris`).
fn call_static_method(
    f: &FunctionObject,
    class: &Rc<ClassObject>,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(call_static_method_multi(f, class, args, span)?))
}

fn call_static_method_multi(
    f: &FunctionObject,
    class: &Rc<ClassObject>,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    let scope = Environment::with_parent(f.closure.clone());
    inject_class_statics(&scope, class);
    scope
        .borrow_mut()
        .define("self".to_string(), Value::Class(class.clone()));
    bind_params(&scope, user_params(f), args, &span)?;
    run_function_body_multi(f, &scope, span)
}

/// Make the class's static fields and methods directly visible inside a
/// method body, so users can write `lauris.introduce()` instead of
/// `self.lauris.introduce()` or `Main.lauris.introduce()`. Parent statics
/// are seeded first and overridden by child statics, matching the lookup
/// order used for member access. Locals and parameters bound later still
/// shadow these, so the user can introduce a same-named local without
/// surprise.
fn inject_class_statics(scope: &Rc<RefCell<Environment>>, class: &Rc<ClassObject>) {
    // Collect the chain root-first so the most-derived class wins.
    let mut chain: Vec<Rc<ClassObject>> = Vec::new();
    let mut cur = Some(class.clone());
    while let Some(c) = cur {
        chain.push(c.clone());
        cur = c.parent.clone();
    }
    for c in chain.iter().rev() {
        for (n, v) in c.static_fields.borrow().iter() {
            scope.borrow_mut().define(n.clone(), v.clone());
        }
        for (n, f) in &c.static_methods {
            scope
                .borrow_mut()
                .define(n.clone(), Value::Function(f.clone()));
        }
    }
}

/// Public re-export of [`call_static_method`] for embedders. Kept as a thin
/// wrapper so the implementation details (param binding, `self` injection)
/// stay private to this module.
pub(crate) fn call_static_method_public(
    f: &FunctionObject,
    class: &Rc<ClassObject>,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    call_static_method(f, class, args, span)
}

/// Resolve `obj.name(args)` where the lookup intent is to *invoke* the
/// result. Instance methods get implicit `self`; static methods get the
/// class as `self`; non-function fields are simply invoked through
/// [`call_value`].
fn dispatch_member_call(
    receiver: &Value,
    name: &str,
    args: Vec<EvaluatedArg>,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    Ok(first_or_nil(dispatch_member_call_multi(receiver, name, args, span)?))
}

fn dispatch_member_call_multi(
    receiver: &Value,
    name: &str,
    args: Vec<EvaluatedArg>,
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    match receiver {
        Value::Instance(inst) => {
            let class = inst.borrow().class.clone();
            if let Some(m) = class.lookup_method(name) {
                return call_instance_method_multi(&m, receiver.clone(), &args, span);
            }
            if let Some(m) = class.lookup_static_method(name) {
                return call_static_method_multi(&m, &class, &args, span);
            }
            // Fall back: maybe the instance has a callable field.
            if let Some(v) = inst.borrow().fields.get(name).cloned() {
                return call_value_multi(v, &args, span);
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no method or field `{name}` on instance of class `{}` — instance members are case-sensitive",
                    class.name
                ),
                span,
            })
        }
        Value::Class(class) => {
            if let Some(m) = class.lookup_static_method(name) {
                return call_static_method_multi(&m, class, &args, span);
            }
            if let Some(v) = class.lookup_static_field(name) {
                return call_value_multi(v, &args, span);
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no static member `{name}` on class `{}` — check the class definition for the correct name",
                    class.name
                ),
                span,
            })
        }
        Value::EnumVariant(_variant) => {
            // Look up the method in the enum's method list, then call with
            // self bound to the variant.
            let v = read_member(receiver, name, span.clone())?;
            match v {
                Value::Function(m) => {
                    call_instance_method_multi(&m, receiver.clone(), &args, span)
                }
                _ => call_value_multi(v, &args, span),
            }
        }
        Value::File(handle) => {
            // File methods are implemented in `stdlib::io` via a static
            // method table — keep `Value::File` opaque to the rest of the
            // evaluator.
            let mut positional = Vec::with_capacity(args.len());
            for a in args {
                match a {
                    EvaluatedArg::Positional(v) => positional.push(v),
                    EvaluatedArg::Named { .. } => {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "named arguments are not supported on file methods (`{name}`) — use positional arguments instead"
                            ),
                            span,
                        });
                    }
                }
            }
            crate::stdlib::io::dispatch_file_method(handle, name, &positional)
                .map_err(|message| RuntimeError::TypeError { message, span })
        }
        _ => {
            // Generic: read the field, then call it.
            let v = read_member(receiver, name, span.clone())?;
            call_value_multi(v, &args, span)
        }
    }
}

/// `self.super(args)` — call the parent class's constructor on the current
/// instance. The receiver expression must evaluate to an instance whose
/// class has a parent.
fn super_call(
    obj: &Spanned<Expr>,
    args: &[CallArg],
    env: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    let receiver = eval(obj, env)?;
    let inst = match receiver {
        Value::Instance(i) => i,
        other => {
            return Err(RuntimeError::TypeError {
                message: format!(
                    "`super(...)` requires `self` (an instance receiver), but got a `{}` — use `self.super(...)` inside a constructor",
                    other.type_name()
                ),
                span,
            });
        }
    };
    let owner_class = super_owner_class(env).unwrap_or_else(|| inst.borrow().class.clone());
    let parent = owner_class
        .parent
        .clone()
        .ok_or_else(|| RuntimeError::TypeError {
            message: format!(
                "class `{}` has no parent to call `super` on",
                owner_class.name
            ),
            span: span.clone(),
        })?;
    let ctor = constructor_chain(&parent).ok_or_else(|| RuntimeError::TypeError {
        message: format!("parent class `{}` has no constructor", parent.name),
        span: span.clone(),
    })?;

    let vs = eval_super_args(args, env, &span)?;

    let scope = Environment::with_parent(ctor.closure.clone());
    scope
        .borrow_mut()
        .define("self".to_string(), Value::Instance(inst));
    scope.borrow_mut().define(
        SUPER_OWNER_BINDING.to_string(),
        Value::Class(parent.clone()),
    );
    bind_params(&scope, user_params(&ctor), &vs, &span)?;
    run_function_body(&ctor, &scope, span).map(|_| Value::Nil)
}

fn eval_super_args(
    args: &[CallArg],
    env: &Rc<RefCell<Environment>>,
    span: &std::ops::Range<usize>,
) -> Result<Vec<EvaluatedArg>, RuntimeError> {
    let mut out = Vec::with_capacity(args.len());
    for arg in args {
        match arg {
            CallArg::Positional(expr) => out.push(EvaluatedArg::Positional(eval(expr, env)?)),
            CallArg::Named { .. } => {
                return Err(RuntimeError::TypeError {
                    message: "named arguments are not supported in `super(...)`".to_string(),
                    span: span.clone(),
                });
            }
        }
    }
    Ok(out)
}

fn super_owner_class(env: &Rc<RefCell<Environment>>) -> Option<Rc<ClassObject>> {
    match env.borrow().get(SUPER_OWNER_BINDING) {
        Some(Value::Class(c)) => Some(c),
        _ => None,
    }
}

// ─── Class / instance helpers ───────────────────────────────────────────────

/// Read `receiver.name`.
///
/// On an instance:
///   1. instance fields,
///   2. class methods (returned as a `Function` — useful for `obj.method`
///      access, though most call sites use the `obj:method()` form),
///   3. class static fields (so `instance.maxHealth` still works the same
///      as `Class.maxHealth`).
///
/// On a class:
///   1. static fields,
///   2. static methods.
fn read_member(
    receiver: &Value,
    name: &str,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    match receiver {
        Value::Instance(inst) => {
            let inst_ref = inst.borrow();
            if let Some(v) = inst_ref.fields.get(name) {
                return Ok(v.clone());
            }
            if let Some(m) = inst_ref.class.lookup_method(name) {
                return Ok(Value::Function(m));
            }
            if let Some(v) = inst_ref.class.lookup_static_field(name) {
                return Ok(v);
            }
            if let Some(m) = inst_ref.class.lookup_static_method(name) {
                return Ok(Value::Function(m));
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no field or method `{name}` on instance of class `{}` — available fields: (check class definition)",
                    inst_ref.class.name
                ),
                span,
            })
        }
        Value::Class(class) => {
            if let Some(v) = class.lookup_static_field(name) {
                return Ok(v);
            }
            if let Some(m) = class.lookup_static_method(name) {
                return Ok(Value::Function(m));
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no static member `{name}` on class `{}` — try `{}:` method notation or check if this is an instance method",
                    class.name,
                    class.name
                ),
                span,
            })
        }
        Value::Enum(enum_obj) => {
            if let Some(variant) = enum_obj.variants.get(name) {
                return Ok(Value::EnumVariant(variant.clone()));
            }
            Err(RuntimeError::TypeError {
                message: format!(
                    "no variant `{name}` on enum `{}` — check enum definition",
                    enum_obj.name
                ),
                span,
            })
        }
        Value::EnumVariant(variant) => {
            match name {
                "value" => {
                    Ok(variant
                        .value
                        .clone()
                        .unwrap_or(Value::Str(Rc::new(variant.variant_name.clone()))))
                }
                "name" => {
                    Ok(Value::Str(Rc::new(variant.variant_name.clone())))
                }
                _ => {
                    if let Some(enum_obj) = variant.enum_obj.borrow().as_ref() {
                        if let Some(m) = enum_obj.methods.get(name) {
                            return Ok(Value::Function(m.clone()));
                        }
                    }
                    Err(RuntimeError::TypeError {
                        message: format!(
                            "no property or method `{name}` on enum variant `{}.{}`",
                            variant.enum_name, variant.variant_name
                        ),
                        span,
                    })
                }
            }
        }
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot read field `{name}` on value of type `{}` — only instances, classes, and enums have members",
                other.type_name()
            ),
            span,
        }),
    }
}

/// Dispatch `receiver:name(args)`. For instances we prepend `self`; for
/// classes we call the static method as-is.
/// Dispatch `receiver:name(args)` (the colon-call form). Delegates to the
/// shared [`dispatch_member_call`] so the dot and colon forms behave the
/// same way at runtime.
fn invoke_method(
    receiver: &Value,
    name: &str,
    args: Vec<EvaluatedArg>,
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    dispatch_member_call(receiver, name, args, span)
}

pub(crate) fn invoke_method_multi(
    receiver: &Value,
    name: &str,
    args: Vec<EvaluatedArg>,
    span: std::ops::Range<usize>,
) -> Result<Vec<Value>, RuntimeError> {
    dispatch_member_call_multi(receiver, name, args, span)
}

/// `new Class(args)` — create an instance, populate field defaults, then
/// run the constructor (if any) with `self` bound to the new object.
pub(crate) fn construct(
    class: Rc<ClassObject>,
    args: &[EvaluatedArg],
    span: std::ops::Range<usize>,
) -> Result<Value, RuntimeError> {
    // Allocate the instance up-front so the constructor can stash it as
    // `self` and observe its own writes.
    let inst = Rc::new(RefCell::new(InstanceObject {
        class: class.clone(),
        fields: HashMap::new(),
    }));

    // Initialize instance fields from defaults (walking the inheritance
    // chain parent-first so the most-derived defaults win).
    init_fields(&class, &inst, &span)?;

    // Run the constructor — first declared on this class, otherwise the
    // nearest parent's. If none exists, fields stay at their defaults.
    if let Some(ctor) = constructor_chain(&class) {
        let scope = Environment::with_parent(ctor.closure.clone());
        inject_class_statics(&scope, &class);
        scope
            .borrow_mut()
            .define("self".to_string(), Value::Instance(inst.clone()));
        scope
            .borrow_mut()
            .define(SUPER_OWNER_BINDING.to_string(), Value::Class(class.clone()));
        // Skip a leading explicit `self` parameter if present (the
        // constructor / `init` body uses the auto-bound one).
        bind_params(&scope, user_params(&ctor), args, &span)?;
        run_function_body(&ctor, &scope, span)?;
    }

    Ok(Value::Instance(inst))
}

fn init_fields(
    class: &Rc<ClassObject>,
    inst: &Rc<RefCell<InstanceObject>>,
    span: &std::ops::Range<usize>,
) -> Result<(), RuntimeError> {
    if let Some(parent) = &class.parent {
        init_fields(parent, inst, span)?;
    }
    // Field-default expressions evaluate in the class's declaration scope.
    // We approximate by using the constructor's closure (every method on a
    // class shares that closure), falling back to a fresh prelude-less env
    // when none exists.
    let scope = if let Some(ctor) = &class.constructor {
        Environment::with_parent(ctor.closure.clone())
    } else if let Some(m) = class.methods.values().next() {
        Environment::with_parent(m.closure.clone())
    } else if let Some(m) = class.static_methods.values().next() {
        Environment::with_parent(m.closure.clone())
    } else {
        Environment::new()
    };
    // `self` is visible to default expressions too.
    scope
        .borrow_mut()
        .define("self".to_string(), Value::Instance(inst.clone()));

    for field in &class.field_defs {
        let value = match &field.default {
            Some(e) => eval(e, &scope)?,
            None => Value::Nil,
        };
        inst.borrow_mut().fields.insert(field.name.clone(), value);
    }
    Ok(())
}

fn constructor_chain(class: &Rc<ClassObject>) -> Option<Rc<FunctionObject>> {
    if let Some(c) = &class.constructor {
        return Some(c.clone());
    }
    class.parent.as_ref().and_then(constructor_chain)
}

//! `Io` static class + `File` value type + `IoMode`/`IoSeek` enums.
//!
//! Design choices:
//!
//! * `Io` is a static class (like `Math` / `String` / `Table`) with statics
//!   `stdin` / `stdout` / `stderr` and methods `open` / `lines` / `read` /
//!   `write`.
//!
//! * File handles are first-class `Value::File` values. Their methods —
//!   `read` / `write` / `lines` / `seek` / `flush` / `close` — are dispatched
//!   by the evaluator via [`dispatch_file_method`] rather than living on a
//!   regular `ClassObject`. A phantom `File` class is still registered so the
//!   typechecker recognises `File` as a type name.
//!
//! * Mode and seek-whence are real Saule **enums** (`IoMode`, `IoSeek`),
//!   registered programmatically. Natives read the variant's `.value` string
//!   to drive the underlying `OpenOptions` / `SeekFrom`.

use std::cell::RefCell;
use std::collections::HashMap;
use std::fs::OpenOptions;
use std::io::{BufRead, BufReader, Read, Seek, SeekFrom, Write};
use std::rc::Rc;

use crate::env::Environment;
use crate::value::{
    ClassObject, EnumObject, EnumVariantObject, FieldDef, FileHandle, NativeClosure, Value,
};

// ─── installation ──────────────────────────────────────────────────────────

pub fn install(env: &Rc<RefCell<Environment>>) {
    install_enum(env, "IoMode", &[
        ("Read",         "r"),
        ("Write",        "w"),
        ("Append",       "a"),
        ("ReadWrite",    "r+"),
        ("WriteRead",    "w+"),
        ("AppendRead",   "a+"),
        ("ReadBinary",   "rb"),
        ("WriteBinary",  "wb"),
        ("AppendBinary", "ab"),
    ]);
    install_enum(env, "IoSeek", &[
        ("Set", "set"),
        ("Cur", "cur"),
        ("End", "end"),
    ]);

    // Phantom `File` class — only needed so the typechecker recognises
    // `File` as a type name in `local f: File = ...`. Method dispatch happens
    // in `dispatch_file_method`, not through this class.
    let file_class = ClassObject {
        name: "File".to_string(),
        parent: None,
        field_defs: Vec::<FieldDef>::new(),
        methods: HashMap::new(),
        static_fields: RefCell::new(HashMap::new()),
        static_methods: HashMap::new(),
        constructor: None,
    };
    env.borrow_mut()
        .define("File".to_string(), Value::Class(Rc::new(file_class)));

    // `Io` class — statics + native methods.
    let mut static_fields = HashMap::new();
    static_fields.insert(
        "stdin".to_string(),
        Value::File(Rc::new(RefCell::new(FileHandle::Stdin(BufReader::new(
            std::io::stdin(),
        ))))),
    );
    static_fields.insert(
        "stdout".to_string(),
        Value::File(Rc::new(RefCell::new(FileHandle::Stdout))),
    );
    static_fields.insert(
        "stderr".to_string(),
        Value::File(Rc::new(RefCell::new(FileHandle::Stderr))),
    );
    static_fields.insert("open".to_string(),  native_multi("Io.open",  io_open));
    static_fields.insert("lines".to_string(), native_multi("Io.lines", io_lines));
    static_fields.insert("read".to_string(),  native_multi("Io.read",  io_read));
    static_fields.insert("write".to_string(), native_multi("Io.write", io_write));

    let io_class = ClassObject {
        name: "Io".to_string(),
        parent: None,
        field_defs: Vec::new(),
        methods: HashMap::new(),
        static_fields: RefCell::new(static_fields),
        static_methods: HashMap::new(),
        constructor: None,
    };
    env.borrow_mut()
        .define("Io".to_string(), Value::Class(Rc::new(io_class)));
}

/// Register native signatures for the typechecker (lazy, via `sigs::lookup`).
pub fn register_sigs() {
    use crate::stdlib::sigs::{register, t_named, t_nullable};
    let s = || t_named("string");
    let i = || t_named("integer");
    let nil = || t_named("nil");
    let file_opt = || t_nullable(t_named("File"));
    let file = || t_named("File");
    let str_opt = || t_nullable(s());

    register("Io.open",  vec![s(), t_named("IoMode")], vec![file_opt()]);
    register("Io.lines", vec![t_nullable(s())],        vec![t_named("any")]);
    register("Io.read",  vec![s()],                    vec![str_opt()]);
    register("Io.write", vec![s()],                    vec![nil()]);

    // File method signatures — only consulted by typeck when it learns to
    // route `file.method(...)`. Pre-registering keeps the contract visible.
    register("File.read",  vec![s()],            vec![str_opt()]);
    register("File.write", vec![s()],            vec![nil()]);
    register("File.lines", vec![],               vec![t_named("any")]);
    register("File.seek",  vec![t_named("IoSeek"), i()], vec![i()]);
    register("File.flush", vec![],               vec![nil()]);
    register("File.close", vec![],               vec![nil()]);
    // Suppress unused warnings for the helpers we didn't reach for.
    let _ = file;
}

// ─── enum helper ───────────────────────────────────────────────────────────

fn install_enum(env: &Rc<RefCell<Environment>>, name: &str, variants: &[(&str, &str)]) {
    let mut variant_dict = HashMap::new();
    for (vname, vvalue) in variants {
        variant_dict.insert(
            (*vname).to_string(),
            Rc::new(EnumVariantObject {
                enum_name: name.to_string(),
                variant_name: (*vname).to_string(),
                value: Some(Value::Str(Rc::new((*vvalue).to_string()))),
                enum_obj: RefCell::new(None),
            }),
        );
    }
    let final_enum = Rc::new(EnumObject {
        name: name.to_string(),
        variants: variant_dict.clone(),
        methods: HashMap::new(),
    });
    for v in variant_dict.values() {
        *v.enum_obj.borrow_mut() = Some(final_enum.clone());
    }
    env.borrow_mut()
        .define(name.to_string(), Value::Enum(final_enum));
}

// ─── native helpers ────────────────────────────────────────────────────────

fn native_multi(
    name: &'static str,
    func: fn(&[Value]) -> Result<Vec<Value>, String>,
) -> Value {
    Value::NativeClosure(Rc::new(NativeClosure {
        name,
        func: Box::new(move |args| func(args)),
    }))
}

fn expect_string(name: &str, args: &[Value], idx: usize) -> Result<String, String> {
    match args.get(idx) {
        Some(Value::Str(s)) => Ok((**s).clone()),
        Some(other) => Err(format!(
            "{name} expects a string at argument {}, got `{}`",
            idx + 1,
            other.type_name()
        )),
        None => Err(format!("{name} missing argument {}", idx + 1)),
    }
}

/// Extract the underlying string value from an `IoMode` / `IoSeek` variant,
/// or accept a raw string (handy for tests and ad-hoc calls).
fn extract_enum_string(name: &str, args: &[Value], idx: usize) -> Result<String, String> {
    match args.get(idx) {
        Some(Value::EnumVariant(ev)) => match &ev.value {
            Some(Value::Str(s)) => Ok((**s).clone()),
            _ => Err(format!(
                "{name}: enum variant `{}.{}` has no string value",
                ev.enum_name, ev.variant_name
            )),
        },
        Some(Value::Str(s)) => Ok((**s).clone()),
        Some(other) => Err(format!(
            "{name} expects an enum variant or string at argument {}, got `{}`",
            idx + 1,
            other.type_name()
        )),
        None => Err(format!("{name} missing argument {}", idx + 1)),
    }
}

// ─── Io.open ─────────────────────────���─────────────────────────────────────

fn io_open(args: &[Value]) -> Result<Vec<Value>, String> {
    let path = expect_string("Io.open", args, 0)?;
    let mode = if args.len() >= 2 {
        extract_enum_string("Io.open", args, 1)?
    } else {
        "r".to_string()
    };

    let mut opts = OpenOptions::new();
    let (readable, writable) = match mode.as_str() {
        "r"  | "rb"            => { opts.read(true);                                      (true,  false) }
        "w"  | "wb"            => { opts.write(true).create(true).truncate(true);         (false, true ) }
        "a"  | "ab"            => { opts.append(true).create(true);                       (false, true ) }
        "r+" | "rb+" | "r+b"   => { opts.read(true).write(true);                          (true,  true ) }
        "w+" | "wb+" | "w+b"   => { opts.read(true).write(true).create(true).truncate(true); (true, true ) }
        "a+" | "ab+" | "a+b"   => { opts.read(true).append(true).create(true);            (true,  true ) }
        other => return Err(format!("Io.open: unknown mode `{other}`")),
    };

    match opts.open(&path) {
        Ok(file) => {
            let reader = if readable {
                let cloned = file.try_clone().map_err(|e| e.to_string())?;
                Some(BufReader::new(cloned))
            } else {
                None
            };
            let writer = if writable { Some(file) } else { None };
            Ok(vec![Value::File(Rc::new(RefCell::new(FileHandle::Open {
                path,
                reader,
                writer,
            })))])
        }
        // Lua semantics: failure returns nil (we drop the OS errno from the
        // tuple — `Result<File>` would be the richer alternative).
        Err(_) => Ok(vec![Value::Nil]),
    }
}

// ─── Io.lines ──────────────────────────────────────────────────────────────

fn io_lines(args: &[Value]) -> Result<Vec<Value>, String> {
    let path = match args.first() {
        Some(Value::Str(s)) => (**s).clone(),
        Some(Value::Nil) | None => {
            // No path → iterate stdin.
            let reader = Rc::new(RefCell::new(BufReader::new(std::io::stdin())));
            return Ok(vec![lines_step_stdin(reader)]);
        }
        Some(other) => {
            return Err(format!(
                "Io.lines expects a string path or nil, got `{}`",
                other.type_name()
            ));
        }
    };

    let file = std::fs::File::open(&path).map_err(|e| format!("Io.lines: {e}"))?;
    let reader = Rc::new(RefCell::new(BufReader::new(file)));
    Ok(vec![lines_step_file(reader)])
}

fn lines_step_file(reader: Rc<RefCell<BufReader<std::fs::File>>>) -> Value {
    Value::NativeClosure(Rc::new(NativeClosure {
        name: "Io.lines#step",
        func: Box::new(move |_| {
            let mut buf = String::new();
            let mut r = reader.borrow_mut();
            match r.read_line(&mut buf) {
                Ok(0) => Ok(vec![Value::Nil]),
                Ok(_) => {
                    strip_trailing_newline(&mut buf);
                    Ok(vec![Value::Str(Rc::new(buf))])
                }
                Err(e) => Err(format!("Io.lines: read error: {e}")),
            }
        }),
    }))
}

fn lines_step_stdin(reader: Rc<RefCell<BufReader<std::io::Stdin>>>) -> Value {
    Value::NativeClosure(Rc::new(NativeClosure {
        name: "Io.lines#stdin-step",
        func: Box::new(move |_| {
            let mut buf = String::new();
            let mut r = reader.borrow_mut();
            match r.read_line(&mut buf) {
                Ok(0) => Ok(vec![Value::Nil]),
                Ok(_) => {
                    strip_trailing_newline(&mut buf);
                    Ok(vec![Value::Str(Rc::new(buf))])
                }
                Err(e) => Err(format!("Io.lines: read error: {e}")),
            }
        }),
    }))
}

fn strip_trailing_newline(s: &mut String) {
    if s.ends_with('\n') {
        s.pop();
        if s.ends_with('\r') {
            s.pop();
        }
    }
}

// ─── Io.read / Io.write — operate on stdin / stdout ────────────────────────

fn io_read(args: &[Value]) -> Result<Vec<Value>, String> {
    let format = if args.is_empty() {
        "l".to_string()
    } else {
        expect_string("Io.read", args, 0)?
    };
    read_format(&format, &mut ReadSource::Stdin)
}

fn io_write(args: &[Value]) -> Result<Vec<Value>, String> {
    let mut out = std::io::stdout();
    for v in args {
        let _ = out.write_all(v.to_display_string().as_bytes());
    }
    let _ = out.flush();
    Ok(vec![Value::Nil])
}

// ─── shared read format ────────────────────────────────────────────────────

enum ReadSource<'a> {
    Stdin,
    BufFile(&'a mut BufReader<std::fs::File>),
    BufStdin(&'a mut BufReader<std::io::Stdin>),
}

fn read_format(fmt: &str, src: &mut ReadSource<'_>) -> Result<Vec<Value>, String> {
    // Lua-style format characters: "l" line w/o newline, "L" line w/ newline,
    // "a" everything, "n" integer (best-effort).
    let fmt = fmt.trim_start_matches('*');
    match fmt {
        "l" | "L" => {
            let mut buf = String::new();
            let bytes = read_line_src(src, &mut buf)?;
            if bytes == 0 {
                return Ok(vec![Value::Nil]);
            }
            if fmt == "l" {
                strip_trailing_newline(&mut buf);
            }
            Ok(vec![Value::Str(Rc::new(buf))])
        }
        "a" => {
            let mut buf = String::new();
            read_all_src(src, &mut buf)?;
            Ok(vec![Value::Str(Rc::new(buf))])
        }
        "n" => {
            let mut buf = String::new();
            let bytes = read_line_src(src, &mut buf)?;
            if bytes == 0 {
                return Ok(vec![Value::Nil]);
            }
            match buf.trim().parse::<i64>() {
                Ok(n) => Ok(vec![Value::Int(n)]),
                Err(_) => Ok(vec![Value::Nil]),
            }
        }
        other => Err(format!("Io.read: unsupported format `{other}`")),
    }
}

fn read_line_src(src: &mut ReadSource<'_>, buf: &mut String) -> Result<usize, String> {
    let r = match src {
        ReadSource::Stdin => {
            let stdin = std::io::stdin();
            return stdin
                .lock()
                .read_line(buf)
                .map_err(|e| e.to_string());
        }
        ReadSource::BufFile(r) => r.read_line(buf),
        ReadSource::BufStdin(r) => r.read_line(buf),
    };
    r.map_err(|e| e.to_string())
}

fn read_all_src(src: &mut ReadSource<'_>, buf: &mut String) -> Result<(), String> {
    match src {
        ReadSource::Stdin => {
            std::io::stdin().lock().read_to_string(buf).map_err(|e| e.to_string())?;
        }
        ReadSource::BufFile(r) => {
            r.read_to_string(buf).map_err(|e| e.to_string())?;
        }
        ReadSource::BufStdin(r) => {
            r.read_to_string(buf).map_err(|e| e.to_string())?;
        }
    }
    Ok(())
}

// ─── file method dispatch ──────────────────────────────────────────────────

/// Route `file.METHOD(args...)` calls. Called from `dispatch_member_call_multi`.
pub fn dispatch_file_method(
    handle: &Rc<RefCell<FileHandle>>,
    method: &str,
    args: &[&Value],
) -> Result<Vec<Value>, String> {
    let args: Vec<Value> = args.iter().map(|v| (*v).clone()).collect();
    match method {
        "read"  => file_read(handle, &args),
        "write" => file_write(handle, &args),
        "lines" => file_lines(handle, &args),
        "seek"  => file_seek(handle, &args),
        "flush" => file_flush(handle, &args),
        "close" => file_close(handle, &args),
        other   => Err(format!(
            "no method `{other}` on file — valid: read / write / lines / seek / flush / close"
        )),
    }
}

fn require_open<'a>(
    handle: &'a mut std::cell::RefMut<'_, FileHandle>,
) -> Result<&'a mut FileHandle, String> {
    if matches!(**handle, FileHandle::Closed) {
        return Err("file is closed".to_string());
    }
    Ok(&mut **handle)
}

fn file_read(handle: &Rc<RefCell<FileHandle>>, args: &[Value]) -> Result<Vec<Value>, String> {
    let format = if args.is_empty() {
        "l".to_string()
    } else {
        expect_string("File.read", args, 0)?
    };
    let mut h = handle.borrow_mut();
    let h = require_open(&mut h)?;
    match h {
        FileHandle::Open { reader: Some(r), .. } => {
            let mut src = ReadSource::BufFile(r);
            read_format(&format, &mut src)
        }
        FileHandle::Stdin(r) => {
            let mut src = ReadSource::BufStdin(r);
            read_format(&format, &mut src)
        }
        FileHandle::Open { reader: None, .. } => Err("file is not opened for reading".to_string()),
        FileHandle::Stdout | FileHandle::Stderr => {
            Err("cannot read from stdout/stderr".to_string())
        }
        FileHandle::Closed => unreachable!(),
    }
}

fn file_write(handle: &Rc<RefCell<FileHandle>>, args: &[Value]) -> Result<Vec<Value>, String> {
    let mut h = handle.borrow_mut();
    let h = require_open(&mut h)?;
    match h {
        FileHandle::Open { writer: Some(w), .. } => {
            for v in args {
                w.write_all(v.to_display_string().as_bytes())
                    .map_err(|e| e.to_string())?;
            }
            Ok(vec![Value::Nil])
        }
        FileHandle::Stdout => {
            let mut out = std::io::stdout();
            for v in args {
                let _ = out.write_all(v.to_display_string().as_bytes());
            }
            let _ = out.flush();
            Ok(vec![Value::Nil])
        }
        FileHandle::Stderr => {
            let mut err = std::io::stderr();
            for v in args {
                let _ = err.write_all(v.to_display_string().as_bytes());
            }
            let _ = err.flush();
            Ok(vec![Value::Nil])
        }
        FileHandle::Open { writer: None, .. } => {
            Err("file is not opened for writing".to_string())
        }
        FileHandle::Stdin(_) => Err("cannot write to stdin".to_string()),
        FileHandle::Closed => unreachable!(),
    }
}

fn file_lines(handle: &Rc<RefCell<FileHandle>>, _args: &[Value]) -> Result<Vec<Value>, String> {
    // Build a step closure that re-borrows the same handle each iteration.
    let h = handle.clone();
    Ok(vec![Value::NativeClosure(Rc::new(NativeClosure {
        name: "File.lines#step",
        func: Box::new(move |_| {
            let mut handle = h.borrow_mut();
            match &mut *handle {
                FileHandle::Open { reader: Some(r), .. } => {
                    let mut buf = String::new();
                    match r.read_line(&mut buf) {
                        Ok(0) => Ok(vec![Value::Nil]),
                        Ok(_) => {
                            strip_trailing_newline(&mut buf);
                            Ok(vec![Value::Str(Rc::new(buf))])
                        }
                        Err(e) => Err(format!("File.lines: {e}")),
                    }
                }
                FileHandle::Stdin(r) => {
                    let mut buf = String::new();
                    match r.read_line(&mut buf) {
                        Ok(0) => Ok(vec![Value::Nil]),
                        Ok(_) => {
                            strip_trailing_newline(&mut buf);
                            Ok(vec![Value::Str(Rc::new(buf))])
                        }
                        Err(e) => Err(format!("File.lines: {e}")),
                    }
                }
                FileHandle::Closed => Err("File.lines: file is closed".to_string()),
                _ => Err("File.lines: file is not readable".to_string()),
            }
        }),
    }))])
}

fn file_seek(handle: &Rc<RefCell<FileHandle>>, args: &[Value]) -> Result<Vec<Value>, String> {
    let whence = if args.is_empty() {
        "cur".to_string()
    } else {
        extract_enum_string("File.seek", args, 0)?
    };
    let offset = if args.len() >= 2 {
        match &args[1] {
            Value::Int(n) => *n,
            other => return Err(format!(
                "File.seek expects an integer offset, got `{}`",
                other.type_name()
            )),
        }
    } else { 0 };

    let from = match whence.as_str() {
        "set" => SeekFrom::Start(offset.max(0) as u64),
        "cur" => SeekFrom::Current(offset),
        "end" => SeekFrom::End(offset),
        other => return Err(format!("File.seek: invalid whence `{other}`")),
    };
    let mut h = handle.borrow_mut();
    let h = require_open(&mut h)?;
    match h {
        FileHandle::Open { reader, writer, .. } => {
            // Prefer seeking the writer if present (matches Lua's behaviour
            // on r+/w+/a+: the file shares the OS cursor).
            let pos = if let Some(w) = writer {
                w.seek(from).map_err(|e| e.to_string())?
            } else if let Some(r) = reader {
                // BufReader seeks its inner File, then reseeks its buffer.
                r.seek(from).map_err(|e| e.to_string())?
            } else {
                return Err("file has no seekable backing".to_string());
            };
            Ok(vec![Value::Int(pos as i64)])
        }
        _ => Err("File.seek: not supported on standard streams".to_string()),
    }
}

fn file_flush(handle: &Rc<RefCell<FileHandle>>, _args: &[Value]) -> Result<Vec<Value>, String> {
    let mut h = handle.borrow_mut();
    let h = require_open(&mut h)?;
    match h {
        FileHandle::Open { writer: Some(w), .. } => {
            w.flush().map_err(|e| e.to_string())?;
            Ok(vec![Value::Nil])
        }
        FileHandle::Stdout => { let _ = std::io::stdout().flush(); Ok(vec![Value::Nil]) }
        FileHandle::Stderr => { let _ = std::io::stderr().flush(); Ok(vec![Value::Nil]) }
        _ => Ok(vec![Value::Nil]),
    }
}

fn file_close(handle: &Rc<RefCell<FileHandle>>, _args: &[Value]) -> Result<Vec<Value>, String> {
    let mut h = handle.borrow_mut();
    // Standard streams are no-ops on close to match Lua.
    if matches!(*h, FileHandle::Stdout | FileHandle::Stderr | FileHandle::Stdin(_)) {
        return Ok(vec![Value::Nil]);
    }
    *h = FileHandle::Closed;
    Ok(vec![Value::Nil])
}

//! `Io` static class + `File` value type + `IoMode`/`IoSeek` enums.
//!
//! Design choices:
//!
//! * `Io` is a static class (like `Math` / `String` / `Table`) with statics
//!   `stdin` / `stdout` / `stderr` and methods `open` / `lines` / `read` /
//!   `write`.
//!
//! * File handles are first-class `Value::File` values. Their methods —
//!   `read` / `write` / `lines` / `seek` / `flush` / `close` — are dispatched
//!   by the evaluator via [`dispatch_file_method`] rather than living on a
//!   regular `ClassObject`. A phantom `File` class is still registered so the
//!   typechecker recognises `File` as a type name.
//!
//! * Mode and seek-whence are real Saule **enums** (`IoMode`, `IoSeek`),
//!   registered programmatically. Natives read the variant's `.value` string
//!   to drive the underlying `OpenOptions` / `SeekFrom`.

use std::cell::RefCell;
use std::collections::HashMap;
use std::fs::OpenOptions;
use std::io::{BufRead, BufReader, Read, Seek, SeekFrom, Write};
use std::rc::Rc;

use crate::env::Environment;
use crate::value::{
    ClassObject, EnumObject, EnumVariantObject, FieldDef, FileHandle, NativeClosure, Value,
};

// ─── installation ──────────────────────────────────────────────────────────

pub fn install(env: &Rc<RefCell<Environment>>) {
    install_enum(env, "IoMode", &[
        ("Read",         "r"),
        ("Write",        "w"),
        ("Append",       "a"),
        ("ReadWrite",    "r+"),
        ("WriteRead",    "w+"),
        ("AppendRead",   "a+"),
        ("ReadBinary",   "rb"),
        ("WriteBinary",  "wb"),
        ("AppendBinary", "ab"),
    ]);
    install_enum(env, "IoSeek", &[
        ("Set", "set"),
        ("Cur", "cur"),
        ("End", "end"),
    ]);

    // Phantom `File` class — only needed so the typechecker recognises
    // `File` as a type name in `local f: File = ...`. Method dispatch happens
    // in `dispatch_file_method`, not through this class.
    let file_class = ClassObject {
        name: "File".to_string(),
        parent: None,
        field_defs: Vec::<FieldDef>::new(),
        methods: HashMap::new(),
        static_fields: RefCell::new(HashMap::new()),
        static_methods: HashMap::new(),
        constructor: None,
    };
    env.borrow_mut()
        .define("File".to_string(), Value::Class(Rc::new(file_class)));

    // `Io` class — statics + native methods.
    let mut static_fields = HashMap::new();
    static_fields.insert(
        "stdin".to_string(),
        Value::File(Rc::new(RefCell::new(FileHandle::Stdin(BufReader::new(
            std::io::stdin(),
        ))))),
    );
    static_fields.insert(
        "stdout".to_string(),
        Value::File(Rc::new(RefCell::new(FileHandle::Stdout))),
    );
    static_fields.insert(
        "stderr".to_string(),
        Value::File(Rc::new(RefCell::new(FileHandle::Stderr))),
    );
    static_fields.insert("open".to_string(),  native_multi("Io.open",  io_open));
    static_fields.insert("lines".to_string(), native_multi("Io.lines", io_lines));
    static_fields.insert("read".to_string(),  native_multi("Io.read",  io_read));
    static_fields.insert("write".to_string(), native_multi("Io.write", io_write));

    let io_class = ClassObject {
        name: "Io".to_string(),
        parent: None,
        field_defs: Vec::new(),
        methods: HashMap::new(),
        static_fields: RefCell::new(static_fields),
        static_methods: HashMap::new(),
        constructor: None,
    };
    env.borrow_mut()
        .define("Io".to_string(), Value::Class(Rc::new(io_class)));
}

/// Register native signatures for the typechecker (lazy, via `sigs::lookup`).
pub fn register_sigs() {
    use crate::stdlib::sigs::{register, t_named, t_nullable};
    let s = || t_named("string");
    let i = || t_named("integer");
    let nil = || t_named("nil");
    let file_opt = || t_nullable(t_named("File"));
    let file = || t_named("File");
    let str_opt = || t_nullable(s());

    register("Io.open",  vec![s(), t_named("IoMode")], vec![file_opt()]);
    register("Io.lines", vec![t_nullable(s())],        vec![t_named("any")]);
    register("Io.read",  vec![s()],                    vec![str_opt()]);
    register("Io.write", vec![s()],                    vec![nil()]);

    // File method signatures — only consulted by typeck when it learns to
    // route `file.method(...)`. Pre-registering keeps the contract visible.
    register("File.read",  vec![s()],            vec![str_opt()]);
    register("File.write", vec![s()],            vec![nil()]);
    register("File.lines", vec![],               vec![t_named("any")]);
    register("File.seek",  vec![t_named("IoSeek"), i()], vec![i()]);
    register("File.flush", vec![],               vec![nil()]);
    register("File.close", vec![],               vec![nil()]);
    // Suppress unused warnings for the helpers we didn't reach for.
    let _ = file;
}

// ─── enum helper ───────────────────────────────────────────────────────────

fn install_enum(env: &Rc<RefCell<Environment>>, name: &str, variants: &[(&str, &str)]) {
    let mut variant_dict = HashMap::new();
    for (vname, vvalue) in variants {
        variant_dict.insert(
            (*vname).to_string(),
            Rc::new(EnumVariantObject {
                enum_name: name.to_string(),
                variant_name: (*vname).to_string(),
                value: Some(Value::Str(Rc::new((*vvalue).to_string()))),
                enum_obj: RefCell::new(None),
            }),
        );
    }
    let final_enum = Rc::new(EnumObject {
        name: name.to_string(),
        variants: variant_dict.clone(),
        methods: HashMap::new(),
    });
    for v in variant_dict.values() {
        *v.enum_obj.borrow_mut() = Some(final_enum.clone());
    }
    env.borrow_mut()
        .define(name.to_string(), Value::Enum(final_enum));
}

// ─── native helpers ────────────────────────────────────────────────────────

fn native_multi(
    name: &'static str,
    func: fn(&[Value]) -> Result<Vec<Value>, String>,
) -> Value {
    Value::NativeClosure(Rc::new(NativeClosure {
        name,
        func: Box::new(move |args| func(args)),
    }))
}

fn expect_string(name: &str, args: &[Value], idx: usize) -> Result<String, String> {
    match args.get(idx) {
        Some(Value::Str(s)) => Ok((**s).clone()),
        Some(other) => Err(format!(
            "{name} expects a string at argument {}, got `{}`",
            idx + 1,
            other.type_name()
        )),
        None => Err(format!("{name} missing argument {}", idx + 1)),
    }
}

/// Extract the underlying string value from an `IoMode` / `IoSeek` variant,
/// or accept a raw string (handy for tests and ad-hoc calls).
fn extract_enum_string(name: &str, args: &[Value], idx: usize) -> Result<String, String> {
    match args.get(idx) {
        Some(Value::EnumVariant(ev)) => match &ev.value {
            Some(Value::Str(s)) => Ok((**s).clone()),
            _ => Err(format!(
                "{name}: enum variant `{}.{}` has no string value",
                ev.enum_name, ev.variant_name
            )),
        },
        Some(Value::Str(s)) => Ok((**s).clone()),
        Some(other) => Err(format!(
            "{name} expects an enum variant or string at argument {}, got `{}`",
            idx + 1,
            other.type_name()
        )),
        None => Err(format!("{name} missing argument {}", idx + 1)),
    }
}

// ─── Io.open ─────────────────────────���─────────────────────────────────────

fn io_open(args: &[Value]) -> Result<Vec<Value>, String> {
    let path = expect_string("Io.open", args, 0)?;
    let mode = if args.len() >= 2 {
        extract_enum_string("Io.open", args, 1)?
    } else {
        "r".to_string()
    };

    let mut opts = OpenOptions::new();
    let (readable, writable) = match mode.as_str() {
        "r"  | "rb"            => { opts.read(true);                                      (true,  false) }
        "w"  | "wb"            => { opts.write(true).create(true).truncate(true);         (false, true ) }
        "a"  | "ab"            => { opts.append(true).create(true);                       (false, true ) }
        "r+" | "rb+" | "r+b"   => { opts.read(true).write(true);                          (true,  true ) }
        "w+" | "wb+" | "w+b"   => { opts.read(true).write(true).create(true).truncate(true); (true, true ) }
        "a+" | "ab+" | "a+b"   => { opts.read(true).append(true).create(true);            (true,  true ) }
        other => return Err(format!("Io.open: unknown mode `{other}`")),
    };

    match opts.open(&path) {
        Ok(file) => {
            let reader = if readable {
                let cloned = file.try_clone().map_err(|e| e.to_string())?;
                Some(BufReader::new(cloned))
            } else {
                None
            };
            let writer = if writable { Some(file) } else { None };
            Ok(vec![Value::File(Rc::new(RefCell::new(FileHandle::Open {
                path,
                reader,
                writer,
            })))])
        }
        // Lua semantics: failure returns nil (we drop the OS errno from the
        // tuple — `Result<File>` would be the richer alternative).
        Err(_) => Ok(vec![Value::Nil]),
    }
}

// ─── Io.lines ──────────────────────────────────────────────────────────────

fn io_lines(args: &[Value]) -> Result<Vec<Value>, String> {
    let path = match args.first() {
        Some(Value::Str(s)) => (**s).clone(),
        Some(Value::Nil) | None => {
            // No path → iterate stdin.
            let reader = Rc::new(RefCell::new(BufReader::new(std::io::stdin())));
            return Ok(vec![lines_step_stdin(reader)]);
        }
        Some(other) => {
            return Err(format!(
                "Io.lines expects a string path or nil, got `{}`",
                other.type_name()
            ));
        }
    };

    let file = std::fs::File::open(&path).map_err(|e| format!("Io.lines: {e}"))?;
    let reader = Rc::new(RefCell::new(BufReader::new(file)));
    Ok(vec![lines_step_file(reader)])
}

fn lines_step_file(reader: Rc<RefCell<BufReader<std::fs::File>>>) -> Value {
    Value::NativeClosure(Rc::new(NativeClosure {
        name: "Io.lines#step",
        func: Box::new(move |_| {
            let mut buf = String::new();
            let mut r = reader.borrow_mut();
            match r.read_line(&mut buf) {
                Ok(0) => Ok(vec![Value::Nil]),
                Ok(_) => {
                    strip_trailing_newline(&mut buf);
                    Ok(vec![Value::Str(Rc::new(buf))])
                }
                Err(e) => Err(format!("Io.lines: read error: {e}")),
            }
        }),
    }))
}

fn lines_step_stdin(reader: Rc<RefCell<BufReader<std::io::Stdin>>>) -> Value {
    Value::NativeClosure(Rc::new(NativeClosure {
        name: "Io.lines#stdin-step",
        func: Box::new(move |_| {
            let mut buf = String::new();
            let mut r = reader.borrow_mut();
            match r.read_line(&mut buf) {
                Ok(0) => Ok(vec![Value::Nil]),
                Ok(_) => {
                    strip_trailing_newline(&mut buf);
                    Ok(vec![Value::Str(Rc::new(buf))])
                }
                Err(e) => Err(format!("Io.lines: read error: {e}")),
            }
        }),
    }))
}

fn strip_trailing_newline(s: &mut String) {
    if s.ends_with('\n') {
        s.pop();
        if s.ends_with('\r') {
            s.pop();
        }
    }
}

// ─── Io.read / Io.write — operate on stdin / stdout ────────────────────────

fn io_read(args: &[Value]) -> Result<Vec<Value>, String> {
    let format = if args.is_empty() {
        "l".to_string()
    } else {
        expect_string("Io.read", args, 0)?
    };
    read_format(&format, &mut ReadSource::Stdin)
}

fn io_write(args: &[Value]) -> Result<Vec<Value>, String> {
    let mut out = std::io::stdout();
    for v in args {
        let _ = out.write_all(v.to_display_string().as_bytes());
    }
    let _ = out.flush();
    Ok(vec![Value::Nil])
}

// ─── shared read format ────────────────────────────────────────────────────

enum ReadSource<'a> {
    Stdin,
    BufFile(&'a mut BufReader<std::fs::File>),
    BufStdin(&'a mut BufReader<std::io::Stdin>),
}

fn read_format(fmt: &str, src: &mut ReadSource<'_>) -> Result<Vec<Value>, String> {
    // Lua-style format characters: "l" line w/o newline, "L" line w/ newline,
    // "a" everything, "n" integer (best-effort).
    let fmt = fmt.trim_start_matches('*');
    match fmt {
        "l" | "L" => {
            let mut buf = String::new();
            let bytes = read_line_src(src, &mut buf)?;
            if bytes == 0 {
                return Ok(vec![Value::Nil]);
            }
            if fmt == "l" {
                strip_trailing_newline(&mut buf);
            }
            Ok(vec![Value::Str(Rc::new(buf))])
        }
        "a" => {
            let mut buf = String::new();
            read_all_src(src, &mut buf)?;
            Ok(vec![Value::Str(Rc::new(buf))])
        }
        "n" => {
            let mut buf = String::new();
            let bytes = read_line_src(src, &mut buf)?;
            if bytes == 0 {
                return Ok(vec![Value::Nil]);
            }
            match buf.trim().parse::<i64>() {
                Ok(n) => Ok(vec![Value::Int(n)]),
                Err(_) => Ok(vec![Value::Nil]),
            }
        }
        other => Err(format!("Io.read: unsupported format `{other}`")),
    }
}

fn read_line_src(src: &mut ReadSource<'_>, buf: &mut String) -> Result<usize, String> {
    let r = match src {
        ReadSource::Stdin => {
            let stdin = std::io::stdin();
            return stdin
                .lock()
                .read_line(buf)
                .map_err(|e| e.to_string());
        }
        ReadSource::BufFile(r) => r.read_line(buf),
        ReadSource::BufStdin(r) => r.read_line(buf),
    };
    r.map_err(|e| e.to_string())
}

fn read_all_src(src: &mut ReadSource<'_>, buf: &mut String) -> Result<(), String> {
    match src {
        ReadSource::Stdin => {
            std::io::stdin().lock().read_to_string(buf).map_err(|e| e.to_string())?;
        }
        ReadSource::BufFile(r) => {
            r.read_to_string(buf).map_err(|e| e.to_string())?;
        }
        ReadSource::BufStdin(r) => {
            r.read_to_string(buf).map_err(|e| e.to_string())?;
        }
    }
    Ok(())
}

// ─── file method dispatch ──────────────────────────────────────────────────

/// Route `file.METHOD(args...)` calls. Called from `dispatch_member_call_multi`.
pub fn dispatch_file_method(
    handle: &Rc<RefCell<FileHandle>>,
    method: &str,
    args: &[Value],
) -> Result<Vec<Value>, String> {
    match method {
        "read"  => file_read(handle, args),
        "write" => file_write(handle, args),
        "lines" => file_lines(handle, args),
        "seek"  => file_seek(handle, args),
        "flush" => file_flush(handle, args),
        "close" => file_close(handle, args),
        other   => Err(format!(
            "no method `{other}` on file — valid: read / write / lines / seek / flush / close"
        )),
    }
}

fn require_open<'a>(
    handle: &'a mut std::cell::RefMut<'_, FileHandle>,
) -> Result<&'a mut FileHandle, String> {
    if matches!(**handle, FileHandle::Closed) {
        return Err("file is closed".to_string());
    }
    Ok(&mut **handle)
}

fn file_read(handle: &Rc<RefCell<FileHandle>>, args: &[Value]) -> Result<Vec<Value>, String> {
    let format = if args.is_empty() {
        "l".to_string()
    } else {
        expect_string("File.read", args, 0)?
    };
    let mut h = handle.borrow_mut();
    let h = require_open(&mut h)?;
    match h {
        FileHandle::Open { reader: Some(r), .. } => {
            let mut src = ReadSource::BufFile(r);
            read_format(&format, &mut src)
        }
        FileHandle::Stdin(r) => {
            let mut src = ReadSource::BufStdin(r);
            read_format(&format, &mut src)
        }
        FileHandle::Open { reader: None, .. } => Err("file is not opened for reading".to_string()),
        FileHandle::Stdout | FileHandle::Stderr => {
            Err("cannot read from stdout/stderr".to_string())
        }
        FileHandle::Closed => unreachable!(),
    }
}

fn file_write(handle: &Rc<RefCell<FileHandle>>, args: &[Value]) -> Result<Vec<Value>, String> {
    let mut h = handle.borrow_mut();
    let h = require_open(&mut h)?;
    match h {
        FileHandle::Open { writer: Some(w), .. } => {
            for v in args {
                w.write_all(v.to_display_string().as_bytes())
                    .map_err(|e| e.to_string())?;
            }
            Ok(vec![Value::Nil])
        }
        FileHandle::Stdout => {
            let mut out = std::io::stdout();
            for v in args {
                let _ = out.write_all(v.to_display_string().as_bytes());
            }
            let _ = out.flush();
            Ok(vec![Value::Nil])
        }
        FileHandle::Stderr => {
            let mut err = std::io::stderr();
            for v in args {
                let _ = err.write_all(v.to_display_string().as_bytes());
            }
            let _ = err.flush();
            Ok(vec![Value::Nil])
        }
        FileHandle::Open { writer: None, .. } => {
            Err("file is not opened for writing".to_string())
        }
        FileHandle::Stdin(_) => Err("cannot write to stdin".to_string()),
        FileHandle::Closed => unreachable!(),
    }
}

fn file_lines(handle: &Rc<RefCell<FileHandle>>, _args: &[Value]) -> Result<Vec<Value>, String> {
    // Build a step closure that re-borrows the same handle each iteration.
    let h = handle.clone();
    Ok(vec![Value::NativeClosure(Rc::new(NativeClosure {
        name: "File.lines#step",
        func: Box::new(move |_| {
            let mut handle = h.borrow_mut();
            match &mut *handle {
                FileHandle::Open { reader: Some(r), .. } => {
                    let mut buf = String::new();
                    match r.read_line(&mut buf) {
                        Ok(0) => Ok(vec![Value::Nil]),
                        Ok(_) => {
                            strip_trailing_newline(&mut buf);
                            Ok(vec![Value::Str(Rc::new(buf))])
                        }
                        Err(e) => Err(format!("File.lines: {e}")),
                    }
                }
                FileHandle::Stdin(r) => {
                    let mut buf = String::new();
                    match r.read_line(&mut buf) {
                        Ok(0) => Ok(vec![Value::Nil]),
                        Ok(_) => {
                            strip_trailing_newline(&mut buf);
                            Ok(vec![Value::Str(Rc::new(buf))])
                        }
                        Err(e) => Err(format!("File.lines: {e}")),
                    }
                }
                FileHandle::Closed => Err("File.lines: file is closed".to_string()),
                _ => Err("File.lines: file is not readable".to_string()),
            }
        }),
    }))])
}

fn file_seek(handle: &Rc<RefCell<FileHandle>>, args: &[Value]) -> Result<Vec<Value>, String> {
    let whence = if args.is_empty() {
        "cur".to_string()
    } else {
        extract_enum_string("File.seek", args, 0)?
    };
    let offset = if args.len() >= 2 {
        match &args[1] {
            Value::Int(n) => *n,
            other => return Err(format!(
                "File.seek expects an integer offset, got `{}`",
                other.type_name()
            )),
        }
    } else { 0 };

    let from = match whence.as_str() {
        "set" => SeekFrom::Start(offset.max(0) as u64),
        "cur" => SeekFrom::Current(offset),
        "end" => SeekFrom::End(offset),
        other => return Err(format!("File.seek: invalid whence `{other}`")),
    };
    let mut h = handle.borrow_mut();
    let h = require_open(&mut h)?;
    match h {
        FileHandle::Open { reader, writer, .. } => {
            // Prefer seeking the writer if present (matches Lua's behaviour
            // on r+/w+/a+: the file shares the OS cursor).
            let pos = if let Some(w) = writer {
                w.seek(from).map_err(|e| e.to_string())?
            } else if let Some(r) = reader {
                // BufReader seeks its inner File, then reseeks its buffer.
                r.seek(from).map_err(|e| e.to_string())?
            } else {
                return Err("file has no seekable backing".to_string());
            };
            Ok(vec![Value::Int(pos as i64)])
        }
        _ => Err("File.seek: not supported on standard streams".to_string()),
    }
}

fn file_flush(handle: &Rc<RefCell<FileHandle>>, _args: &[Value]) -> Result<Vec<Value>, String> {
    let mut h = handle.borrow_mut();
    let h = require_open(&mut h)?;
    match h {
        FileHandle::Open { writer: Some(w), .. } => {
            w.flush().map_err(|e| e.to_string())?;
            Ok(vec![Value::Nil])
        }
        FileHandle::Stdout => { let _ = std::io::stdout().flush(); Ok(vec![Value::Nil]) }
        FileHandle::Stderr => { let _ = std::io::stderr().flush(); Ok(vec![Value::Nil]) }
        _ => Ok(vec![Value::Nil]),
    }
}

fn file_close(handle: &Rc<RefCell<FileHandle>>, _args: &[Value]) -> Result<Vec<Value>, String> {
    let mut h = handle.borrow_mut();
    // Standard streams are no-ops on close to match Lua.
    if matches!(*h, FileHandle::Stdout | FileHandle::Stderr | FileHandle::Stdin(_)) {
        return Ok(vec![Value::Nil]);
    }
    *h = FileHandle::Closed;
    Ok(vec![Value::Nil])
}

//! Tree-walking interpreter for the Saule language.
//!
//! Module layout:
//!
//! | Module       | Responsibility                              |
//! |--------------|---------------------------------------------|
//! | [`value`]    | Runtime [`Value`] enum and `NativeFn`       |
//! | [`env`]      | Lexical scopes ([`Environment`])            |
//! | [`builtins`] | Standard library installed into the prelude |
//! | [`error`]    | [`RuntimeError`] (miette-aware diagnostics) |
//! | [`eval`]     | Statement & expression evaluation           |
//!
//! Phase status:
//!   * Phase 1 — literals, locals, arithmetic, native calls (✓)
//!   * Phase 2 — assignment, blocks, `if`/`while`/`repeat`/numeric `for`,
//!     `break`/`continue`, lexical scoping (✓)
//!   * Phase 3 — user-defined functions, lambdas, closures, `return` (✓ —
//!     this commit)
//!   * Phase 4 — tables and indexing (next)

use std::cell::RefCell;
use std::rc::Rc;

use saule_ast::Module;

pub mod builtins;
pub mod env;
pub mod error;
pub mod eval;
pub mod typeck;
pub mod value;

pub use env::Environment;
pub use error::RuntimeError;
pub use eval::Flow;
pub use value::{NativeFn, Value};

/// Invoke a [`value::FunctionObject`] with the given arguments. Exposed so
/// embedders (the CLI, the REPL, future test runners) can call functions
/// that were defined in user code without re-parsing.
pub fn call_function_value(
    f: &std::rc::Rc<value::FunctionObject>,
    args: &[Value],
) -> Result<Value, RuntimeError> {
    let evaled: Vec<eval::expr::EvaluatedArg> = args
        .iter()
        .cloned()
        .map(eval::expr::EvaluatedArg::Positional)
        .collect();
    eval::expr::call_function(f, &evaled, 0..0)
}

/// Invoke a static method on a class, with `self` bound to the class — the
/// CLI uses this to run `Main.main()`.
pub fn call_class_static_method(
    class: &std::rc::Rc<value::ClassObject>,
    method: &str,
    args: &[Value],
) -> Result<Value, RuntimeError> {
    let f = class.lookup_static_method(method).ok_or_else(|| {
        RuntimeError::TypeError {
            message: format!("no static method `{method}` on class `{}`", class.name),
            span: 0..0,
        }
    })?;
    let evaled: Vec<eval::expr::EvaluatedArg> = args
        .iter()
        .cloned()
        .map(eval::expr::EvaluatedArg::Positional)
        .collect();
    eval::expr::call_static_method_public(&f, class, &evaled, 0..0)
}

/// Run a parsed [`Module`] in a fresh environment seeded with built-ins.
///
/// Returns the value of the last evaluated expression-statement (useful for
/// the REPL and for tests).
pub fn run(module: &Module) -> Result<Value, RuntimeError> {
    let env = Environment::with_prelude();
    run_in(module, &env)
}

/// Run a [`Module`] inside a caller-supplied environment.
pub fn run_in(module: &Module, env: &Rc<RefCell<Environment>>) -> Result<Value, RuntimeError> {
    match eval::stmt::exec_block(&module.stmts, env)? {
        Flow::Normal(v) => Ok(v),
        // At the top level these are illegal — `Stmt::Return` is rejected
        // inside `exec`; `break`/`continue` reach here only if they appear
        // outside any loop.
        Flow::Break => Err(RuntimeError::LoopControlOutsideLoop {
            which: "break",
            span: 0..0,
        }),
        Flow::Continue => Err(RuntimeError::LoopControlOutsideLoop {
            which: "continue",
            span: 0..0,
        }),
        Flow::Return(v) => Ok(v),
    }
}

// ─── Tests ───────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;
    use saule_lexer::Lexer;
    use saule_parser::parse;
    use std::rc::Rc;

    fn eval(src: &str) -> Result<Value, RuntimeError> {
        let toks = Lexer::new(src).tokenize().expect("lex");
        let module = parse(toks).expect("parse");
        run(&module)
    }

    // ── Phase 1 regression coverage ──────────────────────────────────────────

    #[test]
    fn integer_arithmetic() {
        assert_eq!(eval("1 + 2 * 3").unwrap(), Value::Int(7));
    }

    #[test]
    fn float_arithmetic() {
        match eval("1.5 + 2.5").unwrap() {
            Value::Float(f) => assert_eq!(f, 4.0),
            v => panic!("expected float, got {v:?}"),
        }
    }

    #[test]
    fn mixing_int_and_float_errors() {
        assert!(matches!(
            eval("1 + 2.0").unwrap_err(),
            RuntimeError::NumericMix { .. }
        ));
    }

    #[test]
    fn local_then_lookup() {
        assert_eq!(
            eval("local x: integer = 10\nx * 2").unwrap(),
            Value::Int(20)
        );
    }

    #[test]
    fn string_concat_and_length() {
        assert_eq!(
            eval(r#""foo" .. "bar""#).unwrap(),
            Value::Str(Rc::new("foobar".into()))
        );
        assert_eq!(eval(r#"#"hello""#).unwrap(), Value::Int(5));
    }

    #[test]
    fn comparison_and_logic() {
        assert_eq!(eval("1 < 2 and 3 >= 3").unwrap(), Value::Bool(true));
        assert_eq!(
            eval(r#"nil or "fallback""#).unwrap(),
            Value::Str(Rc::new("fallback".into()))
        );
    }

    #[test]
    fn null_coalescing() {
        assert_eq!(
            eval(r#"nil ?? "x""#).unwrap(),
            Value::Str(Rc::new("x".into()))
        );
        assert_eq!(
            eval(r#""y" ?? "x""#).unwrap(),
            Value::Str(Rc::new("y".into()))
        );
    }

    #[test]
    fn print_native_call() {
        assert_eq!(eval(r#"print("hello", 1, true)"#).unwrap(), Value::Nil);
    }

    #[test]
    fn undefined_variable_errors() {
        assert!(matches!(
            eval("nope").unwrap_err(),
            RuntimeError::Undefined { .. }
        ));
    }

    #[test]
    fn division_by_zero() {
        assert!(matches!(
            eval("1 / 0").unwrap_err(),
            RuntimeError::DivisionByZero { .. }
        ));
    }

    #[test]
    fn type_builtin() {
        assert_eq!(eval("type(42)").unwrap(), Value::Str(Rc::new("integer".into())));
        assert_eq!(eval(r#"type("hi")"#).unwrap(), Value::Str(Rc::new("string".into())));
    }

