    #[test]
    fn if_then_branch() {
        let src = r#"
            local x: integer = 0
            if true then
              x = 1
            else
              x = 2
            end
            x
        "#;
        assert_eq!(eval(src).unwrap(), Value::Int(1));
    }

    #[test]
    fn if_elseif_else_chain() {
        let src = r#"
            local n: integer = 7
            local kind: string = ""
            if n < 0 then
              kind = "neg"
            else if n == 0 then
              kind = "zero"
            else if n < 10 then
              kind = "small"
            else
              kind = "big"
            end
            kind
        "#;
        assert_eq!(eval(src).unwrap(), Value::Str(Rc::new("small".into())));
    }

    #[test]
    fn if_body_introduces_scope() {
        // `tmp` is declared inside the `if` body and must NOT leak out.
        let src = r#"
            local x: integer = 0
            if true then
              local tmp: integer = 9
              x = tmp
            end
            tmp
        "#;
        assert!(matches!(
            eval(src).unwrap_err(),
            RuntimeError::Undefined { .. }
        ));
    }

    // ── Phase 2: while + break + continue ────────────────────────────────────

    #[test]
    fn while_counts_to_ten() {
        let src = r#"
            local i: integer = 0
            local sum: integer = 0
            while i < 10 do
              i = i + 1
              sum = sum + i
            end
            return sum
        "#;
        assert_eq!(eval(src).unwrap(), Value::Int(55));
    }

    #[test]
    fn break_exits_loop_early() {
        let src = r#"
            local i: integer = 0
            while true do
              i = i + 1
              if i == 5 then
                break
              end
            end
            return i
        "#;
        assert_eq!(eval(src).unwrap(), Value::Int(5));
    }

    #[test]
    fn continue_skips_rest_of_iteration() {
        // Sum of odd numbers 1..=9 = 25.
        let src = r#"
            local i: integer = 0
            local sum: integer = 0
            while i < 10 do
              i = i + 1
              if i % 2 == 0 then
                continue
              end
              sum = sum + i
            end
            return sum
        "#;
        assert_eq!(eval(src).unwrap(), Value::Int(25));
    }

