fn math_round(args: &[Value]) -> Result<Value, String> {
    expect_arity("round", args, 1)?;
    match number_at(args, 0, "round")? {
        Number::Int(n) => Ok(Value::Int(n)),
        Number::Float(f) => Ok(Value::Int(f.round() as i64)),
