fn math_sqrt(args: &[Value]) -> Result<Value, String> {
    expect_arity("sqrt", args, 1)?;
    let x = number_at(args, 0, "sqrt")?.as_f64();
    if x < 0.0 {
        return Err("sqrt expects a non-negative number".to_string());
    }
    Ok(Value::Float(x.sqrt()))
}

fn math_random(args: &[Value]) -> Result<Value, String> {
    match args.len() {
        0 => Ok(Value::Float(random_unit())),
        1 => {
            let n = number_at(args, 0, "random")?;
            let hi = match n {
                Number::Int(i) => i,
                Number::Float(f) => {
                    if f.fract() != 0.0 {
                        return Err("random upper bound must be an integer".to_string());
                    }
                    f as i64
                }
            };
            if hi < 1 {
                return Err("random upper bound must be >= 1".to_string());
            }
            let span = hi as u64;
            Ok(Value::Int((next_u64() % span) as i64 + 1))
        }
        2 => {
            let lo = to_i64(number_at(args, 0, "random")?, "random lower bound")?;
            let hi = to_i64(number_at(args, 1, "random")?, "random upper bound")?;
            if lo > hi {
                return Err("random expects lower bound <= upper bound".to_string());
            }
            let span = (hi as i128 - lo as i128 + 1) as u128;
            let v = (next_u64() as u128) % span;
            Ok(Value::Int(lo + v as i64))
        }
        _ => Err(format!("random expects 0, 1, or 2 arguments, got {}", args.len())),
    }
}

fn math_randomseed(args: &[Value]) -> Result<Value, String> {
    expect_arity("randomseed", args, 1)?;
    let seed = match number_at(args, 0, "randomseed")? {
        Number::Int(i) => i as u64,
        Number::Float(f) => f.to_bits(),
    };
    RNG_STATE.with(|cell| *cell.borrow_mut() = if seed == 0 { 1 } else { seed });
    Ok(Value::Nil)
}

fn math_tointeger(args: &[Value]) -> Result<Value, String> {
    expect_arity("tointeger", args, 1)?;
    let out = match &args[0] {
        Value::Int(i) => Some(*i),
        Value::Float(f) => {
            if f.is_finite() && f.fract() == 0.0 && *f >= i64::MIN as f64 && *f <= i64::MAX as f64
            {
                Some(*f as i64)
            } else {
                None
            }
        }
        _ => None,
    };
    Ok(out.map(Value::Int).unwrap_or(Value::Nil))
}

fn math_type(args: &[Value]) -> Result<Value, String> {
    expect_arity("type", args, 1)?;
    match args[0] {
        Value::Int(_) => Ok(Value::Str(Rc::new("integer".to_string()))),
        Value::Float(_) => Ok(Value::Str(Rc::new("float".to_string()))),
        _ => Ok(Value::Nil),
    }
}

fn math_ult(args: &[Value]) -> Result<Value, String> {
    expect_arity("ult", args, 2)?;
    let a = to_i64(number_at(args, 0, "ult")?, "ult arg #1")? as u64;
    let b = to_i64(number_at(args, 1, "ult")?, "ult arg #2")? as u64;
    Ok(Value::Bool(a < b))
}

fn math_pow(args: &[Value]) -> Result<Value, String> {
    expect_arity("pow", args, 2)?;
    let base = number_at(args, 0, "pow")?.as_f64();
    let exp = number_at(args, 1, "pow")?.as_f64();
    Ok(Value::Float(base.powf(exp)))
}

fn math_clamp(args: &[Value]) -> Result<Value, String> {
    expect_arity("clamp", args, 3)?;
    let value = number_at(args, 0, "clamp")?.as_f64();
    let min = number_at(args, 1, "clamp")?.as_f64();
    let max = number_at(args, 2, "clamp")?.as_f64();
    if min > max {
        return Err("clamp expects min <= max".to_string());
    }
    Ok(Value::Float(value.clamp(min, max)))
}

fn math_sign(args: &[Value]) -> Result<Value, String> {
    expect_arity("sign", args, 1)?;
    let x = number_at(args, 0, "sign")?.as_f64();
    let out = if x > 0.0 {
        1
    } else if x < 0.0 {
        -1
    } else {
        0
    };
    Ok(Value::Int(out))
}

fn to_i64(n: Number, label: &str) -> Result<i64, String> {
    match n {
        Number::Int(i) => Ok(i),
        Number::Float(f) => {
            if f.fract() != 0.0 || !f.is_finite() || f < i64::MIN as f64 || f > i64::MAX as f64 {
                Err(format!("{label} must be an integer"))
            } else {
                Ok(f as i64)
            }
        }
    }
}

//! Static signatures for native (Rust-implemented) functions.
//!
//! The runtime's `NativeFn` / `NativeClosure` values carry only a `name` and
//! a callable — no type information. The typechecker can't inspect a Rust
//! closure, so we maintain a side-table mapping qualified names like
//! `"String.byte"` or bare names like `"assert"` to their declared signatures.
//!
//! Each `stdlib::*::install` function registers the signatures of the natives
//! it defines. The typechecker (`typeck::infer`) consults `lookup` for
//! `Expr::Call` where the callee resolves to a bare ident or a `Class.method`
//! pair, so writing `local n: integer = String.byte("a")` produces the same
//! `NullableToNonNullable` diagnostic as a user-defined function returning
//! `integer?`.

use std::cell::RefCell;
use std::collections::HashMap;
use std::sync::Once;

use saule_ast::Type;

/// A native function's static signature.
#[derive(Clone, Debug)]
pub struct NativeSig {
    /// Declared parameter types (currently unused by the checker; reserved).
    pub params: Vec<Type>,
    /// Declared return types. `len() == 1` for single-return functions;
    /// `len() > 1` for multi-return (surfaced as `Type::Tuple` to callers).
    pub returns: Vec<Type>,
}

thread_local! {
    static SIGS: RefCell<HashMap<String, NativeSig>> = RefCell::new(HashMap::new());
}

/// Register `name -> sig`. Overwrites silently — `install_std` is idempotent
/// per process.
pub fn register(name: &str, params: Vec<Type>, returns: Vec<Type>) {
    SIGS.with(|s| {
        s.borrow_mut().insert(
            name.to_string(),
            NativeSig { params, returns },
        );
    });
}

/// Look up by qualified (`"String.byte"`) or bare (`"assert"`) name.
pub fn lookup(name: &str) -> Option<NativeSig> {
    SIGS.with(|s| s.borrow().get(name).cloned())
}

// ─── Type-builder shorthands for callers ────────────────────────────────────

pub fn t_named(s: &str) -> Type {
    Type::Named(s.to_string())
}

pub fn t_nullable(inner: Type) -> Type {
    Type::Nullable(Box::new(inner))
}

pub fn t_table(value: Type) -> Type {
    Type::Table { key: None, value: Box::new(value) }
}

pub fn t_table_map(key: Type, value: Type) -> Type {
    Type::Table { key: Some(Box::new(key)), value: Box::new(value) }
}

pub fn t_function(params: Vec<Type>, ret: Type) -> Type {
    Type::Function { params, ret: Box::new(ret) }
}

//! Static signatures for native (Rust-implemented) functions.
//!
//! The runtime's `NativeFn` / `NativeClosure` values carry only a `name` and
//! a callable — no type information. The typechecker can't inspect a Rust
//! closure, so we maintain a side-table mapping qualified names like
//! `"String.byte"` or bare names like `"assert"` to their declared signatures.
//!
//! Each `stdlib::*::install` function registers the signatures of the natives
//! it defines. The typechecker (`typeck::infer`) consults `lookup` for
//! `Expr::Call` where the callee resolves to a bare ident or a `Class.method`
//! pair, so writing `local n: integer = String.byte("a")` produces the same
//! `NullableToNonNullable` diagnostic as a user-defined function returning
//! `integer?`.

use std::cell::RefCell;
use std::collections::HashMap;
use std::sync::Once;

use saule_ast::Type;

/// A native function's static signature.
#[derive(Clone, Debug)]
pub struct NativeSig {
    /// Declared parameter types (currently unused by the checker; reserved).
    pub params: Vec<Type>,
    /// Declared return types. `len() == 1` for single-return functions;
    /// `len() > 1` for multi-return (surfaced as `Type::Tuple` to callers).
    pub returns: Vec<Type>,
}

thread_local! {
    static SIGS: RefCell<HashMap<String, NativeSig>> = RefCell::new(HashMap::new());
}

/// Register `name -> sig`. Overwrites silently — `install_std` is idempotent
/// per process.
pub fn register(name: &str, params: Vec<Type>, returns: Vec<Type>) {
    SIGS.with(|s| {
        s.borrow_mut().insert(
            name.to_string(),
            NativeSig { params, returns },
        );
    });
}

/// Look up by qualified (`"String.byte"`) or bare (`"assert"`) name.
///
/// The typechecker calls this *before* `install_std` runs in the CLI (since
/// type-checking happens prior to environment construction). To make sigs
/// available regardless of call order, the first lookup triggers a one-shot
/// registration of every stdlib module's signatures.
pub fn lookup(name: &str) -> Option<NativeSig> {
    ensure_registered();
    SIGS.with(|s| s.borrow().get(name).cloned())
}

static REGISTER_ONCE: Once = Once::new();

fn ensure_registered() {
    REGISTER_ONCE.call_once(|| {
        crate::stdlib::core::register_sigs();
        crate::stdlib::math::register_sigs();
        crate::stdlib::string::register_sigs();
        crate::stdlib::iter::register_sigs();
    });
}

// ─── Type-builder shorthands for callers ────────────────────────────────────

pub fn t_named(s: &str) -> Type {
    Type::Named(s.to_string())
}

pub fn t_nullable(inner: Type) -> Type {
    Type::Nullable(Box::new(inner))
}

pub fn t_table(value: Type) -> Type {
    Type::Table { key: None, value: Box::new(value) }
}

pub fn t_table_map(key: Type, value: Type) -> Type {
    Type::Table { key: Some(Box::new(key)), value: Box::new(value) }
}

pub fn t_function(params: Vec<Type>, ret: Type) -> Type {
    Type::Function { params, ret: Box::new(ret) }
}

//! Statement execution with control-flow propagation.

use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

use saule_ast::{ClassMember, Decl, EnumVariant, Expr, ImportNames, Method, Param, Spanned, Stmt};

use crate::env::Environment;
use crate::error::{RuntimeError, unsupported};
use crate::module;
use crate::value::{self, ClassObject, FieldDef, FunctionBody, FunctionObject, InterfaceObject, Value};

use super::{Flow, expr};

/// Execute a sequence of statements in `env`. Stops at the first non-`Normal`
/// outcome and propagates it.
pub fn exec_block(
    stmts: &[Spanned<Stmt>],
    env: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let mut last = Flow::nil();
    for stmt in stmts {
        match exec(stmt, env)? {
            Flow::Normal(v) => last = Flow::Normal(v),
            other => return Ok(other),
        }
    }
    Ok(last)
}

/// Run a block in a fresh child scope. The scope is dropped on return.
fn exec_scoped_block(
    stmts: &[Spanned<Stmt>],
    parent: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let scope = Environment::with_parent(parent.clone());
    exec_block(stmts, &scope)
}

/// Execute a single statement.
pub fn exec(stmt: &Spanned<Stmt>, env: &Rc<RefCell<Environment>>) -> Result<Flow, RuntimeError> {
    let span = stmt.span.clone();
    match &stmt.value {
        Stmt::Local { name, value, .. } => {
            let v = match value {
                Some(e) => expr::eval(e, env)?,
                None => Value::Nil,
            };
            env.borrow_mut().define(name.clone(), v);
            Ok(Flow::nil())
        }

        Stmt::LocalMulti { names, values } => {
            // Evaluate every RHS first so `local a, b = b, a` works at the
            // outer scope. The final expression may expand into multiple
            // return values (Lua-style destructuring semantics).
            let evaluated = eval_expr_list(values, env)?;
            for (i, (name, _)) in names.iter().enumerate() {
                let v = evaluated.get(i).cloned().unwrap_or(Value::Nil);
                env.borrow_mut().define(name.clone(), v);
            }
            Ok(Flow::nil())
        }

        Stmt::Assign { target, value } => exec_assign(target, value, env),

        Stmt::AssignMulti { targets, values } => {
            // Evaluate all RHS expressions first to support parallel
            // semantics (e.g. `a, b = b, a + b`). The final expression may
            // expand into multiple return values.
            let evaluated = eval_expr_list(values, env)?;
            for (i, target) in targets.iter().enumerate() {
                let v = evaluated.get(i).cloned().unwrap_or(Value::Nil);
                assign_target(target, v, env)?;
            }
            Ok(Flow::nil())
        }

        Stmt::Expr(e) => Ok(Flow::Normal(expr::eval(e, env)?)),

        Stmt::If {
            cond,
            then_block,
            elseifs,
            else_block,
        } => {
            if expr::eval(cond, env)?.is_truthy() {
                return exec_scoped_block(then_block, env);
            }
            for (econd, ebody) in elseifs {
                if expr::eval(econd, env)?.is_truthy() {
                    return exec_scoped_block(ebody, env);
                }
            }
            if let Some(eb) = else_block {
                return exec_scoped_block(eb, env);
            }
            Ok(Flow::nil())
        }

        Stmt::While { cond, body } => {
            while expr::eval(cond, env)?.is_truthy() {
                match exec_scoped_block(body, env)? {
                    Flow::Normal(_) | Flow::Continue => continue,
                    Flow::Break => break,
                    ret @ Flow::Return(_) => return Ok(ret),
                }
            }
            Ok(Flow::nil())
        }

        Stmt::Repeat { body, cond } => {
            // Lua semantics: the `until` condition sees locals declared in
            // the body, so condition and body must share the same scope.
            loop {
                let scope = Environment::with_parent(env.clone());
                match exec_block(body, &scope)? {
                    Flow::Normal(_) | Flow::Continue => {}
                    Flow::Break => break,
                    ret @ Flow::Return(_) => return Ok(ret),
                }
                if expr::eval(cond, &scope)?.is_truthy() {
                    break;
                }
            }
            Ok(Flow::nil())
        }

        Stmt::ForNumeric {
            var,
            var_ty: _,
            from,
            to,
            step,
            body,
        } => exec_for_numeric(var, from, to, step.as_ref(), body, env, span),

        Stmt::ForIn { vars, iter, body } => exec_for_in(vars, iter, body, env, span),

        Stmt::Return(exprs) => {
            let values = if exprs.is_empty() {
                vec![Value::Nil]
            } else {
                eval_expr_list(exprs, env)?
            };
            Ok(Flow::Return(values))
        }

        Stmt::Break => Ok(Flow::Break),
        Stmt::Continue => Ok(Flow::Continue),

        Stmt::Throw(_) => Err(unsupported("throw", span)),
        Stmt::Try { .. } => Err(unsupported("try/catch", span)),
        Stmt::Decl(decl) => exec_decl(decl, env),
    }
}

fn eval_expr_list(
    exprs: &[Spanned<Expr>],
    env: &Rc<RefCell<Environment>>,
) -> Result<Vec<Value>, RuntimeError> {
    let mut out = Vec::new();
    for (i, expr_node) in exprs.iter().enumerate() {
        if i + 1 == exprs.len() {
            out.extend(expr::eval_values(expr_node, env)?);
        } else {
            out.push(expr::eval(expr_node, env)?);
        }
    }
    Ok(out)
}

// ─── Declarations ────────────────────────────────────────────────────────────

fn exec_decl(
    decl: &Spanned<Decl>,
    env: &std::rc::Rc<std::cell::RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let span = decl.span.clone();
    match &decl.value {
        Decl::Function {
            name, params, body, ..
        } => {
            let func = FunctionObject {
                name: Some(name.clone()),
                params: params.clone(),
                body: FunctionBody::Block(body.clone()),
                closure: env.clone(),
                owner_class: std::cell::RefCell::new(None),
            };
            env.borrow_mut()
                .define(name.clone(), Value::Function(std::rc::Rc::new(func)));
            Ok(Flow::nil())
        }
        Decl::Class { .. } => exec_class_decl(decl, env),
         Decl::Interface { .. } => exec_interface_decl(decl, env),
         Decl::Enum { name, variants, methods, .. } => exec_enum_decl(name, variants, methods, env, span),
        Decl::Import { names, path } => exec_import(names, path, env, span),
    }
}

/// Materialize a `Decl::Class` into a [`ClassObject`] and install it under
/// the class's name in `env`. Method closures all capture `env` so they can
/// see the class itself (used by static calls) and other top-level names.
fn exec_class_decl(
    decl: &Spanned<Decl>,
    env: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let span = decl.span.clone();
    let Decl::Class {
        name,
        extends,
        implements,
        members,
        ..
    } = &decl.value
    else {
        unreachable!("exec_class_decl called with non-class decl");
    };

    // Resolve parent class, if any. Must already exist in scope.
    let parent = if let Some(pname) = extends {
        match env.borrow().get(pname) {
            Some(Value::Class(c)) => Some(c),
            Some(other) => {
                return Err(RuntimeError::TypeError {
                    message: format!(
                        "cannot extend `{}`: expected a class but got `{}` — check class definition",
                        pname, other.type_name()
                    ),
                    span,
                });
            }
            None => {
                return Err(RuntimeError::Undefined {
                    name: pname.clone(),
                    span,
                });
            }
        }
    } else {
        None
    };

    let mut field_defs: Vec<FieldDef> = Vec::new();
    let mut methods: HashMap<String, Rc<FunctionObject>> = HashMap::new();
    let mut static_fields: HashMap<String, Value> = HashMap::new();
    let mut static_methods: HashMap<String, Rc<FunctionObject>> = HashMap::new();
    let mut constructor: Option<Rc<FunctionObject>> = None;

    // Scan once so we know whether the class has a constructor (`fn init`).
    // When it doesn't, `local field = expr` declarations are promoted to
    // statics so callers can read them via `ClassName.field` (and through
    // the class-as-`self` convention used inside `static fn`s).
    let has_init_method = members.iter().any(|m| match &m.value {
        ClassMember::Method(meth) => meth.name == "init" && !meth.is_static,
        _ => false,
    });

    for member in members {
        match &member.value {
            ClassMember::Field {
                is_static,
                name: fname,
                default,
                ..
            } => {
                // Promote `local field = expr` to a static when there's no
                // constructor — otherwise we'd never be able to read it.
                let treat_as_static = *is_static || (!has_init_method && default.is_some());
                if treat_as_static {
                    // Static defaults are evaluated once, at class
                    // declaration time, in the enclosing scope.
                    let value = match default {
                        Some(e) => expr::eval(e, env)?,
                        None => Value::Nil,
                    };
                    static_fields.insert(fname.clone(), value);
                } else {
                    field_defs.push(FieldDef {
                        name: fname.clone(),
                        default: default.clone(),
                    });
                }
            }
            ClassMember::Method(m) => {
                let func = Rc::new(make_function(
                    Some(format!("{name}.{}", m.name)),
                    m.params.clone(),
                    m.body.clone(),
                    env,
                ));
                if m.is_static {
                    static_methods.insert(m.name.clone(), func);
                } else if m.name == "init" {
                    // `init` is the only constructor spelling — always promote.
                    constructor = Some(func);
                } else {
                    methods.insert(m.name.clone(), func);
                }
            }
        }
    }

    // Validate that all implemented interfaces' required methods are present.
    // Collect ALL missing methods across ALL interfaces so we report them together.
    let mut missing_methods: Vec<(String, String)> = Vec::new(); // (interface_name, method_name)

    for interface_name in implements {
        match env.borrow().get(interface_name) {
            Some(Value::Interface(iface)) => {
                for required_method in &iface.methods {
                    if !methods.contains_key(required_method.0) {
                        missing_methods.push((interface_name.clone(), required_method.0.clone()));
                    }
                }
            }
            Some(_) => {
                return Err(RuntimeError::TypeError {
                    message: format!(
                        "cannot implement `{}`: expected an interface but got something else",
                        interface_name
                    ),
                    span,
                });
            }
            None => {
                return Err(RuntimeError::Undefined {
                    name: interface_name.clone(),
                    span,
                });
            }
        }
    }

    // Report all missing methods at once
    if !missing_methods.is_empty() {
        let missing_list = missing_methods
            .iter()
            .map(|(iface, method)| format!("`{}` from interface `{}`", method, iface))
            .collect::<Vec<_>>()
            .join(", ");
        return Err(RuntimeError::TypeError {
            message: format!(
                "class `{}` is missing method{}: {}",
                name,
                if missing_methods.len() == 1 { "" } else { "s" },
                missing_list
            ),
            span,
        });
    }

    let class = Rc::new(ClassObject {
        name: name.clone(),
        parent,
        field_defs,
        methods,
        static_fields: RefCell::new(static_fields),
        static_methods,
        constructor,
    });

    env.borrow_mut().define(name.clone(), Value::Class(class));
    Ok(Flow::nil())
 }

 /// Execute an interface declaration and install it in the environment.
 fn exec_interface_decl(
     decl: &Spanned<Decl>,
     env: &Rc<RefCell<Environment>>,
 ) -> Result<Flow, RuntimeError> {
     let Decl::Interface {
         name,
         extends,
         methods,
         ..
     } = &decl.value
     else {
         unreachable!("exec_interface_decl called with non-interface decl");
     };

     // Build a map of method signatures from the interface.
     // For now, we just store the method name and parameter count for basic validation.
     let mut method_sigs = HashMap::new();
     for method in methods {
         let param_count = method.params.len();
         let has_return_type = method.return_ty.is_some();
         method_sigs.insert(method.name.clone(), (param_count, has_return_type));
     }

     let interface_obj = Rc::new(InterfaceObject {
         name: name.clone(),
         extends: extends.clone(),
         methods: method_sigs,
     });

     env.borrow_mut()
         .define(name.clone(), Value::Interface(interface_obj));
     Ok(Flow::nil())
 }

 fn make_function(
    name: Option<String>,
    params: Vec<Param>,
    body: Vec<Spanned<Stmt>>,
    closure: &Rc<RefCell<Environment>>,
) -> FunctionObject {
    let _ = closure; // silence unused if we change capture
    FunctionObject {
        name,
        params,
        body: FunctionBody::Block(body),
        closure: closure.clone(),
        owner_class: std::cell::RefCell::new(None),
    }
}

fn exec_enum_decl(
    enum_name: &str,
    variants: &[Spanned<EnumVariant>],
    methods: &[Method],
    env: &Rc<RefCell<Environment>>,
    _span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    let mut variant_dict = HashMap::new();
    let mut enum_methods = HashMap::new();

    for method in methods {
        let func = Rc::new(make_function(
            Some(format!("{enum_name}.{}", method.name)),
            method.params.clone(),
            method.body.clone(),
            env,
        ));
        enum_methods.insert(method.name.clone(), func);
    }

    // Create all variants (without enum references initially)
    for variant in variants {
        match &variant.value {
            EnumVariant::Bare(name) => {
                let variant_obj = Rc::new(value::EnumVariantObject {
                    enum_name: enum_name.to_string(),
                    variant_name: name.clone(),
                    value: None,
                    enum_obj: RefCell::new(None),
                });
                variant_dict.insert(name.clone(), variant_obj);
            }
            EnumVariant::Valued(name, expr) => {
                let val = expr::eval(expr, env)?;
                let variant_obj = Rc::new(value::EnumVariantObject {
                    enum_name: enum_name.to_string(),
                    variant_name: name.clone(),
                    value: Some(val),
                    enum_obj: RefCell::new(None),
                });
                variant_dict.insert(name.clone(), variant_obj);
            }
        }
    }

    // Create the final enum object with all variants
    let final_enum = Rc::new(value::EnumObject {
        name: enum_name.to_string(),
        variants: variant_dict.clone(),
        methods: enum_methods,
    });

    // Now update each variant to reference the enum
    for variant in variant_dict.values() {
        *variant.enum_obj.borrow_mut() = Some(final_enum.clone());
    }

    env.borrow_mut()
        .define(enum_name.to_string(), Value::Enum(final_enum));
    Ok(Flow::nil())
}

// ─── Imports ─────────────────────────────────────────────────────────────────

/// Execute `import ... from "path"`:
///   1. Resolve `path` relative to the importing file's directory.
///   2. Load (or fetch cached) exports for that module via the shared
///      [`module::ModuleLoader`].
///   3. Bind the requested names — optionally aliased — into `env`.
fn exec_import(
    names: &ImportNames,
    path: &str,
    env: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    let loader = env.borrow().loader().ok_or_else(|| RuntimeError::ImportError {
        message: "no module loader available — running this file with `saule run` should attach one".to_string(),
        span: span.clone(),
    })?;
    let dir = env.borrow().module_dir().ok_or_else(|| RuntimeError::ImportError {
        message: "cannot resolve relative import: current file has no known directory".to_string(),
        span: span.clone(),
    })?;

    let abs = module::resolve_import_path(&dir, path).ok_or_else(|| RuntimeError::ImportError {
        message: format!(
            "could not find module `{path}` (looked for `.sau` / `.saule` / `init.sau`)"
        ),
        span: span.clone(),
    })?;

    let exports = module::load_module(&abs, &loader, span.clone())?;

    match names {
        ImportNames::All => {
            for (n, v) in &exports.values {
                env.borrow_mut().define(n.clone(), v.clone());
            }
        }
        ImportNames::List(list) => {
            for (n, alias) in list {
                let v = exports.values.get(n).cloned().ok_or_else(|| {
                    RuntimeError::ImportError {
                        message: format!(
                            "`{n}` is not exported from `{}`",
                            abs.display()
                        ),
                        span: span.clone(),
                    }
                })?;
                let bind = alias.clone().unwrap_or_else(|| n.clone());
                env.borrow_mut().define(bind, v);
            }
        }
    }

    Ok(Flow::nil())
}

// ─── Assignment ──────────────────────────────────────────────────────────────

fn exec_assign(
    target: &Spanned<Expr>,
    value: &Spanned<Expr>,
    env: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let v = expr::eval(value, env)?;
    assign_target(target, v, env)
}

fn assign_target(
    target: &Spanned<Expr>,
    v: Value,
    env: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    match &target.value {
        Expr::Ident(name) => {
            if env.borrow_mut().assign(name, v) {
                Ok(Flow::nil())
            } else {
                Err(RuntimeError::AssignUndeclared {
                    name: name.clone(),
                    span: target.span.clone(),
                })
            }
        }
        // `obj.field = v` / `Class.static = v`
        Expr::Member { obj, name } => {
            let receiver = expr::eval(obj, env)?;
            assign_member(&receiver, name, v, target.span.clone())
        }
        Expr::Index { obj, index } => {
            let receiver = expr::eval(obj, env)?;
            let index_value = expr::eval(index, env)?;
            assign_index(&receiver, index_value, v, target.span.clone())
        }
        _ => Err(RuntimeError::InvalidAssignTarget {
            span: target.span.clone(),
        }),
    }
}

fn assign_member(
    receiver: &Value,
    name: &str,
    value: Value,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    match receiver {
        Value::Instance(inst) => {
            inst.borrow_mut().fields.insert(name.to_string(), value);
            Ok(Flow::nil())
        }
        Value::Class(class) => {
            // Walk the chain — `Child.staticField = …` should update the
            // declaring class so the change is visible to every sibling.
            if set_static_in_chain(class, name, value.clone()) {
                Ok(Flow::nil())
            } else {
                // Define a fresh static on the most-derived class.
                class
                    .static_fields
                    .borrow_mut()
                    .insert(name.to_string(), value);
                Ok(Flow::nil())
            }
        }
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot assign field `{name}` on value of type `{}` — only instances and classes can have fields assigned",
                other.type_name()
            ),
            span,
        }),
    }
}

fn set_static_in_chain(class: &Rc<crate::value::ClassObject>, name: &str, value: Value) -> bool {
    if class.static_fields.borrow().contains_key(name) {
        class
            .static_fields
            .borrow_mut()
            .insert(name.to_string(), value);
        return true;
    }
    if let Some(parent) = &class.parent {
        return set_static_in_chain(parent, name, value);
    }
    false
}

fn assign_index(
    receiver: &Value,
    index: Value,
    value: Value,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    match receiver {
        Value::Table(items) => {
            items
                .borrow_mut()
                .set(&index, value)
                .map_err(|message| RuntimeError::TypeError {
                    message,
                    span: span.clone(),
                })?;
            Ok(Flow::nil())
        }
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot assign through `[index]` on a `{}` — only tables support indexed assignment",
                other.type_name()
            ),
            span,
        }),
    }
}

// ─── Numeric for ─────────────────────────────────────────────────────────────

fn exec_for_numeric(
    var: &str,
    from: &Spanned<Expr>,
    to: &Spanned<Expr>,
    step: Option<&Spanned<Expr>>,
    body: &[Spanned<Stmt>],
    env: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    let from_v = expr::eval(from, env)?;
    let to_v = expr::eval(to, env)?;
    let step_v = match step {
        Some(e) => expr::eval(e, env)?,
        // Default step matches the loop's numeric type.
        None => match &from_v {
            Value::Float(_) => Value::Float(1.0),
            _ => Value::Int(1),
        },
    };

    match (from_v, to_v, step_v) {
        (Value::Int(f), Value::Int(t), Value::Int(s)) => {
            if s == 0 {
                return Err(RuntimeError::ZeroStep { span });
            }
            run_numeric_loop_int(var, f, t, s, body, env)
        }
        (Value::Float(f), Value::Float(t), Value::Float(s)) => {
            if s == 0.0 {
                return Err(RuntimeError::ZeroStep { span });
            }
            run_numeric_loop_float(var, f, t, s, body, env)
        }
        (f, t, s) => Err(RuntimeError::TypeError {
            message: format!(
                "numeric `for` loop requires all bounds (from, to, step) to be the same numeric type — got `{}`, `{}`, `{}` (use matching integer or float bounds)",
                f.type_name(),
                t.type_name(),
                s.type_name()
            ),
            span,
        }),
    }
}

fn run_numeric_loop_int(
    var: &str,
    from: i64,
    to: i64,
    step: i64,
    body: &[Spanned<Stmt>],
    parent: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let mut i = from;
    while (step > 0 && i <= to) || (step < 0 && i >= to) {
        let scope = Environment::with_parent(parent.clone());
        scope.borrow_mut().define(var.to_string(), Value::Int(i));
        match exec_block(body, &scope)? {
            Flow::Normal(_) | Flow::Continue => {}
            Flow::Break => return Ok(Flow::nil()),
            ret @ Flow::Return(_) => return Ok(ret),
        }
        // Detect overflow so a too-large step doesn't loop forever.
        let (next, overflow) = i.overflowing_add(step);
        if overflow {
            break;
        }
        i = next;
    }
    Ok(Flow::nil())
}

fn run_numeric_loop_float(
    var: &str,
    from: f64,
    to: f64,
    step: f64,
    body: &[Spanned<Stmt>],
    parent: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let mut i = from;
    while (step > 0.0 && i <= to) || (step < 0.0 && i >= to) {
        let scope = Environment::with_parent(parent.clone());
        scope.borrow_mut().define(var.to_string(), Value::Float(i));
        match exec_block(body, &scope)? {
            Flow::Normal(_) | Flow::Continue => {}
            Flow::Break => return Ok(Flow::nil()),
            ret @ Flow::Return(_) => return Ok(ret),
        }
        i += step;
    }
    Ok(Flow::nil())
}

fn exec_for_in(
    vars: &[(String, Option<saule_ast::Type>)],
    iter: &Spanned<Expr>,
    body: &[Spanned<Stmt>],
    env: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    let iter_value = expr::eval(iter, env)?;
    match iter_value {
        Value::Table(items) => {
            // Snapshot to allow the table to mutate during iteration without
            // breaking the loop. Yield array entries first, then map entries.
            let (array, map_entries) = {
                let t = items.borrow();
                let array = t.array.clone();
                let mut map_entries: Vec<(crate::value::TableKey, Value)> =
                    t.map.iter().map(|(k, v)| (k.clone(), v.clone())).collect();
                // Deterministic order: int keys ascending, then strings, then bools.
                map_entries.sort_by(|a, b| match (&a.0, &b.0) {
                    (crate::value::TableKey::Int(x), crate::value::TableKey::Int(y)) => x.cmp(y),
                    (crate::value::TableKey::Int(_), _) => std::cmp::Ordering::Less,
                    (_, crate::value::TableKey::Int(_)) => std::cmp::Ordering::Greater,
                    (crate::value::TableKey::Str(x), crate::value::TableKey::Str(y)) => x.cmp(y),
                    (crate::value::TableKey::Str(_), _) => std::cmp::Ordering::Less,
                    (_, crate::value::TableKey::Str(_)) => std::cmp::Ordering::Greater,
                    (crate::value::TableKey::Bool(x), crate::value::TableKey::Bool(y)) => x.cmp(y),
                });
                (array, map_entries)
            };

            // Helper to bind one (key, value) pair and run the body.
            let run_iter = |key: Value, value: Value| -> Result<Flow, RuntimeError> {
                let scope = Environment::with_parent(env.clone());
                match vars {
                    [(name, _)] => {
                        scope.borrow_mut().define(name.clone(), value);
                    }
                    [(key_name, _), (value_name, _)] => {
                        scope.borrow_mut().define(key_name.clone(), key);
                        scope.borrow_mut().define(value_name.clone(), value);
                    }
                    _ => {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "for-in loops support one value variable or a key/value pair, got {} variables",
                                vars.len()
                            ),
                            span: span.clone(),
                        });
                    }
                }
                exec_block(body, &scope)
            };

            for (i, value) in array.into_iter().enumerate() {
                match run_iter(Value::Int((i + 1) as i64), value)? {
                    Flow::Normal(_) | Flow::Continue => {}
                    Flow::Break => return Ok(Flow::nil()),
                    ret @ Flow::Return(_) => return Ok(ret),
                }
            }
            for (k, v) in map_entries {
                match run_iter(k.to_value(), v)? {
                    Flow::Normal(_) | Flow::Continue => {}
                    Flow::Break => return Ok(Flow::nil()),
                    ret @ Flow::Return(_) => return Ok(ret),
                }
            }
            Ok(Flow::nil())
        }
        other => {
            // For functions and instances we drive a closure-based iterator.
            // Instances must expose an `iter()` method that returns the closure.
            let driver: Value = match &other {
                Value::Function(_) | Value::Native(_) | Value::NativeClosure(_) => other.clone(),
                Value::Instance(_) => {
                    let result = expr::invoke_method_multi(
                        &other,
                        "iter",
                        Vec::new(),
                        span.clone(),
                    )?;
                    let Some(driver) = result.into_iter().next() else {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "`{}.iter()` returned no value — it must return a function",
                                other.type_name()
                            ),
                            span,
                        });
                    };
                    if !matches!(driver, Value::Function(_) | Value::Native(_) | Value::NativeClosure(_)) {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "`iter()` must return a function, got `{}`",
                                driver.type_name()
                            ),
                            span,
                        });
                    }
                    driver
                }
                _ => {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "cannot iterate over a `{}` with `for ... in` — use a table, a function, or a class that implements `Iterable`",
                            other.type_name()
                        ),
                        span,
                    });
                }
            };

            // Drive the closure: call repeatedly with no arguments. Stop when
            // the first returned value is `nil` (Lua's nil-terminator). Each
            // step's returns are bound positionally across the loop variables
            // (extras → nil, surplus values dropped).
            loop {
                let values = expr::call_value_multi(driver.clone(), &[], span.clone())?;
                if values.first().is_none_or(|v| matches!(v, Value::Nil)) {
                    break;
                }
                let scope = Environment::with_parent(env.clone());
                {
                    let mut scope_mut = scope.borrow_mut();
                    for (i, (name, _)) in vars.iter().enumerate() {
                        let v = values.get(i).cloned().unwrap_or(Value::Nil);
                        scope_mut.define(name.clone(), v);
                    }
                }
                match exec_block(body, &scope)? {
                    Flow::Normal(_) | Flow::Continue => {}
                    Flow::Break => return Ok(Flow::nil()),
                    ret @ Flow::Return(_) => return Ok(ret),
                }
            }
            Ok(Flow::nil())
        }
    }
}

//! Statement execution with control-flow propagation.

use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

use saule_ast::{ClassMember, Decl, EnumVariant, Expr, ImportNames, Method, Param, Spanned, Stmt};

use crate::env::Environment;
use crate::error::{RuntimeError, unsupported};
use crate::module;
use crate::value::{self, ClassObject, FieldDef, FunctionBody, FunctionObject, InterfaceObject, Value};

use super::{Flow, expr};

/// Execute a sequence of statements in `env`. Stops at the first non-`Normal`
/// outcome and propagates it.
pub fn exec_block(
    stmts: &[Spanned<Stmt>],
    env: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let mut last = Flow::nil();
    for stmt in stmts {
        match exec(stmt, env)? {
            Flow::Normal(v) => last = Flow::Normal(v),
            other => return Ok(other),
        }
    }
    Ok(last)
}

/// Run a block in a fresh child scope. The scope is dropped on return.
fn exec_scoped_block(
    stmts: &[Spanned<Stmt>],
    parent: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let scope = Environment::with_parent(parent.clone());
    exec_block(stmts, &scope)
}

/// Execute a single statement.
pub fn exec(stmt: &Spanned<Stmt>, env: &Rc<RefCell<Environment>>) -> Result<Flow, RuntimeError> {
    let span = stmt.span.clone();
    match &stmt.value {
        Stmt::Local { name, value, .. } => {
            let v = match value {
                Some(e) => expr::eval(e, env)?,
                None => Value::Nil,
            };
            env.borrow_mut().define(name.clone(), v);
            Ok(Flow::nil())
        }

        Stmt::LocalMulti { names, values } => {
            // Evaluate every RHS first so `local a, b = b, a` works at the
            // outer scope. The final expression may expand into multiple
            // return values (Lua-style destructuring semantics).
            let evaluated = eval_expr_list(values, env)?;
            for (i, (name, _)) in names.iter().enumerate() {
                let v = evaluated.get(i).cloned().unwrap_or(Value::Nil);
                env.borrow_mut().define(name.clone(), v);
            }
            Ok(Flow::nil())
        }

        Stmt::Assign { target, value } => exec_assign(target, value, env),

        Stmt::AssignMulti { targets, values } => {
            // Evaluate all RHS expressions first to support parallel
            // semantics (e.g. `a, b = b, a + b`). The final expression may
            // expand into multiple return values.
            let evaluated = eval_expr_list(values, env)?;
            for (i, target) in targets.iter().enumerate() {
                let v = evaluated.get(i).cloned().unwrap_or(Value::Nil);
                assign_target(target, v, env)?;
            }
            Ok(Flow::nil())
        }

        Stmt::Expr(e) => Ok(Flow::Normal(expr::eval(e, env)?)),

        Stmt::If {
            cond,
            then_block,
            elseifs,
            else_block,
        } => {
            if expr::eval(cond, env)?.is_truthy() {
                return exec_scoped_block(then_block, env);
            }
            for (econd, ebody) in elseifs {
                if expr::eval(econd, env)?.is_truthy() {
                    return exec_scoped_block(ebody, env);
                }
            }
            if let Some(eb) = else_block {
                return exec_scoped_block(eb, env);
            }
            Ok(Flow::nil())
        }

        Stmt::While { cond, body } => {
            while expr::eval(cond, env)?.is_truthy() {
                match exec_scoped_block(body, env)? {
                    Flow::Normal(_) | Flow::Continue => continue,
                    Flow::Break => break,
                    ret @ Flow::Return(_) => return Ok(ret),
                }
            }
            Ok(Flow::nil())
        }

        Stmt::Repeat { body, cond } => {
            // Lua semantics: the `until` condition sees locals declared in
            // the body, so condition and body must share the same scope.
            loop {
                let scope = Environment::with_parent(env.clone());
                match exec_block(body, &scope)? {
                    Flow::Normal(_) | Flow::Continue => {}
                    Flow::Break => break,
                    ret @ Flow::Return(_) => return Ok(ret),
                }
                if expr::eval(cond, &scope)?.is_truthy() {
                    break;
                }
            }
            Ok(Flow::nil())
        }

        Stmt::ForNumeric {
            var,
            var_ty: _,
            from,
            to,
            step,
            body,
        } => exec_for_numeric(var, from, to, step.as_ref(), body, env, span),

        Stmt::ForIn { vars, iter, body } => exec_for_in(vars, iter, body, env, span),

        Stmt::Return(exprs) => {
            let values = if exprs.is_empty() {
                vec![Value::Nil]
            } else {
                eval_expr_list(exprs, env)?
            };
            Ok(Flow::Return(values))
        }

        Stmt::Break => Ok(Flow::Break),
        Stmt::Continue => Ok(Flow::Continue),

        Stmt::Throw(_) => Err(unsupported("throw", span)),
        Stmt::Try { .. } => Err(unsupported("try/catch", span)),
        Stmt::Decl(decl) => exec_decl(decl, env),
    }
}

fn eval_expr_list(
    exprs: &[Spanned<Expr>],
    env: &Rc<RefCell<Environment>>,
) -> Result<Vec<Value>, RuntimeError> {
    let mut out = Vec::new();
    for (i, expr_node) in exprs.iter().enumerate() {
        if i + 1 == exprs.len() {
            out.extend(expr::eval_values(expr_node, env)?);
        } else {
            out.push(expr::eval(expr_node, env)?);
        }
    }
    Ok(out)
}

// ─── Declarations ────────────────────────────────────────────────────────────

fn exec_decl(
    decl: &Spanned<Decl>,
    env: &std::rc::Rc<std::cell::RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let span = decl.span.clone();
    match &decl.value {
        Decl::Function {
            name, params, body, ..
        } => {
            let func = FunctionObject {
                name: Some(name.clone()),
                params: params.clone(),
                body: FunctionBody::Block(body.clone()),
                closure: env.clone(),
                owner_class: std::cell::RefCell::new(None),
            };
            env.borrow_mut()
                .define(name.clone(), Value::Function(std::rc::Rc::new(func)));
            Ok(Flow::nil())
        }
        Decl::Class { .. } => exec_class_decl(decl, env),
         Decl::Interface { .. } => exec_interface_decl(decl, env),
         Decl::Enum { name, variants, methods, .. } => exec_enum_decl(name, variants, methods, env, span),
        Decl::Import { names, path } => exec_import(names, path, env, span),
    }
}

/// Materialize a `Decl::Class` into a [`ClassObject`] and install it under
/// the class's name in `env`. Method closures all capture `env` so they can
/// see the class itself (used by static calls) and other top-level names.
fn exec_class_decl(
    decl: &Spanned<Decl>,
    env: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let span = decl.span.clone();
    let Decl::Class {
        name,
        extends,
        implements,
        members,
        ..
    } = &decl.value
    else {
        unreachable!("exec_class_decl called with non-class decl");
    };

    // Resolve parent class, if any. Must already exist in scope.
    let parent = if let Some(pname) = extends {
        match env.borrow().get(pname) {
            Some(Value::Class(c)) => Some(c),
            Some(other) => {
                return Err(RuntimeError::TypeError {
                    message: format!(
                        "cannot extend `{}`: expected a class but got `{}` — check class definition",
                        pname, other.type_name()
                    ),
                    span,
                });
            }
            None => {
                return Err(RuntimeError::Undefined {
                    name: pname.clone(),
                    span,
                });
            }
        }
    } else {
        None
    };

    let mut field_defs: Vec<FieldDef> = Vec::new();
    let mut methods: HashMap<String, Rc<FunctionObject>> = HashMap::new();
    let mut static_fields: HashMap<String, Value> = HashMap::new();
    let mut static_methods: HashMap<String, Rc<FunctionObject>> = HashMap::new();
    let mut constructor: Option<Rc<FunctionObject>> = None;

    // Scan once so we know whether the class has a constructor (`fn init`).
    // When it doesn't, `local field = expr` declarations are promoted to
    // statics so callers can read them via `ClassName.field` (and through
    // the class-as-`self` convention used inside `static fn`s).
    let has_init_method = members.iter().any(|m| match &m.value {
        ClassMember::Method(meth) => meth.name == "init" && !meth.is_static,
        _ => false,
    });

    for member in members {
        match &member.value {
            ClassMember::Field {
                is_static,
                name: fname,
                default,
                ..
            } => {
                // Promote `local field = expr` to a static when there's no
                // constructor — otherwise we'd never be able to read it.
                let treat_as_static = *is_static || (!has_init_method && default.is_some());
                if treat_as_static {
                    // Static defaults are evaluated once, at class
                    // declaration time, in the enclosing scope.
                    let value = match default {
                        Some(e) => expr::eval(e, env)?,
                        None => Value::Nil,
                    };
                    static_fields.insert(fname.clone(), value);
                } else {
                    field_defs.push(FieldDef {
                        name: fname.clone(),
                        default: default.clone(),
                    });
                }
            }
            ClassMember::Method(m) => {
                let func = Rc::new(make_function(
                    Some(format!("{name}.{}", m.name)),
                    m.params.clone(),
                    m.body.clone(),
                    env,
                ));
                if m.is_static {
                    static_methods.insert(m.name.clone(), func);
                } else if m.name == "init" {
                    // `init` is the only constructor spelling — always promote.
                    constructor = Some(func);
                } else {
                    methods.insert(m.name.clone(), func);
                }
            }
        }
    }

    // Validate that all implemented interfaces' required methods are present.
    // Collect ALL missing methods across ALL interfaces so we report them together.
    let mut missing_methods: Vec<(String, String)> = Vec::new(); // (interface_name, method_name)

    for interface_name in implements {
        match env.borrow().get(interface_name) {
            Some(Value::Interface(iface)) => {
                for required_method in &iface.methods {
                    if !methods.contains_key(required_method.0) {
                        missing_methods.push((interface_name.clone(), required_method.0.clone()));
                    }
                }
            }
            Some(_) => {
                return Err(RuntimeError::TypeError {
                    message: format!(
                        "cannot implement `{}`: expected an interface but got something else",
                        interface_name
                    ),
                    span,
                });
            }
            None => {
                return Err(RuntimeError::Undefined {
                    name: interface_name.clone(),
                    span,
                });
            }
        }
    }

    // Report all missing methods at once
    if !missing_methods.is_empty() {
        let missing_list = missing_methods
            .iter()
            .map(|(iface, method)| format!("`{}` from interface `{}`", method, iface))
            .collect::<Vec<_>>()
            .join(", ");
        return Err(RuntimeError::TypeError {
            message: format!(
                "class `{}` is missing method{}: {}",
                name,
                if missing_methods.len() == 1 { "" } else { "s" },
                missing_list
            ),
            span,
        });
    }

    let class = Rc::new(ClassObject {
        name: name.clone(),
        parent,
        field_defs,
        methods,
        static_fields: RefCell::new(static_fields),
        static_methods,
        constructor,
    });

    // Back-link every method to its owning class so calls to a method via a
    // bare `Value::Function` (e.g. inside another static method that resolved
    // a sibling via `inject_class_statics`) still see the class's statics.
    for f in class.methods.values() {
        f.set_owner_class(&class);
    }
    for f in class.static_methods.values() {
        f.set_owner_class(&class);
    }
    if let Some(c) = class.constructor.as_ref() {
        c.set_owner_class(&class);
    }

    env.borrow_mut().define(name.clone(), Value::Class(class));
    Ok(Flow::nil())
 }

 /// Execute an interface declaration and install it in the environment.
 fn exec_interface_decl(
     decl: &Spanned<Decl>,
     env: &Rc<RefCell<Environment>>,
 ) -> Result<Flow, RuntimeError> {
     let Decl::Interface {
         name,
         extends,
         methods,
         ..
     } = &decl.value
     else {
         unreachable!("exec_interface_decl called with non-interface decl");
     };

     // Build a map of method signatures from the interface.
     // For now, we just store the method name and parameter count for basic validation.
     let mut method_sigs = HashMap::new();
     for method in methods {
         let param_count = method.params.len();
         let has_return_type = method.return_ty.is_some();
         method_sigs.insert(method.name.clone(), (param_count, has_return_type));
     }

     let interface_obj = Rc::new(InterfaceObject {
         name: name.clone(),
         extends: extends.clone(),
         methods: method_sigs,
     });

     env.borrow_mut()
         .define(name.clone(), Value::Interface(interface_obj));
     Ok(Flow::nil())
 }

 fn make_function(
    name: Option<String>,
    params: Vec<Param>,
    body: Vec<Spanned<Stmt>>,
    closure: &Rc<RefCell<Environment>>,
) -> FunctionObject {
    let _ = closure; // silence unused if we change capture
    FunctionObject {
        name,
        params,
        body: FunctionBody::Block(body),
        closure: closure.clone(),
        owner_class: std::cell::RefCell::new(None),
    }
}

fn exec_enum_decl(
    enum_name: &str,
    variants: &[Spanned<EnumVariant>],
    methods: &[Method],
    env: &Rc<RefCell<Environment>>,
    _span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    let mut variant_dict = HashMap::new();
    let mut enum_methods = HashMap::new();

    for method in methods {
        let func = Rc::new(make_function(
            Some(format!("{enum_name}.{}", method.name)),
            method.params.clone(),
            method.body.clone(),
            env,
        ));
        enum_methods.insert(method.name.clone(), func);
    }

    // Create all variants (without enum references initially)
    for variant in variants {
        match &variant.value {
            EnumVariant::Bare(name) => {
                let variant_obj = Rc::new(value::EnumVariantObject {
                    enum_name: enum_name.to_string(),
                    variant_name: name.clone(),
                    value: None,
                    enum_obj: RefCell::new(None),
                });
                variant_dict.insert(name.clone(), variant_obj);
            }
            EnumVariant::Valued(name, expr) => {
                let val = expr::eval(expr, env)?;
                let variant_obj = Rc::new(value::EnumVariantObject {
                    enum_name: enum_name.to_string(),
                    variant_name: name.clone(),
                    value: Some(val),
                    enum_obj: RefCell::new(None),
                });
                variant_dict.insert(name.clone(), variant_obj);
            }
        }
    }

    // Create the final enum object with all variants
    let final_enum = Rc::new(value::EnumObject {
        name: enum_name.to_string(),
        variants: variant_dict.clone(),
        methods: enum_methods,
    });

    // Now update each variant to reference the enum
    for variant in variant_dict.values() {
        *variant.enum_obj.borrow_mut() = Some(final_enum.clone());
    }

    env.borrow_mut()
        .define(enum_name.to_string(), Value::Enum(final_enum));
    Ok(Flow::nil())
}

// ─── Imports ─────────────────────────────────────────────────────────────────

/// Execute `import ... from "path"`:
///   1. Resolve `path` relative to the importing file's directory.
///   2. Load (or fetch cached) exports for that module via the shared
///      [`module::ModuleLoader`].
///   3. Bind the requested names — optionally aliased — into `env`.
fn exec_import(
    names: &ImportNames,
    path: &str,
    env: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    let loader = env.borrow().loader().ok_or_else(|| RuntimeError::ImportError {
        message: "no module loader available — running this file with `saule run` should attach one".to_string(),
        span: span.clone(),
    })?;
    let dir = env.borrow().module_dir().ok_or_else(|| RuntimeError::ImportError {
        message: "cannot resolve relative import: current file has no known directory".to_string(),
        span: span.clone(),
    })?;

    let abs = module::resolve_import_path(&dir, path).ok_or_else(|| RuntimeError::ImportError {
        message: format!(
            "could not find module `{path}` (looked for `.sau` / `.saule` / `init.sau`)"
        ),
        span: span.clone(),
    })?;

    let exports = module::load_module(&abs, &loader, span.clone())?;

    match names {
        ImportNames::All => {
            for (n, v) in &exports.values {
                env.borrow_mut().define(n.clone(), v.clone());
            }
        }
        ImportNames::List(list) => {
            for (n, alias) in list {
                let v = exports.values.get(n).cloned().ok_or_else(|| {
                    RuntimeError::ImportError {
                        message: format!(
                            "`{n}` is not exported from `{}`",
                            abs.display()
                        ),
                        span: span.clone(),
                    }
                })?;
                let bind = alias.clone().unwrap_or_else(|| n.clone());
                env.borrow_mut().define(bind, v);
            }
        }
    }

    Ok(Flow::nil())
}

// ─── Assignment ──────────────────────────────────────────────────────────────

fn exec_assign(
    target: &Spanned<Expr>,
    value: &Spanned<Expr>,
    env: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let v = expr::eval(value, env)?;
    assign_target(target, v, env)
}

fn assign_target(
    target: &Spanned<Expr>,
    v: Value,
    env: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    match &target.value {
        Expr::Ident(name) => {
            if env.borrow_mut().assign(name, v) {
                Ok(Flow::nil())
            } else {
                Err(RuntimeError::AssignUndeclared {
                    name: name.clone(),
                    span: target.span.clone(),
                })
            }
        }
        // `obj.field = v` / `Class.static = v`
        Expr::Member { obj, name } => {
            let receiver = expr::eval(obj, env)?;
            assign_member(&receiver, name, v, target.span.clone())
        }
        Expr::Index { obj, index } => {
            let receiver = expr::eval(obj, env)?;
            let index_value = expr::eval(index, env)?;
            assign_index(&receiver, index_value, v, target.span.clone())
        }
        _ => Err(RuntimeError::InvalidAssignTarget {
            span: target.span.clone(),
        }),
    }
}

fn assign_member(
    receiver: &Value,
    name: &str,
    value: Value,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    match receiver {
        Value::Instance(inst) => {
            inst.borrow_mut().fields.insert(name.to_string(), value);
            Ok(Flow::nil())
        }
        Value::Class(class) => {
            // Walk the chain — `Child.staticField = …` should update the
            // declaring class so the change is visible to every sibling.
            if set_static_in_chain(class, name, value.clone()) {
                Ok(Flow::nil())
            } else {
                // Define a fresh static on the most-derived class.
                class
                    .static_fields
                    .borrow_mut()
                    .insert(name.to_string(), value);
                Ok(Flow::nil())
            }
        }
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot assign field `{name}` on value of type `{}` — only instances and classes can have fields assigned",
                other.type_name()
            ),
            span,
        }),
    }
}

fn set_static_in_chain(class: &Rc<crate::value::ClassObject>, name: &str, value: Value) -> bool {
    if class.static_fields.borrow().contains_key(name) {
        class
            .static_fields
            .borrow_mut()
            .insert(name.to_string(), value);
        return true;
    }
    if let Some(parent) = &class.parent {
        return set_static_in_chain(parent, name, value);
    }
    false
}

fn assign_index(
    receiver: &Value,
    index: Value,
    value: Value,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    match receiver {
        Value::Table(items) => {
            items
                .borrow_mut()
                .set(&index, value)
                .map_err(|message| RuntimeError::TypeError {
                    message,
                    span: span.clone(),
                })?;
            Ok(Flow::nil())
        }
        other => Err(RuntimeError::TypeError {
            message: format!(
                "cannot assign through `[index]` on a `{}` — only tables support indexed assignment",
                other.type_name()
            ),
            span,
        }),
    }
}

// ─── Numeric for ─────────────────────────────────────────────────────────────

fn exec_for_numeric(
    var: &str,
    from: &Spanned<Expr>,
    to: &Spanned<Expr>,
    step: Option<&Spanned<Expr>>,
    body: &[Spanned<Stmt>],
    env: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    let from_v = expr::eval(from, env)?;
    let to_v = expr::eval(to, env)?;
    let step_v = match step {
        Some(e) => expr::eval(e, env)?,
        // Default step matches the loop's numeric type.
        None => match &from_v {
            Value::Float(_) => Value::Float(1.0),
            _ => Value::Int(1),
        },
    };

    match (from_v, to_v, step_v) {
        (Value::Int(f), Value::Int(t), Value::Int(s)) => {
            if s == 0 {
                return Err(RuntimeError::ZeroStep { span });
            }
            run_numeric_loop_int(var, f, t, s, body, env)
        }
        (Value::Float(f), Value::Float(t), Value::Float(s)) => {
            if s == 0.0 {
                return Err(RuntimeError::ZeroStep { span });
            }
            run_numeric_loop_float(var, f, t, s, body, env)
        }
        (f, t, s) => Err(RuntimeError::TypeError {
            message: format!(
                "numeric `for` loop requires all bounds (from, to, step) to be the same numeric type — got `{}`, `{}`, `{}` (use matching integer or float bounds)",
                f.type_name(),
                t.type_name(),
                s.type_name()
            ),
            span,
        }),
    }
}

fn run_numeric_loop_int(
    var: &str,
    from: i64,
    to: i64,
    step: i64,
    body: &[Spanned<Stmt>],
    parent: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let mut i = from;
    while (step > 0 && i <= to) || (step < 0 && i >= to) {
        let scope = Environment::with_parent(parent.clone());
        scope.borrow_mut().define(var.to_string(), Value::Int(i));
        match exec_block(body, &scope)? {
            Flow::Normal(_) | Flow::Continue => {}
            Flow::Break => return Ok(Flow::nil()),
            ret @ Flow::Return(_) => return Ok(ret),
        }
        // Detect overflow so a too-large step doesn't loop forever.
        let (next, overflow) = i.overflowing_add(step);
        if overflow {
            break;
        }
        i = next;
    }
    Ok(Flow::nil())
}

fn run_numeric_loop_float(
    var: &str,
    from: f64,
    to: f64,
    step: f64,
    body: &[Spanned<Stmt>],
    parent: &Rc<RefCell<Environment>>,
) -> Result<Flow, RuntimeError> {
    let mut i = from;
    while (step > 0.0 && i <= to) || (step < 0.0 && i >= to) {
        let scope = Environment::with_parent(parent.clone());
        scope.borrow_mut().define(var.to_string(), Value::Float(i));
        match exec_block(body, &scope)? {
            Flow::Normal(_) | Flow::Continue => {}
            Flow::Break => return Ok(Flow::nil()),
            ret @ Flow::Return(_) => return Ok(ret),
        }
        i += step;
    }
    Ok(Flow::nil())
}

fn exec_for_in(
    vars: &[(String, Option<saule_ast::Type>)],
    iter: &Spanned<Expr>,
    body: &[Spanned<Stmt>],
    env: &Rc<RefCell<Environment>>,
    span: std::ops::Range<usize>,
) -> Result<Flow, RuntimeError> {
    let iter_value = expr::eval(iter, env)?;
    match iter_value {
        Value::Table(items) => {
            // Snapshot to allow the table to mutate during iteration without
            // breaking the loop. Yield array entries first, then map entries.
            let (array, map_entries) = {
                let t = items.borrow();
                let array = t.array.clone();
                let mut map_entries: Vec<(crate::value::TableKey, Value)> =
                    t.map.iter().map(|(k, v)| (k.clone(), v.clone())).collect();
                // Deterministic order: int keys ascending, then strings, then bools.
                map_entries.sort_by(|a, b| match (&a.0, &b.0) {
                    (crate::value::TableKey::Int(x), crate::value::TableKey::Int(y)) => x.cmp(y),
                    (crate::value::TableKey::Int(_), _) => std::cmp::Ordering::Less,
                    (_, crate::value::TableKey::Int(_)) => std::cmp::Ordering::Greater,
                    (crate::value::TableKey::Str(x), crate::value::TableKey::Str(y)) => x.cmp(y),
                    (crate::value::TableKey::Str(_), _) => std::cmp::Ordering::Less,
                    (_, crate::value::TableKey::Str(_)) => std::cmp::Ordering::Greater,
                    (crate::value::TableKey::Bool(x), crate::value::TableKey::Bool(y)) => x.cmp(y),
                });
                (array, map_entries)
            };

            // Helper to bind one (key, value) pair and run the body.
            let run_iter = |key: Value, value: Value| -> Result<Flow, RuntimeError> {
                let scope = Environment::with_parent(env.clone());
                match vars {
                    [(name, _)] => {
                        scope.borrow_mut().define(name.clone(), value);
                    }
                    [(key_name, _), (value_name, _)] => {
                        scope.borrow_mut().define(key_name.clone(), key);
                        scope.borrow_mut().define(value_name.clone(), value);
                    }
                    _ => {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "for-in loops support one value variable or a key/value pair, got {} variables",
                                vars.len()
                            ),
                            span: span.clone(),
                        });
                    }
                }
                exec_block(body, &scope)
            };

            for (i, value) in array.into_iter().enumerate() {
                match run_iter(Value::Int((i + 1) as i64), value)? {
                    Flow::Normal(_) | Flow::Continue => {}
                    Flow::Break => return Ok(Flow::nil()),
                    ret @ Flow::Return(_) => return Ok(ret),
                }
            }
            for (k, v) in map_entries {
                match run_iter(k.to_value(), v)? {
                    Flow::Normal(_) | Flow::Continue => {}
                    Flow::Break => return Ok(Flow::nil()),
                    ret @ Flow::Return(_) => return Ok(ret),
                }
            }
            Ok(Flow::nil())
        }
        other => {
            // For functions and instances we drive a closure-based iterator.
            // Instances must expose an `iter()` method that returns the closure.
            let driver: Value = match &other {
                Value::Function(_) | Value::Native(_) | Value::NativeClosure(_) => other.clone(),
                Value::Instance(_) => {
                    let result = expr::invoke_method_multi(
                        &other,
                        "iter",
                        Vec::new(),
                        span.clone(),
                    )?;
                    let Some(driver) = result.into_iter().next() else {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "`{}.iter()` returned no value — it must return a function",
                                other.type_name()
                            ),
                            span,
                        });
                    };
                    if !matches!(driver, Value::Function(_) | Value::Native(_) | Value::NativeClosure(_)) {
                        return Err(RuntimeError::TypeError {
                            message: format!(
                                "`iter()` must return a function, got `{}`",
                                driver.type_name()
                            ),
                            span,
                        });
                    }
                    driver
                }
                _ => {
                    return Err(RuntimeError::TypeError {
                        message: format!(
                            "cannot iterate over a `{}` with `for ... in` — use a table, a function, or a class that implements `Iterable`",
                            other.type_name()
                        ),
                        span,
                    });
                }
            };

            // Drive the closure: call repeatedly with no arguments. Stop when
            // the first returned value is `nil` (Lua's nil-terminator). Each
            // step's returns are bound positionally across the loop variables
            // (extras → nil, surplus values dropped).
            loop {
                let values = expr::call_value_multi(driver.clone(), &[], span.clone())?;
                if values.first().is_none_or(|v| matches!(v, Value::Nil)) {
                    break;
                }
                let scope = Environment::with_parent(env.clone());
                {
                    let mut scope_mut = scope.borrow_mut();
                    for (i, (name, _)) in vars.iter().enumerate() {
                        let v = values.get(i).cloned().unwrap_or(Value::Nil);
                        scope_mut.define(name.clone(), v);
                    }
                }
                match exec_block(body, &scope)? {
                    Flow::Normal(_) | Flow::Continue => {}
                    Flow::Break => return Ok(Flow::nil()),
                    ret @ Flow::Return(_) => return Ok(ret),
                }
            }
            Ok(Flow::nil())
        }
    }
}

//! String standard library — exposed as the static class `String`.

use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

use crate::env::Environment;
use crate::stdlib::{expect_arity, expect_min_arity};
use crate::value::{ClassObject, NativeClosure, Value};

pub fn install(env: &Rc<RefCell<Environment>>) {
    let mut static_fields = HashMap::new();
    static_fields.insert("byte".to_string(),   native("String.byte",   str_byte));
    static_fields.insert("char".to_string(),   native("String.char",   str_char));
    static_fields.insert("format".to_string(), native("String.format", str_format));
    static_fields.insert("len".to_string(),    native("String.len",    str_len));
    static_fields.insert("sub".to_string(),    native("String.sub",    str_sub));
    static_fields.insert("rep".to_string(),    native("String.rep",    str_rep));
    static_fields.insert("starts".to_string(), native("String.starts", str_starts));
    static_fields.insert("ends".to_string(),   native("String.ends",   str_ends));
    static_fields.insert("find".to_string(),   native_multi("String.find", str_find));
    static_fields.insert("lower".to_string(),  native("String.lower",  str_lower));
    static_fields.insert("upper".to_string(),  native("String.upper",  str_upper));
    static_fields.insert("iter".to_string(),   native("String.iter",   str_iter));

    let class = ClassObject {
        name: "String".to_string(),
        parent: None,
        field_defs: Vec::new(),
        methods: HashMap::new(),
        static_fields: RefCell::new(static_fields),
        static_methods: HashMap::new(),
        constructor: None,
    };
    env.borrow_mut()
        .define("String".to_string(), Value::Class(Rc::new(class)));

    // Static signatures consulted by the typechecker.
    use crate::stdlib::sigs::{register, t_named, t_nullable};
    let s   = || t_named("string");
    let i   = || t_named("integer");
    let b   = || t_named("boolean");
    let any = || t_named("any");
    register("String.byte",   vec![s(), t_nullable(i())],         vec![t_nullable(i())]);
    register("String.char",   vec![],                              vec![s()]);
    register("String.format", vec![s()],                           vec![s()]);
    register("String.len",    vec![s()],                           vec![i()]);
    register("String.sub",    vec![s(), i(), t_nullable(i())],     vec![s()]);
    register("String.rep",    vec![s(), i()],                      vec![s()]);
    register("String.starts", vec![s(), s()],                      vec![b()]);
    register("String.ends",   vec![s(), s()],                      vec![b()]);
    register("String.find",   vec![s(), s(), t_nullable(i())],     vec![t_nullable(i()), t_nullable(i())]);
    register("String.lower",  vec![s()],                           vec![s()]);
    register("String.upper",  vec![s()],                           vec![s()]);
    register("String.iter",   vec![s()],                           vec![any()]);  // returns a step closure
}

fn native(name: &'static str, func: fn(&[Value]) -> Result<Value, String>) -> Value {
    Value::Native(Rc::new(crate::value::NativeFn { name, func }))
}

/// Wrap a multi-return native function as a `NativeClosure` so the call
/// site can destructure `local a, b = f(...)`.
fn native_multi(
    name: &'static str,
    func: fn(&[Value]) -> Result<Vec<Value>, String>,
) -> Value {
    Value::NativeClosure(Rc::new(NativeClosure {
        name,
        func: Box::new(move |args| func(args)),
    }))
}

// ─── helpers ────────────────────────────────────────────────────────────────

fn expect_string(name: &str, args: &[Value], idx: usize) -> Result<String, String> {
    match args.get(idx) {
        Some(Value::Str(s)) => Ok((**s).clone()),
        Some(other) => Err(format!(
            "{name} expects a string at argument {}, got `{}`",
            idx + 1,
            other.type_name()
        )),
        None => Err(format!("{name} missing argument {}", idx + 1)),
    }
}

fn expect_int(name: &str, args: &[Value], idx: usize) -> Result<i64, String> {
    match args.get(idx) {
        Some(Value::Int(i)) => Ok(*i),
        Some(other) => Err(format!(
            "{name} expects an integer at argument {}, got `{}`",
            idx + 1,
            other.type_name()
        )),
        None => Err(format!("{name} missing argument {}", idx + 1)),
    }
}

// Lua-style 1-based index with negative-from-end. Clamps to `[1, len]`. The
// returned value is a 0-based byte offset suitable for slicing the `chars`
// vector (so it's "1-based char index minus 1").
fn resolve_index(i: i64, char_count: usize) -> usize {
    let n = char_count as i64;
    let idx = if i < 0 { n + i + 1 } else { i };
    if idx < 1 {
        0
    } else if idx > n {
        char_count
    } else {
        (idx - 1) as usize
    }
}

// ─── functions ──────────────────────────────────────────────────────────────

fn str_byte(args: &[Value]) -> Result<Value, String> {
    expect_min_arity("String.byte", args, 1)?;
    let s = expect_string("String.byte", args, 0)?;
    let chars: Vec<char> = s.chars().collect();
    let pos: i64 = if args.len() >= 2 {
        expect_int("String.byte", args, 1)?
    } else {
        1
    };
    if pos < 1 || (pos as usize) > chars.len() {
        return Ok(Value::Nil);
    }
    let c = chars[(pos as usize) - 1];
    Ok(Value::Int(c as i64))
}

fn str_char(args: &[Value]) -> Result<Value, String> {
    let mut out = String::with_capacity(args.len());
    for (i, arg) in args.iter().enumerate() {
        let code = match arg {
            Value::Int(n) => *n,
            other => {
                return Err(format!(
                    "String.char expects integer arguments, got `{}` at argument {}",
                    other.type_name(),
                    i + 1
                ));
            }
        };
        let Some(c) = u32::try_from(code).ok().and_then(char::from_u32) else {
            return Err(format!(
                "String.char: code {code} at argument {} is not a valid character",
                i + 1
            ));
        };
        out.push(c);
    }
    Ok(Value::Str(Rc::new(out)))
}

fn str_len(args: &[Value]) -> Result<Value, String> {
    expect_arity("String.len", args, 1)?;
    let s = expect_string("String.len", args, 0)?;
    Ok(Value::Int(s.chars().count() as i64))
}

fn str_sub(args: &[Value]) -> Result<Value, String> {
    expect_min_arity("String.sub", args, 2)?;
    let s = expect_string("String.sub", args, 0)?;
    let chars: Vec<char> = s.chars().collect();
    let i = expect_int("String.sub", args, 1)?;
    let j: i64 = if args.len() >= 3 {
        expect_int("String.sub", args, 2)?
    } else {
        chars.len() as i64
    };

    // Resolve to 0-based [start, end) range with Lua semantics.
    let n = chars.len() as i64;
    let mut start = if i < 0 { (n + i + 1).max(1) } else { i.max(1) };
    let mut end = if j < 0 { n + j + 1 } else { j };
    if end > n {
        end = n;
    }
    if start < 1 {
        start = 1;
    }
    if start > end {
        return Ok(Value::Str(Rc::new(String::new())));
    }
    let out: String = chars[(start as usize - 1)..(end as usize)].iter().collect();
    Ok(Value::Str(Rc::new(out)))
}

